/* Hanzi AI biên soạn: bài ngữ pháp cho các điểm HSK 3.0 chưa có bài. Không phải nội dung chính thức. */
window.HSK_GA=[{"id":"a-o-1-002","hsk30_level":"1","official":["o-1-002"],"title":"后缀 —们、—边","py":"Hòu zhuì —men, —biān","func":"语素 › 后缀","struct":"名词/人称代词 + 们；方位词 + 边","vi":"们 biểu thị số nhiều (chỉ người); 边 ghép sau từ phương vị để thành từ chỉ vị trí.","use":"们 dùng sau đại từ nhân xưng và danh từ chỉ người (我们, 朋友们). Không dùng 们 khi đã có số từ cụ thể. 边 ghép với 上/下/里/外/前/后/左/右 thành 上边, 前边... nghĩa gần như 上, 前.","ex":[["同学们好！","Tóngxué men hǎo!","Chào các bạn!"],["学生们都在教室里。","Xuésheng men dōu zài jiàoshì lǐ.","Các học sinh đều ở trong lớp."],["学校前边有一家商店。","Xuéxiào qiánbian yǒu yī jiā shāngdiàn.","Phía trước trường có một cửa hàng."]],"note":"Không nói 三个学生们; chỉ nói 三个学生 hoặc 学生们.","origin":"hanziai-authored"},{"id":"a-o-1-013","hsk30_level":"1","official":["o-1-013"],"title":"借用名量词：杯","py":"Jièyòng míng liàng cí: bēi","func":"词类 › 量词","struct":"数词 + 杯 + 名词","vi":"杯 (cốc, ly) vốn là danh từ, được mượn làm lượng từ để đếm đồ uống đựng trong cốc.","use":"Đặt giữa số từ và danh từ chỉ thức uống: 一杯水, 两杯茶. Hỏi số lượng dùng 几杯.","ex":[["我想喝一杯茶。","Wǒ xiǎng hē yī bēi chá.","Tôi muốn uống một cốc trà."],["她买了两杯咖啡。","Tā mǎi le liǎng bēi kāfēi.","Cô ấy mua hai cốc cà phê."]],"note":"Với số 2 trước lượng từ dùng 两, không dùng 二.","origin":"hanziai-authored"},{"id":"a-o-1-018","hsk30_level":"1","official":["o-1-018"],"title":"再1","py":"Zài1","func":"词类 › 副词","struct":"再 + 动词","vi":"再 biểu thị hành động sẽ lặp lại hoặc tiếp tục trong tương lai.","use":"Đứng trước động từ, nói về việc chưa xảy ra: 再说一遍 (nói lại lần nữa), 明天再来. Với việc đã xảy ra rồi lặp lại, dùng 又 chứ không dùng 再.","ex":[["请你再说一遍。","Qǐng nǐ zàishuō yī biàn.","Xin bạn nói lại một lần nữa."],["今天太晚了，明天我再来。","Jīntiān tài wǎn le, míngtiān wǒ zài lái.","Hôm nay muộn quá, mai tôi lại đến."]],"note":"Phân biệt: 再 (lặp lại trong tương lai) và 又 (đã lặp lại).","origin":"hanziai-authored"},{"id":"a-o-1-028","hsk30_level":"1","official":["o-1-028"],"title":"（1）联合短语","py":"（1）Liánhé duǎn yǔ","func":"短语 › 结构类型","struct":"A + 和/跟/与 + B；A + B (hai thành phần ngang hàng)","vi":"Cụm liên hợp gồm hai hay nhiều thành phần ngang hàng, không thành phần nào bổ nghĩa cho thành phần kia.","use":"Các thành phần cùng loại từ, có thể nối bằng 和 hoặc đặt cạnh nhau (又大又好, 老师和学生).","ex":[["老师和学生都来了。","Lǎoshī hé xuésheng dōu lái le.","Giáo viên và học sinh đều đến rồi."],["这个房间又大又干净。","Zhè ge fángjiān yòu dà yòu gānjìng.","Căn phòng này vừa rộng vừa sạch."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-029","hsk30_level":"1","official":["o-1-029"],"title":"（2）偏正短语","py":"（2）Piān zhèng duǎn yǔ","func":"短语 › 结构类型","struct":"修饰语 + 中心语","vi":"Cụm chính phụ: thành phần phía trước bổ nghĩa cho thành phần chính phía sau.","use":"Định ngữ + danh từ (新书, 我的朋友) hoặc trạng ngữ + động từ/tính từ (很好, 慢慢走). Thành phần chính nằm ở cuối.","ex":[["这是我的新手机。","Zhè shì wǒ de xīnshǒu jī.","Đây là điện thoại mới của tôi."],["他慢慢地走进教室。","Tā mànmàn de zǒujìn jiàoshì.","Anh ấy chầm chậm bước vào lớp."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-030","hsk30_level":"1","official":["o-1-030"],"title":"（3）动宾短语","py":"（3）Dòng bīn duǎn yǔ","func":"短语 › 结构类型","struct":"动词 + 宾语","vi":"Cụm động tân: động từ ở trước, tân ngữ chỉ đối tượng của hành động ở sau.","use":"Tân ngữ thường là danh từ hoặc đại từ: 喝水, 看书, 学汉语.","ex":[["我每天看书。","Wǒ měi tiān kàn shū.","Mỗi ngày tôi đọc sách."],["他在学汉语。","Tā zài xué Hànyǔ.","Anh ấy đang học tiếng Hán."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-031","hsk30_level":"1","official":["o-1-031"],"title":"（4）主谓短语","py":"（4）Zhǔ wèi duǎn yǔ","func":"短语 › 结构类型","struct":"主语 + 谓语","vi":"Cụm chủ vị: vế trước nêu đối tượng, vế sau nói về đối tượng đó.","use":"Có thể đứng độc lập làm câu, hoặc làm thành phần trong câu lớn hơn (我喜欢天气好).","ex":[["天气很好。","Tiānqì hěn hǎo.","Thời tiết rất đẹp."],["我知道他是老师。","Wǒ zhīdào tā shì lǎoshī.","Tôi biết anh ấy là giáo viên."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-032","hsk30_level":"1","official":["o-1-032"],"title":"（1）数量短语","py":"（1）Shùliàng duǎn yǔ","func":"短语 › 结构类型","struct":"数词 + 量词","vi":"Cụm số lượng: số từ ghép với lượng từ.","use":"Dùng trước danh từ (三本书) hoặc sau động từ để đếm số lần (去一次).","ex":[["我有两个哥哥。","Wǒ yǒu liǎng ge gēge.","Tôi có hai người anh."],["请给我一杯水。","Qǐng gěi wǒ yī bēi shuǐ.","Xin cho tôi một cốc nước."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-033","hsk30_level":"1","official":["o-1-033"],"title":"（2）介宾短语","py":"（2）Jiè bīn duǎn yǔ","func":"短语 › 结构类型","struct":"介词 + 宾语","vi":"Cụm giới tân: giới từ cộng với danh từ/đại từ phía sau.","use":"Thường làm trạng ngữ đặt trước động từ: 在北京工作, 对我说.","ex":[["我在北京工作。","Wǒ zài Běijīng gōngzuò.","Tôi làm việc ở Bắc Kinh."],["他对我很好。","Tā duì wǒ hěn hǎo.","Anh ấy rất tốt với tôi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-034","hsk30_level":"1","official":["o-1-034"],"title":"（3）方位短语","py":"（3）Fāngwèi duǎn yǔ","func":"短语 › 结构类型","struct":"名词 + 方位词","vi":"Cụm phương vị: danh từ cộng với từ chỉ phương vị như 上, 下, 里, 外.","use":"Chỉ vị trí của sự vật: 桌子上, 学校里. Thường đứng sau 在 hoặc làm chủ ngữ.","ex":[["书在桌子上。","Shū zài zhuōzi shàng.","Sách ở trên bàn."],["教室里没有人。","Jiàoshì lǐ méiyǒu rén.","Trong lớp không có ai."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-035","hsk30_level":"1","official":["o-1-035"],"title":"名词、代词或名词性短语作主语","py":"Míng cí, dài cí huò míng cí xìng duǎn yǔ zuò zhǔ yǔ","func":"句子成分 › 主语","struct":"主语 (名词/代词/名词性短语) + 谓语","vi":"Chủ ngữ là danh từ, đại từ hoặc cụm danh từ, nêu đối tượng được nói đến.","use":"Chủ ngữ thường đứng đầu câu, trước vị ngữ.","ex":[["我是学生。","Wǒ shì xuésheng.","Tôi là học sinh."],["我的朋友住在上海。","Wǒ de péngyou zhù zài shàng hǎi.","Bạn tôi sống ở Thượng Hải."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-036","hsk30_level":"1","official":["o-1-036"],"title":"名词、代词、数词或数量短语作谓语","py":"Míng cí, dài cí, shù cí huò shùliàng duǎn yǔ zuò wèi yǔ","func":"句子成分 › 谓语","struct":"主语 + 名词/数量短语 (+ 谓语)","vi":"Vị ngữ không phải động từ mà là danh từ, đại từ, số từ hoặc cụm số lượng, thường nói về tuổi, ngày, giá tiền.","use":"Hay gặp khi nói tuổi, ngày tháng, giá: 我二十岁, 今天星期五. Dạng khẳng định thường không cần 是.","ex":[["今天星期五。","Jīntiān xīngqī wǔ.","Hôm nay là thứ Sáu."],["这本书三十块。","Zhè běn shū sān shí kuài.","Quyển sách này ba mươi đồng."]],"note":"Dạng phủ định phải dùng 不是: 今天不是星期五.","origin":"hanziai-authored"},{"id":"a-o-1-037","hsk30_level":"1","official":["o-1-037"],"title":"动词或动词性短语、形容词或形容词性短语作谓语","py":"Dòng cí huò dòng cí xìng duǎn yǔ, xíngróng cí huò xíngróng cí xìng duǎn yǔ zuò wèi yǔ","func":"句子成分 › 谓语","struct":"主语 + 动词(短语)/形容词(短语)","vi":"Vị ngữ là động từ hay tính từ (kể cả cụm), là kiểu vị ngữ phổ biến nhất.","use":"Động từ nói hành động; tính từ nói tính chất, thường có phó từ mức độ như 很 đứng trước.","ex":[["他去学校。","Tā qù xuéxiào.","Anh ấy đi đến trường."],["这个菜很好吃。","Zhè ge cài hěn hǎochī.","Món này rất ngon."]],"note":"Vị ngữ tính từ thường cần 很 hoặc phó từ khác; nói 他高 mang nghĩa so sánh.","origin":"hanziai-authored"},{"id":"a-o-1-038","hsk30_level":"1","official":["o-1-038"],"title":"名词、代词或名词性短语作宾语","py":"Míng cí, dài cí huò míng cí xìng duǎn yǔ zuò bīn yǔ","func":"句子成分 › 宾语","struct":"动词 + 宾语","vi":"Tân ngữ là danh từ, đại từ hoặc cụm danh từ, nêu đối tượng chịu tác động của động từ.","use":"Đứng sau động từ.","ex":[["我喜欢他。","Wǒ xǐhuan tā.","Tôi thích anh ấy."],["妈妈买了一些水果。","Māma mǎi le yīxiē shuǐguǒ.","Mẹ mua một ít hoa quả."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-039","hsk30_level":"1","official":["o-1-039"],"title":"名词性词语、形容词性短语、数量短语作定语","py":"Míng cí xìng cíyǔ, xíngróng cí xìng duǎn yǔ, shùliàng duǎn yǔ zuò dìng yǔ","func":"句子成分 › 定语","struct":"定语 (+ 的) + 名词","vi":"Định ngữ bổ nghĩa cho danh từ, có thể là danh từ, cụm tính từ hoặc cụm số lượng.","use":"Cụm tính từ thường cần 的 (漂亮的衣服); danh từ chỉ sở hữu cũng dùng 的; cụm số lượng không cần 的.","ex":[["这是老师的书。","Zhè shì lǎoshī de shū.","Đây là sách của thầy giáo."],["她穿着一件漂亮的衣服。","Tā chuānzhuó yī jiàn piàoliang de yīfu.","Cô ấy mặc một bộ quần áo đẹp."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-040","hsk30_level":"1","official":["o-1-040"],"title":"副词、形容词作状语 / 表示时间、处所的词语作状语","py":"Fù cí, xíngróng cí zuò zhuàng yǔ / biǎoshì shíjiān, chù suǒ de cíyǔ zuò zhuàng yǔ","func":"句子成分 › 状语","struct":"状语 + 动词/形容词","vi":"Trạng ngữ đứng trước vị ngữ, bổ nghĩa cho nó; có thể là phó từ, tính từ hoặc từ chỉ thời gian, nơi chốn.","use":"Trạng ngữ chỉ thời gian và nơi chốn đứng trước động từ (hoặc đầu câu): 昨天去, 在家看.","ex":[["他很高兴。","Tā hěn gāoxìng.","Anh ấy rất vui."],["我们明天在学校见面。","Wǒmen míngtiān zài xuéxiào jiànmiàn.","Ngày mai chúng ta gặp nhau ở trường."]],"note":"Trạng ngữ đặt trước động từ, không đặt sau như tiếng Việt.","origin":"hanziai-authored"},{"id":"a-o-1-041","hsk30_level":"1","official":["o-1-041"],"title":"数量补语1：动词+动量补语","py":"Shùliàng bǔ yǔ1: dòng cí+dòng liàng bǔ yǔ","func":"句子成分 › 补语","struct":"动词 + 数词 + 动量词","vi":"Bổ ngữ chỉ số lần hành động.","use":"Đứng sau động từ, nói động tác diễn ra bao nhiêu lần (一次, 两遍).","ex":[["我去过一次北京。","Wǒ qù guò yī cì Běijīng.","Tôi từng đến Bắc Kinh một lần."],["请你再读一遍。","Qǐng nǐ zài dú yī biàn.","Xin bạn đọc lại một lượt."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-042","hsk30_level":"1","official":["o-1-042"],"title":"主谓句1：动词谓语句","py":"Zhǔ wèi jù1: dòng cí wèi yǔ jù","func":"句子的类型 › 句型","struct":"主语 + 动词 (+ 宾语)","vi":"Câu chủ vị có vị ngữ là động từ.","use":"Kiểu câu cơ bản nhất, nói người hay vật làm gì.","ex":[["他看书。","Tā kàn shū.","Anh ấy đọc sách."],["我们在学汉语。","Wǒmen zài xué Hànyǔ.","Chúng tôi đang học tiếng Hán."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-043","hsk30_level":"1","official":["o-1-043"],"title":"主谓句2：形容词谓语句","py":"Zhǔ wèi jù2: xíngróng cí wèi yǔ jù","func":"句子的类型 › 句型","struct":"主语 + 很 + 形容词","vi":"Câu chủ vị có vị ngữ là tính từ, miêu tả tính chất hay trạng thái.","use":"Thường có 很 hoặc phó từ mức độ trước tính từ. Không dùng 是 trước tính từ.","ex":[["今天很热。","Jīntiān hěn rè.","Hôm nay rất nóng."],["这个电影不太好看。","Zhè ge diànyǐng bùtài hǎokàn.","Bộ phim này không hay lắm."]],"note":"Không nói 他是很高; nói 他很高.","origin":"hanziai-authored"},{"id":"a-o-1-045","hsk30_level":"1","official":["o-1-045"],"title":"非主谓句","py":"Fēi zhǔ wèi jù","func":"句子的类型 › 句型","struct":"单个词或短语成句","vi":"Câu không có đủ chủ ngữ và vị ngữ; từ hoặc cụm từ tự thành câu.","use":"Gặp ở lời chào, gọi, cảm thán, thông báo ngắn.","ex":[["你好！","Nǐ hǎo!","Xin chào!"],["下雨了！","Xiàyǔ le!","Mưa rồi!"]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-046","hsk30_level":"1","official":["o-1-046"],"title":"陈述句","py":"Chénshù jù","func":"句子的类型 › 句类","struct":"主语 + 谓语。","vi":"Câu trần thuật dùng để thông báo hoặc kể sự việc.","use":"Dùng giọng thường, kết thúc bằng dấu chấm; có thể ở dạng khẳng định hoặc phủ định.","ex":[["我是中国人。","Wǒ shì Zhōngguó rén.","Tôi là người Trung Quốc."],["他今天不在家。","Tā jīntiān bù zàijiā.","Hôm nay anh ấy không ở nhà."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-047","hsk30_level":"1","official":["o-1-047"],"title":"（1）是非问句","py":"（1）Shìfēi wèn jù","func":"句子的类型 › 句类","struct":"陈述句 + 吗？","vi":"Câu hỏi để người nghe xác nhận đúng sai: trả lời là hoặc không.","use":"Thêm 吗 vào cuối câu trần thuật, hoặc dùng 吧 khi người nói đã đoán là đúng.","ex":[["你是学生吗？","Nǐ shì xuésheng ma?","Bạn là học sinh à?"],["他会说汉语吗？","Tā huì shuō Hànyǔ ma?","Anh ấy có biết nói tiếng Hán không?"]],"note":"Không dùng 吗 cùng lúc với từ nghi vấn như 什么.","origin":"hanziai-authored"},{"id":"a-o-1-048","hsk30_level":"1","official":["o-1-048"],"title":"（2）特指问句","py":"（2）Tè zhǐ wèn jù","func":"句子的类型 › 句类","struct":"带疑问代词的问句","vi":"Câu hỏi dùng từ nghi vấn (谁, 什么, 哪儿, 几...) để hỏi đúng thông tin chưa biết.","use":"Từ nghi vấn đứng đúng vị trí của thông tin được hỏi, không đảo lên đầu câu, và không cần 吗.","ex":[["你叫什么名字？","Nǐ jiào shénme míngzi?","Bạn tên là gì?"],["他住在哪儿？","Tā zhù zài nǎr?","Anh ấy sống ở đâu?"]],"note":"Không thêm 吗 cuối câu.","origin":"hanziai-authored"},{"id":"a-o-1-050","hsk30_level":"1","official":["o-1-050"],"title":"祈使句","py":"Qí shǐ jù","func":"句子的类型 › 句类","struct":"（请）+ 动词；别/不要 + 动词","vi":"Câu cầu khiến dùng để yêu cầu, đề nghị hoặc ngăn cản.","use":"Thêm 请 để lịch sự; 别/不要 để cấm đoán; chủ ngữ thường lược bỏ.","ex":[["请坐。","Qǐngzuò.","Xin mời ngồi."],["别说话！","Biéshuō huà!","Đừng nói chuyện!"]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-051","hsk30_level":"1","official":["o-1-051"],"title":"感叹句","py":"Gǎntàn jù","func":"句子的类型 › 句类","struct":"太 + 形容词 + 了；多 + 形容词 + 啊","vi":"Câu cảm thán biểu lộ cảm xúc mạnh như vui, kinh ngạc, tiếc.","use":"Hay dùng 太……了, 多么……啊, hoặc từ cảm thán; cuối câu dùng dấu chấm than.","ex":[["今天太冷了！","Jīntiān tài lěng le!","Hôm nay lạnh quá!"],["这个地方多漂亮啊！","Zhè ge dìfāng duō piàoliang a!","Nơi này đẹp biết bao!"]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-053","hsk30_level":"1","official":["o-1-053"],"title":"“有”字句1：表示领有","py":"“Yǒu”zì jù1: biǎoshì lǐng yǒu","func":"句子的类型 › 特殊句型","struct":"主语 + 有 + 宾语","vi":"Câu chữ 有 dùng để nói ai sở hữu cái gì.","use":"Phủ định dùng 没有, không dùng 不有. Hỏi bằng 有……吗 hoặc 有没有.","ex":[["我有一个哥哥。","Wǒ yǒu yī ge gēge.","Tôi có một người anh."],["他没有手机。","Tā méiyǒu shǒujī.","Anh ấy không có điện thoại."]],"note":"Phủ định là 没有, không phải 不有.","origin":"hanziai-authored"},{"id":"a-o-1-054","hsk30_level":"1","official":["o-1-054"],"title":"存现句1：（1）所处+是+名词","py":"Cún xiàn jù1: （1）suǒ chù+shì+míng cí","func":"句子的类型 › 特殊句型","struct":"处所 + 是 + 名词","vi":"Câu tồn hiện dùng 是 để nêu ở một nơi có cái gì (nhấn vào vật đó, thường là toàn bộ thứ ở đó).","use":"Nơi chốn đứng đầu câu, sau đó là 是 và vật.","ex":[["学校前边是一家银行。","Xuéxiào qiánbian shì yī jiā yínháng.","Phía trước trường là một ngân hàng."],["我家旁边是商店。","Wǒ jiā pángbiān shì shāngdiàn.","Bên cạnh nhà tôi là cửa hàng."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-059","hsk30_level":"1","official":["o-1-059"],"title":"不用关联词语的复句","py":"Bùyòng guānlián cíyǔ de fù jù","func":"句子的类型 › 复句","struct":"分句 1，分句 2","vi":"Câu ghép không dùng từ nối; quan hệ giữa các vế hiểu qua nghĩa.","use":"Hai phân câu đặt cạnh nhau, ngăn cách bằng dấu phẩy.","ex":[["天黑了，我们回家吧。","Tiān hēi le, wǒmen huíjiā ba.","Trời tối rồi, chúng ta về nhà thôi."],["他不来，我也不去。","Tā bù lái, wǒ yě bù qù.","Anh ấy không đến, tôi cũng không đi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-060","hsk30_level":"1","official":["o-1-060"],"title":"并列复句：……，也……","py":"Bìngliè fù jù: ……, yě……","func":"句子的类型 › 复句","struct":"主语 1 + 动词，主语 2 + 也 + 动词","vi":"Câu ghép song song, nói hai điều cùng như nhau; 也 nghĩa là cũng.","use":"Vế sau đặt 也 trước động từ. Chủ ngữ hai vế có thể khác nhau.","ex":[["我喜欢中国菜，他也喜欢。","Wǒ xǐhuan Zhōngguó cài, tā yě xǐhuan.","Tôi thích món Trung, anh ấy cũng thích."],["今天很冷，明天也很冷。","Jīntiān hěn lěng, míngtiān yě hěn lěng.","Hôm nay rất lạnh, mai cũng rất lạnh."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-061","hsk30_level":"1","official":["o-1-061"],"title":"并列复句：……，还……","py":"Bìngliè fù jù: ……, hái……","func":"句子的类型 › 复句","struct":"动词 1，还 + 动词 2","vi":"Câu ghép nói thêm một việc nữa; 还 nghĩa là còn, vừa lại.","use":"Vế sau thêm 还 trước động từ để bổ sung.","ex":[["他会说汉语，还会说英语。","Tā huì shuō Hànyǔ, hái huì shuō Yīngyǔ.","Anh ấy biết nói tiếng Hán, còn biết nói tiếng Anh."],["我们去超市，还要去银行。","Wǒmen qù chāoshì, hái yào qù yínháng.","Chúng tôi đi siêu thị, còn phải đến ngân hàng."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-062","hsk30_level":"1","official":["o-1-062"],"title":"完成态：用动态助词“了1”表示","py":"Wánchéng tài: yòng dòngtài zhù cí“le1”biǎoshì","func":"动作的态","struct":"动词 + 了 + (宾语)","vi":"Dùng 了 sau động từ để nói hành động đã hoàn thành.","use":"Khi tân ngữ có số lượng hay định ngữ thì 了 đặt sau động từ (我买了三本书). Phủ định dùng 没(有) và bỏ 了.","ex":[["我吃了两个苹果。","Wǒ chī le liǎng ge píngguǒ.","Tôi đã ăn hai quả táo."],["他没吃早饭。","Tā méi chī zǎofàn.","Anh ấy chưa ăn sáng."]],"note":"Phủ định không giữ 了: 他没吃, không phải 他没吃了.","origin":"hanziai-authored"},{"id":"a-o-1-063","hsk30_level":"1","official":["o-1-063"],"title":"变化态：用动态助词“了2”表示","py":"Biànhuà tài: yòng dòngtài zhù cí“le2”biǎoshì","func":"动作的态","struct":"句子 + 了","vi":"Dùng 了 cuối câu để nói tình huống mới hoặc có thay đổi.","use":"Đặt cuối câu, cho thấy sự việc đã đổi so với trước.","ex":[["天黑了。","Tiān hēi le.","Trời tối rồi."],["我现在会说汉语了。","Wǒ xiànzài huì shuō Hànyǔ le.","Bây giờ tôi biết nói tiếng Hán rồi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-064","hsk30_level":"1","official":["o-1-064"],"title":"进行态：（1）……在/正在+动词","py":"Jìnxíng tài: （1）……zài/zhèngzài+dòng cí","func":"动作的态","struct":"主语 + 在/正在 + 动词","vi":"Diễn tả hành động đang diễn ra.","use":"在 hay 正在 đặt trước động từ; thường có thêm 呢 cuối câu.","ex":[["他在看电视。","Tā zài kàn diànshì.","Anh ấy đang xem tivi."],["我们正在上课。","Wǒmen zhèngzài shàngkè.","Chúng tôi đang học."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-065","hsk30_level":"1","official":["o-1-065"],"title":"进行态：（2）……在/正在+动词……+呢","py":"Jìnxíng tài: （2）……zài/zhèngzài+dòng cí……+ne","func":"动作的态","struct":"主语 + (正)在 + 动词 + 呢","vi":"Như trên, thêm 呢 cuối câu để nhấn mạnh trạng thái đang diễn ra.","use":"呢 làm ngữ khí cho hành động đang tiếp diễn.","ex":[["妈妈正在做饭呢。","Māma zhèngzài zuòfàn ne.","Mẹ đang nấu cơm đấy."],["你别打电话，他在睡觉呢。","Nǐ bié dǎdiànhuà, tā zài shuìjiào ne.","Đừng gọi điện, anh ấy đang ngủ."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-066","hsk30_level":"1","official":["o-1-066"],"title":"进行态：（3）……呢","py":"Jìnxíng tài: （3）……ne","func":"动作的态","struct":"主语 + 动词 + 呢","vi":"Chỉ dùng 呢 cuối câu cũng thể hiện hành động đang diễn ra.","use":"Dùng nhiều trong khẩu ngữ khi đã rõ ngữ cảnh.","ex":[["他吃饭呢。","Tā chīfàn ne.","Anh ấy đang ăn cơm đấy."],["外面下雨呢。","Wàimiàn xiàyǔ ne.","Bên ngoài đang mưa."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-067","hsk30_level":"1","official":["o-1-067"],"title":"钱数表示法","py":"Qián shù biǎoshì fǎ","func":"特殊表达法 › 数的表达法","struct":"数词 + 块/元 (+ 数词 + 毛/角)","vi":"Cách nói tiền Trung Quốc: 块 (khẩu ngữ) hay 元, 毛 hay 角, 分.","use":"Khẩu ngữ dùng 块, 毛; văn viết dùng 元, 角. 1 块 = 10 毛.","ex":[["这个多少钱？","Zhè ge duōshǎo qián?","Cái này bao nhiêu tiền?"],["一共二十五块五毛。","Yīgòng èr shí wǔ kuài wǔ máo.","Tổng cộng hai mươi lăm đồng năm hào."]],"note":"Hai trăm là 两百, không phải 二百 khi nói số lượng lớn (khẩu ngữ).","origin":"hanziai-authored"},{"id":"a-o-1-068","hsk30_level":"1","official":["o-1-068"],"title":"序数表达法1：第+数词","py":"Xù shù biǎodá fǎ1: dì+shù cí","func":"特殊表达法 › 数的表达法","struct":"第 + 数词 (+ 量词) + 名词","vi":"Cách nói thứ tự: thêm 第 trước số từ.","use":"Có thể thêm lượng từ rồi đến danh từ: 第一课, 第三个人.","ex":[["这是第一课。","Zhè shì dìyī kè.","Đây là bài thứ nhất."],["他是第三个到的。","Tā shì dì sān ge dào de.","Anh ấy là người thứ ba đến."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-1-070","hsk30_level":"1","official":["o-1-070"],"title":"（2）钟点表示法","py":"（2）Zhōng diǎn biǎoshì fǎ","func":"特殊表达法 › 时间表示法","struct":"数词 + 点 + 数词 + 分","vi":"Cách nói giờ giấc: 点 là giờ, 分 là phút, 半 là rưỡi, 刻 là mười lăm phút.","use":"两点 (không dùng 二点); 差五分三点 (ba giờ kém năm phút); 三点半.","ex":[["现在几点？","Xiànzài jī diǎn?","Bây giờ là mấy giờ?"],["我们七点半吃早饭。","Wǒmen qī diǎn bàn chī zǎofàn.","Chúng tôi ăn sáng lúc bảy giờ rưỡi."]],"note":"Hai giờ là 两点, không phải 二点.","origin":"hanziai-authored"},{"id":"a-o-2-001","hsk30_level":"2","official":["o-2-001"],"title":"后缀 —面","py":"Hòu zhuì —miàn","func":"语素 › 后缀","struct":"方位词 + 面","vi":"面 ghép sau từ phương vị để tạo từ chỉ vị trí như 上面, 下面, 里面, 外面.","use":"Nghĩa gần như 上, 下 nhưng nhấn vào \"mặt, phía\"; dùng như danh từ phương vị.","ex":[["桌子上面有一本书。","Zhuōzi shàngmiàn yǒu yī běn shū.","Trên bàn có một quyển sách."],["外面在下雨。","Wàimiàn zài xiàyǔ.","Bên ngoài đang mưa."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-012","hsk30_level":"2","official":["o-2-012"],"title":"借用名量词：包","py":"Jièyòng míng liàng cí: bāo","func":"词类 › 量词","struct":"数词 + 包 + 名词","vi":"包 (túi, gói) vốn là danh từ, mượn làm lượng từ đếm đồ đựng trong gói hay túi.","use":"Đặt giữa số từ và danh từ: 一包糖, 两包饼干.","ex":[["我买了一包饼干。","Wǒ mǎi le yī bāo bǐnggān.","Tôi mua một gói bánh quy."],["他要两包糖。","Tā yào liǎng bāo táng.","Anh ấy cần hai gói kẹo."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-028","hsk30_level":"2","official":["o-2-028"],"title":"跟2 (liên từ)","py":"Gēn2 (liên từ)","func":"词类 › 连词","struct":"A + 跟 + B","vi":"跟 làm liên từ nghĩa là và, nối hai danh từ hoặc đại từ ngang hàng, như 和.","use":"Dùng nhiều trong khẩu ngữ: 我跟他, 苹果跟香蕉.","ex":[["我跟他都是学生。","Wǒ gēn tā dōu shì xuésheng.","Tôi và anh ấy đều là học sinh."],["桌子上有苹果跟香蕉。","Zhuōzi shàng yǒu píngguǒ gēn xiāngjiāo.","Trên bàn có táo và chuối."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-034","hsk30_level":"2","official":["o-2-034"],"title":"动补短语1","py":"Dòng bǔ duǎn yǔ1","func":"词类 › 助词","struct":"动词 + 补语","vi":"Cụm động bổ: động từ kèm bổ ngữ nói kết quả, xu hướng, trạng thái hay số lượng.","use":"Gồm 看懂, 跑进来, 洗干净, 说得好...","ex":[["我听懂了。","Wǒ tīng dǒng le.","Tôi nghe hiểu rồi."],["他跑进教室来。","Tā pǎo jìn jiàoshì lái.","Anh ấy chạy vào lớp."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-035","hsk30_level":"2","official":["o-2-035"],"title":"（1）“的”字短语","py":"（1）“De”zì duǎn yǔ","func":"短语 › 结构类型","struct":"名词/形容词/动词 + 的","vi":"Cụm chữ 的: 的 đứng sau từ hoặc cụm để thành cụm danh từ, thay cho danh từ đã nhắc ở trước.","use":"Dùng khi không cần nhắc lại danh từ: 我的 (của tôi), 红的 (cái màu đỏ).","ex":[["这本书是我的。","Zhè běn shū shì wǒ de.","Quyển sách này là của tôi."],["我要红的，不要黑的。","Wǒ yào hóng de, bùyào hēi de.","Tôi lấy cái đỏ, không lấy cái đen."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-036","hsk30_level":"2","official":["o-2-036"],"title":"（2）连谓短语","py":"（2）Lián wèi duǎn yǔ","func":"短语 › 结构类型","struct":"动词1 + (宾语1) + 动词2 + (宾语2)","vi":"Cụm liên động: hai hoặc nhiều động từ liên tiếp cùng một chủ ngữ.","use":"Quan hệ giữa các động tác có thể là nối tiếp, mục đích hoặc cách thức.","ex":[["他去商店买东西。","Tā qù shāngdiàn mǎi dōngxī.","Anh ấy đi cửa hàng mua đồ."],["我坐地铁上班。","Wǒ zuò dìtiě shàngbān.","Tôi đi tàu điện ngầm đi làm."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-038","hsk30_level":"2","official":["o-2-038"],"title":"名词性短语","py":"Míng cí xìng duǎn yǔ","func":"短语 › 功能类型","struct":"定语 + 名词","vi":"Cụm danh từ: lấy danh từ làm trung tâm, có thể làm chủ ngữ, tân ngữ.","use":"Ví dụ 我的书, 老师的朋友.","ex":[["我喜欢他的朋友。","Wǒ xǐhuan tā de péngyou.","Tôi thích bạn của anh ấy."],["那件红衣服很好看。","Nà jiàn hóng yīfu hěn hǎokàn.","Chiếc áo đỏ kia rất đẹp."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-039","hsk30_level":"2","official":["o-2-039"],"title":"动词性短语","py":"Dòng cí xìng duǎn yǔ","func":"短语 › 功能类型","struct":"动词 + 宾语/补语 等","vi":"Cụm động từ: lấy động từ làm trung tâm, làm vị ngữ hoặc các thành phần khác.","use":"Ví dụ 看电影, 吃完饭.","ex":[["我想看电影。","Wǒ xiǎng kàn diànyǐng.","Tôi muốn xem phim."],["他吃完饭就走了。","Tā chī wán fàn jiù zǒu le.","Anh ấy ăn cơm xong là đi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-040","hsk30_level":"2","official":["o-2-040"],"title":"形容词性短语","py":"Xíngróng cí xìng duǎn yǔ","func":"短语 › 功能类型","struct":"很/非常 + 形容词","vi":"Cụm tính từ: lấy tính từ làm trung tâm, thường có phó từ.","use":"Ví dụ 非常好, 很贵.","ex":[["这件衣服非常漂亮。","Zhè jiàn yīfu fēicháng piàoliang.","Chiếc áo này rất đẹp."],["这家饭店不太贵。","Zhè jiā fàndiàn bùtài guì.","Quán này không đắt lắm."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-042","hsk30_level":"2","official":["o-2-042"],"title":"还是……吧","py":"Háishi……ba","func":"固定格式","struct":"还是 + 动作/选择 + 吧","vi":"Dùng 还是……吧 để đưa ra đề nghị sau khi cân nhắc: nghĩa là thôi thì, hay là.","use":"Vế giữa nêu lựa chọn người nói thấy hợp hơn; kết thúc bằng 吧.","ex":[["天太冷了，我们还是回家吧。","Tiān tài lěng le, wǒmen háishi huíjiā ba.","Trời lạnh quá, hay là chúng ta về nhà đi."],["你还是先休息吧。","Nǐ háishi xiān xiūxi ba.","Bạn cứ nghỉ trước đã thì hơn."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-044","hsk30_level":"2","official":["o-2-044"],"title":"都……了","py":"Dōu……le","func":"固定格式","struct":"都 + 动词/形容词/时间 + 了","vi":"Dùng 都……了 nhấn mạnh sự việc đã đến mức như vậy, có ý nhắc nhở hoặc phàn nàn.","use":"Giữa 都 và 了 là từ chỉ thời gian, tuổi hoặc trạng thái đã đạt: 都十点了.","ex":[["都十点了，你怎么还不睡觉？","Dōu shí diǎn le, nǐ zěnme hái bù shuìjiào?","Đã mười giờ rồi, sao bạn còn chưa ngủ?"],["他都三十岁了。","Tā dōu sān shí suì le.","Anh ấy đã ba mươi tuổi rồi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-045","hsk30_level":"2","official":["o-2-045"],"title":"受事主语","py":"Shòu shì zhǔ yǔ","func":"句子成分 › 主语","struct":"受事 + 动词 (+ 了)","vi":"Chủ ngữ là đối tượng chịu tác động của hành động chứ không phải người làm.","use":"Không dùng 被; nghĩa vẫn là bị động. Thường có thành phần hoàn thành (了, 完...).","ex":[["饭做好了。","Fàn zuò hǎo le.","Cơm nấu xong rồi."],["信写完了。","Xìn xiě wánle.","Thư viết xong rồi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-046","hsk30_level":"2","official":["o-2-046"],"title":"名词性短语作谓语","py":"Míng cí xìng duǎn yǔ zuò wèi yǔ","func":"句子成分 › 谓语","struct":"主语 + 名词性短语","vi":"Vị ngữ là cụm danh từ, nói về quê quán, tuổi, ngày, đặc điểm.","use":"Thường là cụm có số lượng; không cần 是.","ex":[["他北京人。","Tā Běijīng rén.","Anh ấy người Bắc Kinh."],["今天阴天。","Jīntiān yīntiān.","Hôm nay trời âm u."]],"note":"Phủ định dùng 不是.","origin":"hanziai-authored"},{"id":"a-o-2-047","hsk30_level":"2","official":["o-2-047"],"title":"动词或动词性短语、主谓短语作定语","py":"Dòng cí huò dòng cí xìng duǎn yǔ, zhǔ wèi duǎn yǔ zuò dìng yǔ","func":"句子成分 › 定语","struct":"动词性短语/主谓短语 + 的 + 名词","vi":"Động từ, cụm động từ hay cụm chủ vị đóng vai trò định ngữ cho danh từ, cần có 的.","use":"Đưa cả mệnh đề lên trước danh từ, khác tiếng Việt: danh từ nằm cuối.","ex":[["我昨天买的书很有意思。","Wǒ zuótiān mǎi de shū hěn yǒuyìsi.","Quyển sách tôi mua hôm qua rất thú vị."],["这是妈妈做的菜。","Zhè shì māma zuò de cài.","Đây là món mẹ nấu."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-052","hsk30_level":"2","official":["o-2-052"],"title":"状态补语1：动词+得+形容词性短语","py":"Zhuàngtài bǔ yǔ1: dòng cí+de+xíngróng cí xìng duǎn yǔ","func":"句子成分 › 补语","struct":"动词 + 得 + 很/形容词性短语","vi":"Bổ ngữ trạng thái nói mức độ hay trạng thái của hành động.","use":"Nếu có tân ngữ, lặp động từ: 说汉语说得很好 hoặc đưa tân ngữ lên: 汉语说得很好.","ex":[["他跑得很快。","Tā pǎo de hěn kuài.","Anh ấy chạy rất nhanh."],["她唱歌唱得很好。","Tā chànggē chàng de hěn hǎo.","Cô ấy hát rất hay."]],"note":"Phủ định: 跑得不快, đặt 不 trước tính từ.","origin":"hanziai-authored"},{"id":"a-o-2-054","hsk30_level":"2","official":["o-2-054"],"title":"数量补语2：（2）形容词+数量补语","py":"Shùliàng bǔ yǔ2: （2）xíngróng cí+shùliàng bǔ yǔ","func":"句子成分 › 补语","struct":"形容词 + 数量短语","vi":"Bổ ngữ số lượng sau tính từ cho biết chênh lệch hay mức độ hơn kém.","use":"Hay dùng trong so sánh: 大两岁, 高三厘米.","ex":[["他比我大两岁。","Tā bǐ wǒ dà liǎng suì.","Anh ấy lớn hơn tôi hai tuổi."],["这个比那个贵十块。","Zhè ge bǐ nà ge guì shí kuài.","Cái này đắt hơn cái kia mười đồng."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-056","hsk30_level":"2","official":["o-2-056"],"title":"用“还是”连接的选择问句","py":"Yòng“háishi”liánjiē de xuǎnzé wèn jù","func":"句子的类型 › 句类","struct":"A 还是 B？","vi":"Câu hỏi lựa chọn dùng 还是 để hỏi người nghe chọn giữa các lựa chọn.","use":"Không thêm 吗; 还是 đặt giữa hai lựa chọn.","ex":[["你喝茶还是喝咖啡？","Nǐ hē chá háishi hē kāfēi?","Bạn uống trà hay uống cà phê?"],["他是老师还是学生？","Tā shì lǎoshī háishi xuésheng?","Anh ấy là giáo viên hay học sinh?"]],"note":"Câu trần thuật dùng 或者, câu hỏi dùng 还是.","origin":"hanziai-authored"},{"id":"a-o-2-057","hsk30_level":"2","official":["o-2-057"],"title":"用“别”的祈使句","py":"Yòng“bié”de qí shǐ jù","func":"句子的类型 › 句类","struct":"别 + 动词 (+ 了)","vi":"Câu cầu khiến dùng 别 để khuyên can hoặc cấm làm việc gì.","use":"Đặt 别 trước động từ; thêm 了 để nhấn ngừng việc đang làm.","ex":[["别说话，他在睡觉。","Biéshuō huà, tā zài shuìjiào.","Đừng nói chuyện, anh ấy đang ngủ."],["你别哭了。","Nǐ bié kū le.","Bạn đừng khóc nữa."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-058","hsk30_level":"2","official":["o-2-058"],"title":"“是”字句2：表示说明或特征","py":"“Shì”zì jù2: biǎoshì shuōmíng huò tèzhēng","func":"句子的类型 › 句类","struct":"主语 + 是 + 形容词/短语 + 的","vi":"Câu chữ 是 dùng để nêu đặc điểm, tính chất hay nhận xét về chủ ngữ.","use":"Thường có 的 cuối câu: 这个杯子是新的.","ex":[["这个杯子是新的。","Zhè ge bēizi shì xīn de.","Cái cốc này là mới."],["他的房间是很干净的。","Tā de fángjiān shì hěn gānjìng de.","Phòng của anh ấy rất sạch."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-059","hsk30_level":"2","official":["o-2-059"],"title":"“有”字句2：表示达到","py":"“Yǒu”zì jù2: biǎoshì dádào","func":"句子的类型 › 句类","struct":"主语 + 有 + 数量短语 + (形容词)","vi":"Câu chữ 有 dùng để nói đạt đến một mức, số lượng hay kích cỡ nhất định.","use":"Hay có 这么/那么 hoặc số lượng: 有一米八高.","ex":[["他有一米八高。","Tā yǒu yī mǐ bā gāo.","Anh ấy cao một mét tám."],["这个湖有三公里长。","Zhè ge hú yǒu sān gōnglǐ cháng.","Hồ này dài ba cây số."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-064","hsk30_level":"2","official":["o-2-064"],"title":"比较句1：（4）A比B+动词+得+形容词 / A+动词+得+比+B+形容词","py":"Bǐjiào jù1: （4）AbǐB+dòng cí+de+xíngróng cí / A+dòng cí+de+bǐ+B+xíngróng cí","func":"句子的类型 › 句类","struct":"A + 比 + B + 动词 + 得 + 形容词；A + 动词 + 得 + 比 + B + 形容词","vi":"So sánh mức độ của hành động giữa hai đối tượng.","use":"Có hai cách đặt 比: trước động từ (比他跑得快) hoặc trước bổ ngữ (跑得比他快).","ex":[["我比他跑得快。","Wǒ bǐ tā pǎo de kuài.","Tôi chạy nhanh hơn anh ấy."],["她说得比我流利。","Tā shuō de bǐ wǒ liúlì.","Cô ấy nói trôi chảy hơn tôi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-065","hsk30_level":"2","official":["o-2-065"],"title":"“是……的”句1：强调时间、地点、方式、动作者","py":"“Shì……de”jù1: qiángdiào shíjiān, dìdiǎn, fāngshì, dòngzuò zhě","func":"句子的类型 › 句类","struct":"（主语）+ 是 + 时间/地点/方式 + 动词 + 的","vi":"Dùng 是……的 để nhấn mạnh thời gian, nơi chốn, cách thức hay người thực hiện một việc đã xảy ra.","use":"Nhấn mạnh phần giữa 是 và động từ; có thể lược 是 trong câu khẳng định.","ex":[["我是昨天到的。","Wǒ shì zuótiān dào de.","Tôi đến vào hôm qua."],["他是坐飞机来的。","Tā shì zuò fēijī lái de.","Anh ấy đến bằng máy bay."]],"note":"Chỉ dùng cho việc đã xảy ra.","origin":"hanziai-authored"},{"id":"a-o-2-067","hsk30_level":"2","official":["o-2-067"],"title":"双宾语句2：主语+动词+给+宾语1+宾语2","py":"Shuāng bīn yǔ jù2: zhǔ yǔ+dòng cí+gěi+bīn yǔ1+bīn yǔ2","func":"句子的类型 › 句类","struct":"主语 + 动词 + 给 + 人 + 物","vi":"Câu hai tân ngữ có 给 sau động từ: đưa vật cho ai.","use":"Thứ tự: người nhận rồi tới vật.","ex":[["他送给我一本书。","Tā sònggěi wǒ yī běn shū.","Anh ấy tặng tôi một quyển sách."],["妈妈寄给我一些水果。","Māma jì gěi wǒ yīxiē shuǐguǒ.","Mẹ gửi cho tôi ít hoa quả."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-068","hsk30_level":"2","official":["o-2-068"],"title":"选择复句：（是）……，还是……","py":"Xuǎnzé fù jù: （shì）……, háishi……","func":"句子的类型 › 复句","struct":"（是）A，还是 B","vi":"Câu ghép lựa chọn dùng để hỏi hoặc nêu hai khả năng, chọn một.","use":"Vế sau có 还是 làm từ nối; câu hỏi thường không cần 吗.","ex":[["你是坐火车去，还是坐飞机去？","Nǐ shì zuò huǒchē qù, háishi zuò fēijī qù?","Bạn đi tàu hỏa hay đi máy bay?"],["我们是现在走，还是等一会儿？","Wǒmen shì xiànzài zǒu, háishi děng yīhuìr?","Chúng ta đi bây giờ hay đợi một lát?"]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-069","hsk30_level":"2","official":["o-2-069"],"title":"转折复句：虽然……，但是……","py":"Zhuǎnzhé fù jù: suīrán……, dànshì……","func":"句子的类型 › 复句","struct":"虽然 + A，但是 + B","vi":"Câu ghép chuyển ý: thừa nhận A nhưng B trái với dự đoán.","use":"虽然 ở vế trước, 但是 ở vế sau. Có thể dùng 可是 thay 但是.","ex":[["虽然天气很冷，但是他还是去跑步。","Suīrán tiānqì hěn lěng, dànshì tā háishi qù pǎobù.","Tuy trời lạnh, nhưng anh ấy vẫn đi chạy."],["这家店虽然小，但是菜很好吃。","Zhè jiā diàn suīrán xiǎo, dànshì cài hěn hǎochī.","Quán này tuy nhỏ nhưng món rất ngon."]],"note":"Không dùng 因为 cùng 虽然.","origin":"hanziai-authored"},{"id":"a-o-2-070","hsk30_level":"2","official":["o-2-070"],"title":"因果复句：因为……，所以……","py":"Yīn guǒ fù jù: yīnwèi……, suǒyǐ……","func":"句子的类型 › 复句","struct":"因为 + 原因，所以 + 结果","vi":"Câu ghép nhân quả: nêu nguyên nhân rồi kết quả.","use":"Tiếng Hán dùng cả 因为 và 所以, khác tiếng Việt chỉ dùng một. Cũng có thể lược một trong hai.","ex":[["因为下雨，所以我们没去公园。","Yīnwèi xiàyǔ, suǒyǐ wǒmen méi qù gōngyuán.","Vì trời mưa nên chúng tôi không đi công viên."],["因为他生病了，所以没来上课。","Yīnwèi tā shēngbìng le, suǒyǐ méi lái shàngkè.","Vì anh ấy ốm nên không đến lớp."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-071","hsk30_level":"2","official":["o-2-071"],"title":"紧缩复句：一……就……","py":"Jǐnsuō fù jù: yī……jiù……","func":"句子的类型 › 复句","struct":"一 + 动作1，就 + 动作2","vi":"Câu ghép rút gọn: vừa làm việc một thì lập tức tới việc hai.","use":"Hai hành động nối tiếp rất nhanh; 就 đặt trước động từ ở vế sau.","ex":[["他一到家就吃饭。","Tā yī dào jiā jiù chīfàn.","Anh ấy vừa về đến nhà là ăn cơm."],["我一看就明白了。","Wǒ yī kàn jiù míngbai le.","Tôi vừa nhìn là hiểu."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-072","hsk30_level":"2","official":["o-2-072"],"title":"持续态：动词+着（1）表示状态的持续","py":"Chíxù tài: dòng cí+zhe（1）biǎoshì zhuàngtài de chíxù","func":"动作的态","struct":"动词 + 着","vi":"着 sau động từ nói trạng thái được giữ liên tục sau khi hành động xong.","use":"Hay đi với các động từ như 坐, 站, 开, 放, 挂.","ex":[["门开着。","Mén kāi zhe.","Cửa đang mở."],["墙上挂着一幅画。","Qiáng shàng guà zhe yī fú huà.","Trên tường treo một bức tranh."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-073","hsk30_level":"2","official":["o-2-073"],"title":"持续态：（2）表示动作的持续","py":"Chíxù tài: （2）biǎoshì dòngzuò de chíxù","func":"动作的态","struct":"动词 + 着 (+ 宾语)","vi":"着 cũng diễn tả hành động đang tiếp diễn, thường kèm 呢 hoặc một động từ khác.","use":"Hay gặp trong 说着, 笑着, 听着.","ex":[["他笑着说：“你好！”","Tā xiào zhe shuō: “nǐ hǎo!”","Anh ấy cười nói: “Xin chào!”"],["孩子们唱着歌走进教室。","Háizi men chàng zhe gē zǒujìn jiàoshì.","Bọn trẻ vừa hát vừa đi vào lớp."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-074","hsk30_level":"2","official":["o-2-074"],"title":"经历态：用动态助词“过”表示","py":"Jīnglì tài: yòng dòngtài zhù cí“guò”biǎoshì","func":"动作的态","struct":"动词 + 过","vi":"过 sau động từ nói đã từng trải qua việc gì.","use":"Phủ định dùng 没(有) + 动词 + 过; hỏi dùng 有没有……过.","ex":[["我去过北京。","Wǒ qù guò Běijīng.","Tôi từng đến Bắc Kinh."],["他没吃过饺子。","Tā méi chī guò jiǎozi.","Anh ấy chưa từng ăn sủi cảo."]],"note":"Phủ định vẫn giữ 过.","origin":"hanziai-authored"},{"id":"a-o-2-075","hsk30_level":"2","official":["o-2-075"],"title":"序数表示法2：数词+量词","py":"Xù shù biǎoshì fǎ2: shù cí+liàng cí","func":"特殊表达法 › 数的表达法","struct":"数词 + 量词","vi":"Không dùng 第 vẫn có thể nói thứ tự trong cách nói quen thuộc (一号, 二楼).","use":"Dùng cho tầng, số nhà, ngày: 三楼, 五号.","ex":[["我住在三楼。","Wǒ zhù zài sān lóu.","Tôi ở tầng ba."],["他是二班的学生。","Tā shì èr bān de xuésheng.","Anh ấy là học sinh lớp hai."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-076","hsk30_level":"2","official":["o-2-076"],"title":"概数表达法1：（1）用“几”表示概数","py":"Gài shù biǎodá fǎ1: （1）yòng“jī”biǎoshì gài shù","func":"特殊表达法 › 数的表达法","struct":"几 + 量词 + 名词","vi":"几 dùng để nói số lượng ít, không xác định (khoảng vài).","use":"Thường chỉ số dưới mười.","ex":[["我买了几个苹果。","Wǒ mǎi le jī ge píngguǒ.","Tôi mua mấy quả táo."],["他有几个中国朋友。","Tā yǒu jī ge Zhōngguó péngyou.","Anh ấy có vài người bạn Trung Quốc."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-077","hsk30_level":"2","official":["o-2-077"],"title":"（2）数词+多+量词","py":"（2）Shù cí+duō+liàng cí","func":"特殊表达法 › 数的表达法","struct":"数词 (10, 100...) + 多 + 量词","vi":"Số tròn chục, trăm + 多 chỉ số lớn hơn con số đó một chút.","use":"多 đứng trước lượng từ khi số từ là số tròn: 十多个人.","ex":[["教室里有二十多个人。","Jiàoshì lǐ yǒu èr shí duō gèrén.","Trong lớp có hơn hai mươi người."],["他花了一百多块钱。","Tā huā le yī bǎi duō kuài qián.","Anh ấy tiêu hơn một trăm đồng."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-2-078","hsk30_level":"2","official":["o-2-078"],"title":"（3）数词+量词+多","py":"（3）Shù cí+liàng cí+duō","func":"特殊表达法 › 数的表达法","struct":"数词 (số nhỏ) + 量词 + 多","vi":"Với số không tròn chục, 多 đặt sau lượng từ: hơn con số đó một chút.","use":"Ví dụ 三个多月, 五斤多.","ex":[["我学了三个多月汉语。","Wǒ xué le sān ge duō yuè Hànyǔ.","Tôi đã học tiếng Hán hơn ba tháng."],["这个包五斤多。","Zhè ge bāo wǔ jīn duō.","Cái túi này nặng hơn năm cân."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-001","hsk30_level":"3","official":["o-3-001"],"title":"前缀 老—","py":"Qián zhuì lǎo—","func":"语素 › 前缀","struct":"老 + 姓/排行/称谓","vi":"Tiền tố 老 đặt trước họ, thứ bậc hoặc xưng hô, thể hiện thân mật hoặc kính trọng.","use":"老王, 老师, 老二, 老虎. Không còn nghĩa \"già\" ở đây.","ex":[["老王是我的邻居。","Lǎo wáng shì wǒ de línjū.","Bác Vương là hàng xóm của tôi."],["他是家里的老二。","Tā shì jiālǐ de lǎo èr.","Anh ấy là con thứ hai trong nhà."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-002","hsk30_level":"3","official":["o-3-002"],"title":"后缀 —家、—子、—员","py":"Hòu zhuì —jiā, —zi, —yuán","func":"语素 › 后缀","struct":"名词/动词 + 家/子/员","vi":"Hậu tố tạo danh từ: —家 chỉ chuyên gia, —子 là hậu tố danh từ, —员 chỉ người làm nghề.","use":"作家, 画家, 桌子, 椅子, 服务员, 演员.","ex":[["他是一位有名的作家。","Tā shì yī wèi yǒumíng de zuòjiā.","Anh ấy là một nhà văn nổi tiếng."],["服务员，请给我菜单。","Fúwùyuán, qǐng gěi wǒ càidān.","Phục vụ ơi, cho tôi thực đơn."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-008","hsk30_level":"3","official":["o-3-008"],"title":"疑问代词的任指用法","py":"Yíwèn dài cí de rèn zhǐ yòngfǎ","func":"词类 › 代词","struct":"疑问代词 + 都/也 + 动词；疑问代词……，疑问代词……","vi":"Đại từ nghi vấn không để hỏi mà chỉ bất kỳ, mọi.","use":"Dạng 1: 谁/什么/哪儿 + 都/也. Dạng 2: hai đại từ nghi vấn cùng loại hô ứng.","ex":[["谁都知道这件事。","Shéi dōu zhīdào zhè jiàn shì.","Ai cũng biết chuyện này."],["你想吃什么就吃什么。","Nǐ xiǎng chī shénme jiù chī shénme.","Bạn muốn ăn gì thì ăn nấy."]],"note":"Phủ định dùng 也 hoặc 都 đều được.","origin":"hanziai-authored"},{"id":"a-o-3-009","hsk30_level":"3","official":["o-3-009"],"title":"疑问代词的不定指用法","py":"Yíwèn dài cí de bùdìng zhǐ yòngfǎ","func":"词类 › 代词","struct":"疑问代词 + 动词/名词","vi":"Đại từ nghi vấn chỉ người hoặc vật không xác định: ai đó, cái gì đó.","use":"Thường trong câu phủ định, điều kiện hoặc nghi vấn nhẹ.","ex":[["我好像在哪儿见过你。","Wǒ hǎoxiàng zài nǎr jiànguò nǐ.","Hình như tôi đã gặp bạn ở đâu đó."],["你想喝点什么吗？","Nǐ xiǎng hē diǎn shénme ma?","Bạn muốn uống chút gì không?"]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-032","hsk30_level":"3","official":["o-3-032"],"title":"同位短语","py":"Tóng wèi duǎn yǔ","func":"短语 › 结构类型","struct":"名词1 + 名词2 (cùng chỉ một đối tượng)","vi":"Cụm đồng vị: hai thành phần cùng chỉ một người hay vật, giải thích cho nhau.","use":"Ví dụ 我们老师王先生, 首都北京.","ex":[["我的朋友小李是医生。","Wǒ de péngyou xiǎo li shì yīshēng.","Bạn tôi Tiểu Lý là bác sĩ."],["中国首都北京很大。","Zhōngguó shǒudū Běijīng hěn dà.","Thủ đô Bắc Kinh của Trung Quốc rất lớn."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-033","hsk30_level":"3","official":["o-3-033"],"title":"动补短语2","py":"Dòng bǔ duǎn yǔ2","func":"短语 › 结构类型","struct":"动词 + 得/不 + 补语","vi":"Cụm động bổ dạng khả năng hoặc mức độ: có thể hay không thể đạt kết quả.","use":"Ví dụ 看得见, 听不懂, 吃得完.","ex":[["我听不懂他的话。","Wǒ tīng bù dǒng tā dehuà.","Tôi không nghe hiểu lời anh ấy."],["这些菜我吃得完。","Zhèxiē cài wǒ chī de wán.","Tôi ăn hết được chỗ món này."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-034","hsk30_level":"3","official":["o-3-034"],"title":"数量重叠","py":"Shùliàng chóngdié","func":"短语 › 结构类型","struct":"数词 + 量词 + 数词 + 量词","vi":"Lặp số lượng để nhấn từng đơn vị nối tiếp hoặc theo kiểu.","use":"Ví dụ 一个一个, 一件一件, 一步一步.","ex":[["请大家一个一个地说。","Qǐng dàjiā yī ge yī ge de shuō.","Mời mọi người nói từng người một."],["他一步一步往前走。","Tā yī bù yī bù wǎng qián zǒu.","Anh ấy từng bước một đi về phía trước."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-035","hsk30_level":"3","official":["o-3-035"],"title":"不A不B","py":"BùAbùB","func":"短语 › 固定短语","struct":"不 + A + 不 + B","vi":"Kết cấu bốn chữ phủ định cả hai cực, nghĩa vừa phải, không thừa thiếu.","use":"Ví dụ 不多不少, 不大不小, 不冷不热.","ex":[["这件衣服不大不小，正合适。","Zhè jiàn yīfu bùdà bù xiǎo, zhèng héshì.","Chiếc áo này không to không nhỏ, vừa vặn."],["今天不冷不热，很舒服。","Jīntiān bù lěng bù rè, hěn shūfu.","Hôm nay không lạnh không nóng, rất dễ chịu."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-036","hsk30_level":"3","official":["o-3-036"],"title":"不一会儿","py":"Bùyīhuǐr","func":"短语 › 固定短语","struct":"不一会儿 (+ 就/便) + 动词","vi":"Một lát sau, chẳng bao lâu.","use":"Dùng cho việc đã xảy ra, đặt đầu câu hoặc sau chủ ngữ.","ex":[["他进去了，不一会儿就出来了。","Tā jìnqù le, bùyīhuǐr jiù chūlái le.","Anh ấy đi vào, chẳng bao lâu đã đi ra."],["不一会儿，雨就停了。","Bùyīhuǐr, yǔ jiù tíng le.","Một lát sau mưa tạnh."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-038","hsk30_level":"3","official":["o-3-038"],"title":"在……看来","py":"Zài……kànlai","func":"短语 › 固定短语","struct":"在 + 人 + 看来，句子","vi":"Trong mắt ai, theo quan điểm của ai.","use":"Nêu nhận xét; phần giữa là người.","ex":[["在我看来，这个办法很好。","Zài wǒ kànlai, zhè ge bànfǎ hěn hǎo.","Theo tôi thấy, cách này rất tốt."],["在老师看来，他很努力。","Zài lǎoshī kànlai, tā hěn nǔlì.","Theo giáo viên, cậu ấy rất chăm."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-041","hsk30_level":"3","official":["o-3-041"],"title":"看上去","py":"Kànshangqu","func":"短语 › 固定短语","struct":"主语 + 看上去 + 形容词/小句","vi":"Nhìn có vẻ, trông như.","use":"Nhận xét dựa trên vẻ bề ngoài.","ex":[["他看上去很年轻。","Tā kànshangqu hěn niánqīng.","Anh ấy trông rất trẻ."],["这道菜看上去很好吃。","Zhè dào cài kànshangqu hěn hǎochī.","Món này trông rất ngon."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-042","hsk30_level":"3","official":["o-3-042"],"title":"一般来说","py":"Yībānláishuō","func":"短语 › 固定短语","struct":"一般来说，句子","vi":"Nói chung, thông thường.","use":"Mở đầu câu nêu quy luật chung.","ex":[["一般来说，冬天比较冷。","Yībānláishuō, dōngtiān bǐjiào lěng.","Nói chung mùa đông khá lạnh."],["一般来说，他八点上班。","Yībānláishuō, tā bā diǎn shàngbān.","Thông thường anh ấy đi làm lúc tám giờ."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-043","hsk30_level":"3","official":["o-3-043"],"title":"不怎么样","py":"Bùzěnmeyàng","func":"短语 › 固定短语","struct":"主语 + 不怎么样","vi":"Không ra sao, không tốt lắm.","use":"Khẩu ngữ, đánh giá hơi tiêu cực.","ex":[["这家饭店不怎么样。","Zhè jiā fàndiàn bùzěnmeyàng.","Quán này không ra sao."],["今天的天气不怎么样。","Jīntiān de tiānqì bùzěnmeyàng.","Thời tiết hôm nay không tốt lắm."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-045","hsk30_level":"3","official":["o-3-045"],"title":"从……起","py":"Cóng……qǐ","func":"固定格式","struct":"从 + 时间/地点 + 起","vi":"Bắt đầu từ lúc hoặc nơi nào.","use":"Thường gặp ở thông báo, quy định.","ex":[["从明天起，我每天跑步。","Cóng míngtiān qǐ, wǒ měi tiān pǎobù.","Từ ngày mai tôi chạy bộ mỗi ngày."],["从这儿起，路变窄了。","Cóng zhèr qǐ, lù biàn zhǎi le.","Từ chỗ này đường hẹp lại."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-046","hsk30_level":"3","official":["o-3-046"],"title":"对……来说","py":"Duì……lái shuō","func":"固定格式","struct":"对 + 人/事 + 来说，句子","vi":"Đối với ai thì, xét về.","use":"Nêu góc nhìn để đánh giá.","ex":[["对学生来说，时间很重要。","Duì xuésheng lái shuō, shíjiān hěn zhòngyào.","Đối với học sinh, thời gian rất quan trọng."],["对我来说，这不难。","Duì wǒ lái shuō, zhè bùnán.","Với tôi, việc này không khó."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-047","hsk30_level":"3","official":["o-3-047"],"title":"一……也/都+不/没……","py":"Yī……yě/dōu+bù/méi……","func":"固定格式","struct":"一 + 量词 + (名词) + 也/都 + 不/没 + 动词","vi":"Nhấn mạnh phủ định tuyệt đối: một cái cũng không.","use":"Sau 一 là lượng từ; 都/也 đứng trước 不/没.","ex":[["他一个人也没来。","Tā yī gèrén yě méi lái.","Một người cũng không đến."],["我一口水都没喝。","Wǒ yī kǒushuǐ dōu méi hē.","Tôi một ngụm nước cũng chưa uống."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-049","hsk30_level":"3","official":["o-3-049"],"title":"越……越……","py":"Yuè……yuè……","func":"固定格式","struct":"越 + A，越 + B","vi":"Càng... càng...: mức A tăng thì mức B tăng theo.","use":"Có thể dùng 越来越 cho tăng dần theo thời gian.","ex":[["他越说越快。","Tā yuè shuō yuè kuài.","Anh ấy càng nói càng nhanh."],["雨越下越大。","Yǔ yuè xià yuè dà.","Mưa càng rơi càng to."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-051","hsk30_level":"3","official":["o-3-051"],"title":"X什么（啊）","py":"Xshénme（a）","func":"固定格式","struct":"X + 什么 (啊)","vi":"Dùng để phản bác nhẹ, nghĩa là sao lại, làm gì mà.","use":"Lặp lại từ người kia vừa nói rồi thêm 什么.","ex":[["急什么啊，还有时间。","Jí shénme a, háiyǒu shíjiān.","Vội gì chứ, còn thời gian mà."],["哭什么，没事的。","Kū shénme, méi shì de.","Khóc gì chứ, không sao đâu."]],"note":"Giọng điệu thân mật.","origin":"hanziai-authored"},{"id":"a-o-3-052","hsk30_level":"3","official":["o-3-052"],"title":"该……了","py":"Gāi……le","func":"固定格式","struct":"该 + 动词 + 了","vi":"Đến lúc phải làm gì rồi.","use":"Nhắc đã tới lúc hay thứ tự.","ex":[["十点了，该睡觉了。","Shí diǎn le, gāi shuìjiào le.","Mười giờ rồi, đến lúc đi ngủ."],["该你了。","Gāi nǐ le.","Đến lượt bạn."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-054","hsk30_level":"3","official":["o-3-054"],"title":"动词/形容词性短语作主语","py":"Dòng cí/xíngróng cí xìng duǎn yǔ zuò zhǔ yǔ","func":"句子成分 › 主语","struct":"动词(短语)/形容词(短语) + 谓语","vi":"Động từ hoặc tính từ làm chủ ngữ để nói một hoạt động hay tính chất.","use":"Vị ngữ thường là 是, 很, 对... .","ex":[["游泳对身体很好。","Yóuyǒng duì shēntǐ hěn hǎo.","Bơi lội rất tốt cho sức khỏe."],["诚实很重要。","Chéngshí hěn zhòngyào.","Trung thực rất quan trọng."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-055","hsk30_level":"3","official":["o-3-055"],"title":"主谓短语作主语","py":"Zhǔ wèi duǎn yǔ zuò zhǔ yǔ","func":"句子成分 › 主语","struct":"主谓短语 + 谓语","vi":"Cụm chủ vị làm chủ ngữ cả câu.","use":"Hay đi với 是, 很, 不容易.","ex":[["他来不来没关系。","Tā lái bù lái méiguānxi.","Anh ấy đến hay không không sao."],["你说得对。","Nǐ shuō de duì.","Bạn nói đúng."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-056","hsk30_level":"3","official":["o-3-056"],"title":"多项定语","py":"Duō xiàng dìng yǔ","func":"句子成分 › 定语","struct":"限定 + 数量 + 描写 + 名词","vi":"Nhiều định ngữ trước một danh từ, theo thứ tự thường gặp.","use":"Thứ tự: sở hữu, chỉ thị/số lượng, tính chất, danh từ.","ex":[["我的那三本新书在桌子上。","Wǒ de nà sān běn xīn shū zài zhuōzi shàng.","Ba quyển sách mới kia của tôi ở trên bàn."],["她是一位很漂亮的中国女孩。","Tā shì yī wèi hěn piàoliang de Zhōngguó nǚ hái.","Cô ấy là một cô gái Trung Quốc rất xinh."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-057","hsk30_level":"3","official":["o-3-057"],"title":"结果补语2：到/住/走/上","py":"Jiēguǒ bǔ yǔ2: dào/zhù/zǒu/shàng","func":"句子成分 › 补语","struct":"动词 + 到/住/走/上","vi":"Bổ ngữ kết quả: 到 đạt tới, 住 giữ chặt, 走 rời đi, 上 khép lại hoặc đạt.","use":"Ví dụ 找到, 记住, 拿走, 关上.","ex":[["我找到了钥匙。","Wǒ zhǎodào le yàoshi.","Tôi tìm thấy chìa khóa rồi."],["请记住这个词。","Qǐng jìzhu zhè ge cí.","Hãy nhớ kỹ từ này."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-064","hsk30_level":"3","official":["o-3-064"],"title":"数量补语3：动作结束到某个时间点的间隔","py":"Shùliàng bǔ yǔ3: dòngzuò jiéshù dào mǒu ge shíjiān diǎn de jiàngé","func":"句子成分 › 补语","struct":"动词 + 了 + 时间 + 了","vi":"Bổ ngữ thời lượng nói từ khi việc kết thúc tới nay đã bao lâu.","use":"Thường với 来, 去, 到, 死, 毕业: 毕业三年了.","ex":[["他走了三天了。","Tā zǒu le sān tiān le.","Anh ấy đi được ba ngày rồi."],["我们毕业两年了。","Wǒmen bìyè liǎng nián le.","Chúng tôi tốt nghiệp hai năm rồi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-065","hsk30_level":"3","official":["o-3-065"],"title":"“怎样+动词”的特指问句","py":"“Zěnyàng+dòng cí”de tè zhǐ wèn jù","func":"句子的类型 › 句类","struct":"怎样 + 动词","vi":"Hỏi cách thức làm việc gì.","use":"怎样 đứng trước động từ, gần như 怎么.","ex":[["怎样才能学好汉语？","Zěnyàng cáinéng xué hǎo Hànyǔ?","Làm thế nào mới học giỏi tiếng Hán?"],["这个字怎样写？","Zhè ge zì zěnyàng xiě?","Chữ này viết thế nào?"]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-073","hsk30_level":"3","official":["o-3-073"],"title":"比较句：A比B+更/还+形容词","py":"Bǐjiào jù: AbǐB+gēng/hái+xíngróng cí","func":"句子的类型 › 特殊句型","struct":"A + 比 + B + 更/还 + 形容词","vi":"So sánh nhấn mức cao hơn nữa; B đã có mức nhất định.","use":"Không dùng 很 sau 比.","ex":[["今天比昨天更冷。","Jīntiān bǐ zuótiān gēng lěng.","Hôm nay còn lạnh hơn hôm qua."],["他比我还高。","Tā bǐ wǒ hái gāo.","Anh ấy còn cao hơn tôi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-074","hsk30_level":"3","official":["o-3-074"],"title":"比较句：A跟B一样","py":"Bǐjiào jù: AgēnByīyàng","func":"句子的类型 › 特殊句型","struct":"A + 跟 + B + 一样","vi":"A giống B.","use":"Phủ định dùng 不一样.","ex":[["我的书跟你的一样。","Wǒ de shū gēn nǐ de yīyàng.","Sách của tôi giống của bạn."],["他跟我一样大。","Tā gēn wǒ yīyàng dà.","Anh ấy bằng tuổi tôi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-075","hsk30_level":"3","official":["o-3-075"],"title":"比较句：A跟B一样+形容词","py":"Bǐjiào jù: AgēnByīyàng+xíngróng cí","func":"句子的类型 › 特殊句型","struct":"A + 跟 + B + 一样 + 形容词","vi":"A bằng B về tính chất nào đó.","use":"Tính từ đứng cuối.","ex":[["这个跟那个一样贵。","Zhè ge gēn nà ge yīyàng guì.","Cái này đắt bằng cái kia."],["他跟哥哥一样高。","Tā gēn gēge yīyàng gāo.","Anh ấy cao bằng anh trai."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-076","hsk30_level":"3","official":["o-3-076"],"title":"比较句：A不比B+形容词","py":"Bǐjiào jù: Abù bǐB+xíngróng cí","func":"句子的类型 › 特殊句型","struct":"A + 不比 + B + 形容词","vi":"A không hơn B; có khi nghĩa là ngang nhau hoặc phản bác.","use":"Khác với 没有.","ex":[["我不比他高。","Wǒ bù bǐ tā gāo.","Tôi không cao hơn anh ấy."],["这个不比那个贵。","Zhè ge bù bǐ nà ge guì.","Cái này không đắt hơn cái kia."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-077","hsk30_level":"3","official":["o-3-077"],"title":"比较句：A比B+多/少/早/晚+动词+数量","py":"Bǐjiào jù: AbǐB+duō/shǎo/zǎo/wǎn+dòng cí+shùliàng","func":"句子的类型 › 特殊句型","struct":"A + 比 + B + 多/少/早/晚 + 动词 + 数量短语","vi":"So sánh lượng hay thời gian của hành động.","use":"多/少/早/晚 đặt trước động từ.","ex":[["他比我多学了两年。","Tā bǐ wǒ duō xué le liǎng nián.","Anh ấy học nhiều hơn tôi hai năm."],["她比我早到了十分钟。","Tā bǐ wǒ zǎo dào le shífēn zhōng.","Cô ấy đến sớm hơn tôi mười phút."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-078","hsk30_level":"3","official":["o-3-078"],"title":"存现句：表示出现","py":"Cún xiàn jù: biǎoshì chūxiàn","func":"句子的类型 › 特殊句型","struct":"处所词 + 动词 + 补语 + 了 + 数量 + 人/物","vi":"Câu tồn hiện nói có người hoặc vật xuất hiện ở nơi nào.","use":"Chủ ngữ là nơi chốn, tân ngữ là vật mới xuất hiện.","ex":[["前面走来了一个人。","Qiánmiàn zǒu lái le yī gèrén.","Phía trước có một người đi tới."],["桌子上多了一本书。","Zhuōzi shàng duō le yī běn shū.","Trên bàn có thêm một quyển sách."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-079","hsk30_level":"3","official":["o-3-079"],"title":"存现句：表示消失","py":"Cún xiàn jù: biǎoshì xiāoshī","func":"句子的类型 › 特殊句型","struct":"处所词 + 动词 + 结果补语 + 了 + 数量 + 人/物","vi":"Câu tồn hiện nói có người hoặc vật biến mất khỏi nơi nào.","use":"Thường dùng 跑, 丢, 死, 走.","ex":[["我们班走了两个同学。","Wǒmen bān zǒu le liǎng ge tóngxué.","Lớp chúng tôi có hai bạn chuyển đi."],["书架上少了一本书。","Shūjià shàng shǎo le yī běn shū.","Giá sách mất một quyển."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-080","hsk30_level":"3","official":["o-3-080"],"title":"“是……的”句：强调看法或态度","py":"“Shì……de”jù: qiángdiào kànfǎ huò tàidu","func":"句子的类型 › 特殊句型","struct":"主语 + 是 + 形容词/动词短语 + 的","vi":"Nhấn mạnh quan điểm hay thái độ của người nói chứ không phải việc đã xảy ra.","use":"Khác 是……的 chỉ thời gian nơi chốn.","ex":[["我是支持你的。","Wǒ shì zhīchí nǐ de.","Tôi ủng hộ bạn."],["他是不会同意的。","Tā shì bù huì tóngyì de.","Anh ấy sẽ không đồng ý đâu."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-081","hsk30_level":"3","official":["o-3-081"],"title":"重动句","py":"Zhòng dòng jù","func":"句子的类型 › 特殊句型","struct":"主语 + 动词 + 宾语 + 动词 + 补语","vi":"Câu lặp động từ khi vừa có tân ngữ vừa có bổ ngữ.","use":"Động từ thứ nhất có thể lược nếu đã có tân ngữ.","ex":[["他说汉语说得很好。","Tā shuō Hànyǔ shuō de hěn hǎo.","Anh ấy nói tiếng Hán rất giỏi."],["她看书看了两个小时。","Tā kàn shū kàn le liǎng ge xiǎoshí.","Cô ấy đọc sách hai tiếng."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-082","hsk30_level":"3","official":["o-3-082"],"title":"先……，再/然后……","py":"Xiān……, zài/ránhòu……","func":"句子的类型 › 复句","struct":"先 + 动作1，再/然后 + 动作2","vi":"Câu ghép nối tiếp: làm việc một rồi mới tới việc hai.","use":"Có thể dùng 接着, 最后.","ex":[["我们先吃饭，再去看电影。","Wǒmen xiān chīfàn, zài qù kàn diànyǐng.","Chúng ta ăn cơm trước rồi đi xem phim."],["他先洗手，然后吃饭。","Tā xiān xǐ shǒu, ránhòu chīfàn.","Anh ấy rửa tay trước rồi ăn."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-083","hsk30_level":"3","official":["o-3-083"],"title":"或者……，或者……","py":"Huòzhě……, huòzhě……","func":"句子的类型 › 复句","struct":"或者 + A，或者 + B","vi":"Hoặc A hoặc B, chọn một trong hai.","use":"Dùng trong câu trần thuật; câu hỏi dùng 还是.","ex":[["周末或者看电影，或者去公园。","Zhōumò huòzhě kàn diànyǐng, huòzhě qù gōngyuán.","Cuối tuần hoặc xem phim hoặc đi công viên."],["你或者打电话，或者发短信。","Nǐ huòzhě dǎdiànhuà, huòzhě fā duǎnxìn.","Bạn gọi điện hoặc nhắn tin đều được."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-084","hsk30_level":"3","official":["o-3-084"],"title":"一会儿……，一会儿……","py":"Yīhuìr……, yīhuìr……","func":"句子的类型 › 复句","struct":"一会儿 + A，一会儿 + B","vi":"Lúc thì A lúc thì B, thay đổi nhanh.","use":"A, B thường là hai trạng thái trái nhau.","ex":[["天气一会儿冷，一会儿热。","Tiānqì yīhuìr lěng, yīhuìr rè.","Thời tiết lúc lạnh lúc nóng."],["他一会儿笑，一会儿哭。","Tā yīhuìr xiào, yīhuìr kū.","Anh ấy lúc cười lúc khóc."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-085","hsk30_level":"3","official":["o-3-085"],"title":"又……，又……","py":"Yòu……, yòu……","func":"句子的类型 › 复句","struct":"又 + A，又 + B","vi":"Vừa A vừa B: hai tính chất cùng có.","use":"A, B cùng loại (cùng tốt hay cùng xấu).","ex":[["这家的菜又好吃又便宜。","Zhè jiā de cài yòu hǎochī yòu biànyí.","Món quán này vừa ngon vừa rẻ."],["她又聪明又努力。","Tā yòu cōngming yòu nǔlì.","Cô ấy vừa thông minh vừa chăm."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-086","hsk30_level":"3","official":["o-3-086"],"title":"一边……，一边……","py":"Yībiān……, yībiān……","func":"句子的类型 › 复句","struct":"一边 + 动作1，一边 + 动作2","vi":"Vừa làm việc này vừa làm việc kia cùng lúc.","use":"Cùng một chủ ngữ, hai động từ.","ex":[["他一边走路，一边听音乐。","Tā yībiān zǒulù, yībiān tīng yīnyuè.","Anh ấy vừa đi vừa nghe nhạc."],["我们一边吃饭，一边聊天。","Wǒmen yībiān chīfàn, yībiān liáotiān.","Chúng tôi vừa ăn vừa trò chuyện."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-087","hsk30_level":"3","official":["o-3-087"],"title":"不但……，而且……","py":"Bùdàn……, érqiě……","func":"句子的类型 › 复句","struct":"不但 + A，而且 + B","vi":"Không những A mà còn B (递进).","use":"Vế sau nặng hơn; 也/还 hay đi kèm.","ex":[["他不但会说汉语，而且会写汉字。","Tā bùdàn huì shuō Hànyǔ, érqiě huì xiě hànzì.","Anh ấy không những nói được mà còn viết được chữ Hán."],["这里不但漂亮，而且很安静。","Zhèlǐ bùdàn piàoliang, érqiě hěn ānjìng.","Chỗ này không những đẹp mà còn yên tĩnh."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-088","hsk30_level":"3","official":["o-3-088"],"title":"虽然……，可是……","py":"Suīrán……, kěshì……","func":"句子的类型 › 复句","struct":"虽然 + A，可是 + B","vi":"Tuy A nhưng B (转折).","use":"可是 thay 但是, khẩu ngữ hơn.","ex":[["虽然很累，可是我很高兴。","Suīrán hěn lěi, kěshì wǒ hěn gāoxìng.","Tuy mệt nhưng tôi rất vui."],["虽然他年纪小，可是懂很多。","Suīrán tā niánjì xiǎo, kěshì dǒng hěn duō.","Tuy còn nhỏ nhưng cậu ấy hiểu nhiều."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-089","hsk30_level":"3","official":["o-3-089"],"title":"如果……，就……","py":"Rúguǒ……, jiù……","func":"句子的类型 › 复句","struct":"如果 + 条件，(主语) 就 + 结果","vi":"Nếu... thì...: giả thiết.","use":"就 đứng trước động từ vế sau.","ex":[["如果明天下雨，我就不去了。","Rúguǒ míngtiān xiàyǔ, wǒ jiù bù qù le.","Nếu mai mưa thì tôi không đi."],["如果你有时间，就来看我。","Rúguǒ nǐ yǒushí jiān, jiù lái kàn wǒ.","Nếu bạn rảnh thì đến thăm tôi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-090","hsk30_level":"3","official":["o-3-090"],"title":"……的话，就……","py":"……Dehuà, jiù……","func":"句子的类型 › 复句","struct":"条件 + 的话，就 + 结果","vi":"的话 đặt cuối vế giả thiết, nghĩa như nếu.","use":"Có thể kết hợp 如果……的话.","ex":[["你不想去的话，就别去。","Nǐ bù xiǎng qù dehuà, jiù bié qù.","Nếu bạn không muốn đi thì đừng đi."],["下雨的话，我们就在家。","Xiàyǔ dehuà, wǒmen jiù zàijiā.","Nếu mưa thì chúng ta ở nhà."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-091","hsk30_level":"3","official":["o-3-091"],"title":"只有……，才……","py":"Zhǐyǒu……, cái……","func":"句子的类型 › 复句","struct":"只有 + 条件，才 + 结果","vi":"Chỉ có... mới...: điều kiện duy nhất.","use":"才 đứng trước động từ vế sau.","ex":[["只有努力，才能成功。","Zhǐyǒu nǔlì, cáinéng Chénggōng.","Chỉ có cố gắng mới thành công."],["只有你去，他才会来。","Zhǐyǒu nǐ qù, tā cái huì lái.","Chỉ khi bạn đi anh ấy mới đến."]],"note":"Khác 只要: 只要 là điều kiện đủ.","origin":"hanziai-authored"},{"id":"a-o-3-092","hsk30_level":"3","official":["o-3-092"],"title":"只要……，就……","py":"Zhǐyào……, jiù……","func":"句子的类型 › 复句","struct":"只要 + 条件，就 + 结果","vi":"Chỉ cần... là...: điều kiện đủ.","use":"Điều kiện nhẹ hơn 只有.","ex":[["只要你来，我就高兴。","Zhǐyào nǐ lái, wǒ jiù gāoxìng.","Chỉ cần bạn đến là tôi vui."],["只要努力，就会进步。","Zhǐyào nǔlì, jiù huì jìnbù.","Chỉ cần cố gắng là sẽ tiến bộ."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-093","hsk30_level":"3","official":["o-3-093"],"title":"为了……，……","py":"Wèile……, ……","func":"句子的类型 › 复句","struct":"为了 + 目的，(主语) + 行动","vi":"Để... thì...: nêu mục đích trước, hành động sau.","use":"为了 đứng đầu vế đầu.","ex":[["为了学好汉语，他每天练习。","Wèile xué hǎo Hànyǔ, tā měi tiān liànxí.","Để học giỏi tiếng Hán, anh ấy luyện mỗi ngày."],["为了健康，我不抽烟。","Wèile jiànkāng, wǒ bù chōuyān.","Vì sức khỏe, tôi không hút thuốc."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-094","hsk30_level":"3","official":["o-3-094"],"title":"……了……（就）……","py":"……Le……（jiù）……","func":"句子的类型 › 复句","struct":"动作1 + 了 + (宾语) + (就) + 动作2","vi":"Câu rút gọn: xong việc một thì làm việc hai.","use":"Hai hành động nối tiếp, 了 gắn với việc thứ nhất.","ex":[["他吃了饭就走了。","Tā chī le fàn jiù zǒu le.","Anh ấy ăn xong là đi."],["下了课我就回家。","Xià le kè wǒ jiù huíjiā.","Tan học là tôi về nhà."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-3-095","hsk30_level":"3","official":["o-3-095"],"title":"概数表达法：用“大概”","py":"Gài shù biǎodá fǎ: yòng“dàgài”","func":"特殊表达法 › 数的表达法","struct":"大概 + 数量短语","vi":"大概 đặt trước số lượng để nói ước chừng.","use":"Khác với 几, 多.","ex":[["大概有五十个人来了。","Dàgài yǒu wǔ shí gèrén lái le.","Khoảng năm mươi người đã đến."],["他大概三十岁。","Tā dàgài sān shí suì.","Anh ấy khoảng ba mươi tuổi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-024","hsk30_level":"4","official":["o-4-024"],"title":"数词+形容词+量词","py":"Shù cí+xíngróng cí+liàng cí","func":"短语 › 结构类型","struct":"数词 + 形容词 + 量词 + 名词","vi":"Cụm số từ + tính từ + lượng từ, tính từ thường là 大, 小, 长, 整.","use":"Ví dụ 一大杯, 两小碗, 三长条.","ex":[["请给我来一大杯咖啡。","Qǐng gěi wǒ lái yī dà bēi kāfēi.","Cho tôi một ly cà phê lớn."],["他买了两大袋水果。","Tā mǎi le liǎng dà dài shuǐguǒ.","Anh ấy mua hai túi lớn hoa quả."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-025","hsk30_level":"4","official":["o-4-025"],"title":"一A一B","py":"YīAyīB","func":"短语 › 固定短语","struct":"一 + A + 一 + B","vi":"Kết cấu bốn chữ: A, B là hai thành phần đối ứng hoặc nối tiếp, nhấn động tác lần lượt.","use":"Ví dụ 一来一往, 一问一答, 一上一下.","ex":[["他们一问一答，聊得很开心。","Tāmen yī wèn yī dá, liáo de hěn kāixīn.","Họ hỏi đáp qua lại, trò chuyện vui vẻ."],["球一上一下地跳着。","Qiú yī shàng yī xià de tiào zhe.","Quả bóng nảy lên nảy xuống."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-026","hsk30_level":"4","official":["o-4-026"],"title":"无A无B","py":"WúAwúB","func":"短语 › 固定短语","struct":"无 + A + 无 + B","vi":"Kết cấu bốn chữ nghĩa không A không B.","use":"Ví dụ 无亲无故, 无声无息.","ex":[["他无亲无故，一个人生活。","Tā wú qīn wúgù, yī gèrén shēnghuó.","Anh ấy không thân thích, sống một mình."],["小偷无声无息地走了。","Xiǎotōu wú shēng wú xī de zǒu le.","Tên trộm lặng lẽ bỏ đi."]],"note":"Văn viết.","origin":"hanziai-authored"},{"id":"a-o-4-027","hsk30_level":"4","official":["o-4-027"],"title":"有A有B","py":"YǒuAyǒuB","func":"短语 › 固定短语","struct":"有 + A + 有 + B","vi":"Kết cấu bốn chữ nghĩa có A có B, đầy đủ.","use":"Ví dụ 有说有笑, 有声有色, 有头有尾.","ex":[["他们有说有笑地走进来。","Tāmen yǒu shuō yǒu xiào de zǒujìn lái.","Họ vừa nói vừa cười đi vào."],["他讲得有声有色。","Tā jiǎng de yǒushēngyǒusè.","Anh ấy kể rất sinh động."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-029","hsk30_level":"4","official":["o-4-029"],"title":"有的是","py":"Yǒudeshì","func":"短语 › 固定短语","struct":"主语 + 有的是 + 名词","vi":"Có rất nhiều, không thiếu.","use":"Khẩu ngữ, dùng nhấn mạnh có nhiều.","ex":[["我有的是时间。","Wǒ yǒudeshì shíjiān.","Tôi có thừa thời gian."],["这里有的是好吃的。","Zhèlǐ yǒudeshì hǎochī de.","Ở đây thiếu gì đồ ngon."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-031","hsk30_level":"4","official":["o-4-031"],"title":"不怎么","py":"Bùzěnme","func":"短语 › 固定短语","struct":"不怎么 + 形容词/动词","vi":"Không ... lắm, mức độ nhẹ.","use":"Nhẹ hơn 不太.","ex":[["我不怎么喜欢吃辣的。","Wǒ bùzěnme xǐhuan chī là de.","Tôi không thích ăn cay lắm."],["他不怎么说话。","Tā bùzěnme shuōhuà.","Anh ấy ít nói."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-032","hsk30_level":"4","official":["o-4-032"],"title":"就是说/这就是说","py":"Jiùshìshuō/zhèjiùshìshuō","func":"短语 › 固定短语","struct":"前句，就是说，后句","vi":"Nói cách khác, tức là: giải thích lại ý trước.","use":"Đứng giữa hai câu, ngắt bằng dấu phẩy.","ex":[["你不去，就是说你不同意？","Nǐ bù qù, jiùshìshuō nǐ bùtóng yì?","Bạn không đi, tức là bạn không đồng ý?"],["他明天不在，这就是说我们得改时间。","Tā míngtiān bù zài, zhèjiùshìshuō wǒmen de gǎi shíjiān.","Mai anh ấy không có đây, nghĩa là ta phải đổi giờ."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-033","hsk30_level":"4","official":["o-4-033"],"title":"一+量词+比+一+量词","py":"Yī+liàng cí+bǐ+yī+liàng cí","func":"固定格式","struct":"一 + 量词 + 比 + 一 + 量词 + 形容词","vi":"Càng ngày càng, mỗi cái hơn cái trước.","use":"Ví dụ 一天比一天好.","ex":[["天气一天比一天冷。","Tiānqì yī tiān bǐ yī tiān lěng.","Trời ngày càng lạnh."],["他的汉语一年比一年好。","Tā de Hànyǔ yī nián bǐ yī nián hǎo.","Tiếng Hán của anh ấy năm sau tốt hơn năm trước."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-034","hsk30_level":"4","official":["o-4-034"],"title":"在……方面","py":"Zài……fāngmiàn","func":"固定格式","struct":"在 + 名词 + 方面","vi":"Về mặt, trong lĩnh vực.","use":"Dùng đầu câu giới hạn phạm vi.","ex":[["在学习方面，他很努力。","Zài xuéxí fāngmiàn, tā hěn nǔlì.","Về việc học, anh ấy rất chăm."],["在这方面我是外行。","Zài zhè fāngmiàn wǒ shì wàiháng.","Về mặt này tôi là người ngoại đạo."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-035","hsk30_level":"4","official":["o-4-035"],"title":"够……的","py":"Gòu……de","func":"固定格式","struct":"主语 + 够 + 形容词 + 的","vi":"Khá, đủ là (nhấn mạnh mức độ cao, thường hơi quá).","use":"Khẩu ngữ.","ex":[["这天气够冷的。","Zhè tiānqì gòu lěng de.","Trời này lạnh thật."],["他够忙的。","Tā gòu máng de.","Anh ấy bận thật đấy."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-036","hsk30_level":"4","official":["o-4-036"],"title":"拿……来说","py":"Ná……lái shuō","func":"固定格式","struct":"拿 + 名词 + 来说，句子","vi":"Lấy... mà nói: nêu ví dụ.","use":"Đi trước ví dụ minh họa.","ex":[["拿我来说，每天都很忙。","Ná wǒ lái shuō, měi tiān dōu hěn máng.","Lấy tôi mà nói, ngày nào cũng bận."],["拿北京来说，冬天很冷。","Ná Běijīng lái shuō, dōngtiān hěn lěng.","Lấy Bắc Kinh làm ví dụ, mùa đông rất lạnh."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-037","hsk30_level":"4","official":["o-4-037"],"title":"再也不/没……","py":"Zàiyě bù/méi……","func":"固定格式","struct":"再也 + 不/没 + 动词","vi":"Không bao giờ nữa.","use":"Nhấn việc sẽ không lặp lại.","ex":[["我再也不迟到了。","Wǒ zàiyě bù chídào le.","Tôi sẽ không bao giờ đến muộn nữa."],["他再也没来过。","Tā zàiyě méi lái guò.","Anh ấy chưa từng đến lại."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-038","hsk30_level":"4","official":["o-4-038"],"title":"怎么都/也+不/没……","py":"Zěnme dōu/yě+bù/méi……","func":"固定格式","struct":"怎么 + 都/也 + 不/没 + 动词","vi":"Làm thế nào cũng không.","use":"Nhấn nỗ lực mà không có kết quả.","ex":[["这个字我怎么也写不好。","Zhè ge zì wǒ zěnme yě xiě bù hǎo.","Chữ này tôi viết mãi không đẹp."],["门怎么都打不开。","Mén zěnme dōu dǎ bù kāi.","Cửa mở thế nào cũng không ra."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-039","hsk30_level":"4","official":["o-4-039"],"title":"为了……而……","py":"Wèile……ér……","func":"固定格式","struct":"为了 + 目的 + 而 + 动词","vi":"Vì... mà...: nêu mục đích của hành động.","use":"而 nối mục đích và hành động.","ex":[["他为了梦想而努力。","Tā wèile mèngxiǎng ér nǔlì.","Anh ấy nỗ lực vì ước mơ."],["我们为了和平而工作。","Wǒmen wèile Hépíng ér gōngzuò.","Chúng ta làm việc vì hòa bình."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-040","hsk30_level":"4","official":["o-4-040"],"title":"动词+一X是一X","py":"Dòng cí+yīXshì yīX","func":"固定格式","struct":"动词 + 一 + 量词 + 是 + 一 + 量词","vi":"Chẳng cần chọn, có bao nhiêu dùng bấy nhiêu.","use":"Ví dụ 吃一口是一口.","ex":[["能吃一口是一口。","Néng chī yī kǒu shì yī kǒu.","Ăn được miếng nào hay miếng đó."],["挣一块是一块。","Zhēng yī kuài shì yī kuài.","Kiếm được đồng nào hay đồng đó."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-041","hsk30_level":"4","official":["o-4-041"],"title":"（没）有什么（好）X的","py":"（Méi）yǒu shénme（hǎo）Xde","func":"固定格式","struct":"(没)有 + 什么 + (好) + 动词 + 的","vi":"Có gì mà phải... (phản vấn nhẹ).","use":"Dùng để thấy việc không đáng.","ex":[["这有什么好怕的？","Zhè yǒu shénme hǎo pà de?","Cái này có gì phải sợ?"],["没什么好说的。","Méishénme hǎoshuō de.","Chẳng có gì để nói."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-042","hsk30_level":"4","official":["o-4-042"],"title":"X是X，Y是Y","py":"XshìX, YshìY","func":"固定格式","struct":"X + 是 + X，Y + 是 + Y","vi":"Phân biệt rạch ròi hai việc, không lẫn lộn.","use":"Hay dùng để tách bạch.","ex":[["工作是工作，生活是生活。","Gōngzuò shì gōngzuò, shēnghuó shì shēnghuó.","Công việc là công việc, cuộc sống là cuộc sống."],["朋友是朋友，规矩是规矩。","Péngyou shì péngyou, guīju shì guīju.","Bạn bè là bạn bè, quy tắc là quy tắc."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-043","hsk30_level":"4","official":["o-4-043"],"title":"X也得X，不X也得X","py":"Xyě deX, bùXyě deX","func":"固定格式","struct":"X + 也得 + X，不 X + 也得 + X","vi":"Dù muốn hay không cũng phải làm.","use":"Nhấn việc bắt buộc.","ex":[["你去也得去，不去也得去。","Nǐ qù yě de qù, bù qù yě de qù.","Bạn đi cũng phải đi, không đi cũng phải đi."],["愿意也得做，不愿意也得做。","Yuànyì yě de zuò, bù yuànyì yě de zuò.","Muốn hay không cũng phải làm."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-044","hsk30_level":"4","official":["o-4-044"],"title":"X就是了","py":"Xjiùshì le","func":"固定格式","struct":"句子 + 就是了","vi":"Cứ... là được, nhấn không cần lo.","use":"Cuối câu, giọng trấn an.","ex":[["你放心去就是了。","Nǐ fàngxīn qù jiùshì le.","Bạn cứ yên tâm đi là được."],["有事找我就是了。","Yǒushì zhǎo wǒ jiùshì le.","Có việc cứ tìm tôi là được."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-045","hsk30_level":"4","official":["o-4-045"],"title":"还X呢","py":"HáiXne","func":"固定格式","struct":"还 + 动词/名词 + 呢","vi":"Còn bảo là... ư (chê trách, mỉa).","use":"Chỉ ra điều trái với điều người kia nói.","ex":[["你还老师呢，这都不懂！","Nǐ hái lǎoshī ne, zhè dōu bù dǒng!","Còn là giáo viên cơ à, cái này mà không hiểu!"],["还说帮我呢，你在哪儿？","Hái shuō bāng wǒ ne, nǐ zài nǎr?","Còn bảo giúp tôi, bạn ở đâu?"]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-046","hsk30_level":"4","official":["o-4-046"],"title":"你X你的吧","py":"NǐXnǐ de ba","func":"固定格式","struct":"你 + 动词 + 你的 + 吧","vi":"Bạn cứ làm việc của bạn đi, đừng bận tâm.","use":"Giọng thoải mái hoặc hơi gắt.","ex":[["你睡你的吧，别管我。","Nǐ shuì nǐ de ba, bié guǎn wǒ.","Bạn cứ ngủ đi, đừng lo cho tôi."],["你吃你的吧。","Nǐ chī nǐ de ba.","Bạn cứ ăn đi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-047","hsk30_level":"4","official":["o-4-047"],"title":"让/叫你X你就X","py":"Ràng/jiào nǐXnǐ jiùX","func":"固定格式","struct":"让/叫 + 你 + 动词 + 你就 + 动词","vi":"Bảo làm gì thì cứ làm đi.","use":"Giọng ra lệnh hoặc khuyên.","ex":[["让你去你就去。","Ràng nǐ qù nǐ jiù qù.","Bảo bạn đi thì cứ đi."],["叫你吃你就吃。","Jiào nǐ chī nǐ jiù chī.","Bảo ăn thì cứ ăn."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-048","hsk30_level":"4","official":["o-4-048"],"title":"说什么/怎么（着）也得X","py":"Shuō shénme/zěnme（zhe）yě deX","func":"固定格式","struct":"说什么/怎么(着) + 也得 + 动词","vi":"Dù thế nào cũng phải.","use":"Nhấn quyết tâm.","ex":[["说什么也得去一趟。","Shuō shénme yě de qù yī tāng.","Dù thế nào cũng phải đi một chuyến."],["怎么着也得吃饭。","Zěnme zhe yě de chīfàn.","Thế nào cũng phải ăn cơm."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-049","hsk30_level":"4","official":["o-4-049"],"title":"X就X（点儿）吧","py":"XjiùX（diǎn r）ba","func":"固定格式","struct":"动词 + 就 + 动词 + (点儿) + 吧","vi":"Thôi thì cứ làm vậy đi, chấp nhận.","use":"Giọng buông xuôi.","ex":[["累就累点儿吧。","Lěi jiù lěi diǎn r ba.","Mệt thì mệt chút vậy."],["贵就贵吧，我买了。","Guì jiù guì ba, wǒ mǎi le.","Đắt thì đắt, tôi mua."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-050","hsk30_level":"4","official":["o-4-050"],"title":"X是X","py":"XshìX","func":"固定格式","struct":"X + 是 + X，(但是) ……","vi":"Thừa nhận X nhưng có điều kiện: đúng là X nhưng...","use":"Thường theo sau là 就是, 不过.","ex":[["好是好，就是太贵。","Hǎo shì hǎo, jiùshì tài guì.","Tốt thì tốt, chỉ là đắt quá."],["累是累，不过很值得。","Lěi shì lěi, bùguò hěn zhíde.","Mệt thì mệt, nhưng đáng."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-053","hsk30_level":"4","official":["o-4-053"],"title":"难道……吗？","py":"Nándào……ma?","func":"句子的类型 › 句类","struct":"难道 + 句子 + 吗？","vi":"Câu hỏi tu từ nhấn mạnh: chẳng lẽ...?","use":"难道 đứng trước vị ngữ.","ex":[["难道你不知道吗？","Nándào nǐ bùzhī dào ma?","Chẳng lẽ bạn không biết?"],["难道他不来吗？","Nándào tā bù lái ma?","Chẳng lẽ anh ấy không đến?"]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-054","hsk30_level":"4","official":["o-4-054"],"title":"由疑问代词构成的反问句","py":"Yóu yíwèn dài cí gòuchéng de fǎnwèn jù","func":"句子的类型 › 句类","struct":"疑问代词 + 动词 (+ 呢)？","vi":"Câu phản vấn dùng đại từ nghi vấn, ý nghĩa ngược lại.","use":"Ví dụ 谁不知道？ = ai cũng biết.","ex":[["谁不想成功呢？","Shéi bù xiǎng Chénggōng ne?","Ai mà chẳng muốn thành công?"],["我怎么知道？","Wǒ zěnme zhīdào?","Làm sao tôi biết được?"]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-055","hsk30_level":"4","official":["o-4-055"],"title":"“把”字句：把+宾语+动词（+一/了）+动词","py":"“Bǎ”zì jù: bǎ+bīn yǔ+dòng cí（+yī/le）+dòng cí","func":"句子的类型 › 句类","struct":"主语 + 把 + 宾语 + 动词重叠/动词 + 一 + 动词","vi":"Câu 把 có động từ lặp hoặc 一, nhẹ nhàng, thử.","use":"Ví dụ 把房间收拾收拾.","ex":[["你把房间收拾收拾。","Nǐ bǎ fángjiān shōushi shōushi.","Bạn dọn dẹp phòng đi."],["请把这件事想一想。","Qǐng bǎ zhè jiàn shì xiǎng yī xiǎng.","Hãy suy nghĩ chuyện này một chút."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-056","hsk30_level":"4","official":["o-4-056"],"title":"“把”字句：把+宾语+动词+了","py":"“Bǎ”zì jù: bǎ+bīn yǔ+dòng cí+le","func":"句子的类型 › 句类","struct":"主语 + 把 + 宾语 + 动词 + 了","vi":"Câu 把 kết thúc bằng 了 nói việc đã xong.","use":"Động từ đa âm không cần thêm bổ ngữ.","ex":[["他把饭吃了。","Tā bǎ fàn chī le.","Anh ấy ăn cơm rồi."],["我把钱花了。","Wǒ bǎ qián huā le.","Tôi tiêu hết tiền rồi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-057","hsk30_level":"4","official":["o-4-057"],"title":"“把”字句：把+宾语+动词+动量/时量补语","py":"“Bǎ”zì jù: bǎ+bīn yǔ+dòng cí+dòng liàng/shí liàng bǔ yǔ","func":"句子的类型 › 句类","struct":"主语 + 把 + 宾语 + 动词 + 数量补语","vi":"Câu 把 kèm bổ ngữ số lần hay thời gian.","use":"Bổ ngữ đứng sau động từ.","ex":[["他把书看了两遍。","Tā bǎ shū kàn le liǎng biàn.","Anh ấy đọc sách hai lượt."],["我把车开了一个小时。","Wǒ bǎ chē kāi le yī ge xiǎoshí.","Tôi lái xe một tiếng."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-058","hsk30_level":"4","official":["o-4-058"],"title":"“把”字句：把+宾语+状语+动词","py":"“Bǎ”zì jù: bǎ+bīn yǔ+zhuàng yǔ+dòng cí","func":"句子的类型 › 句类","struct":"主语 + 把 + 宾语 + 状语 + 动词","vi":"Câu 把 có trạng ngữ trước động từ, như 一下子, 慢慢.","use":"Thường kèm 都, 全, 一口气.","ex":[["他把饭都吃了。","Tā bǎ fàn dōu chī le.","Anh ấy ăn hết cơm."],["她把信一口气读完。","Tā bǎ xìn yīkǒuqì dú wán.","Cô ấy đọc một mạch hết bức thư."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-059","hsk30_level":"4","official":["o-4-059"],"title":"被动句：叫/让+宾语+动词+其他成分","py":"Bèidòng jù: jiào/ràng+bīn yǔ+dòng cí+qítā chéngfèn","func":"句子的类型 › 句类","struct":"主语 + 叫/让 + 施事 + 动词 + 其他成分","vi":"Câu bị động khẩu ngữ dùng 叫 hoặc 让 thay cho 被, bắt buộc có người gây.","use":"Khác 被, 叫/让 không được lược người gây hành động.","ex":[["杯子叫他打破了。","Bēizi jiào tā dǎpò le.","Cái cốc bị anh ấy làm vỡ."],["我的自行车让人骑走了。","Wǒ de zìxíngchē ràng rén qí zǒu le.","Xe đạp của tôi bị người ta đi mất."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-060","hsk30_level":"4","official":["o-4-060"],"title":"兼语句：表爱憎","py":"Jiān yǔ jù: biǎo ài 憎","func":"句子的类型 › 句类","struct":"主语 + 表扬/批评/喜欢 + 宾语1 + 动词 + 宾语2","vi":"Câu kiêm ngữ thể hiện khen, chê, yêu, ghét.","use":"Tân ngữ 1 đồng thời là chủ ngữ của động từ sau.","ex":[["老师表扬他学习努力。","Lǎoshī biǎoyáng tā xuéxí nǔlì.","Thầy khen cậu ấy học chăm."],["妈妈批评我不听话。","Māma pīpíng wǒ bù tīnghuà.","Mẹ phê bình tôi không nghe lời."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-061","hsk30_level":"4","official":["o-4-061"],"title":"兼语句：表称谓或认定","py":"Jiān yǔ jù: biǎo chēng wèi huò rèndìng","func":"句子的类型 › 句类","struct":"主语 + 收/选/叫 + 宾语1 + 做/当/为 + 宾语2","vi":"Câu kiêm ngữ thể hiện xưng hô hoặc xác định thân phận.","use":"Ví dụ 选他当班长.","ex":[["大家选他当班长。","Dàjiā xuǎn tā dāng bānzhǎng.","Mọi người bầu anh ấy làm lớp trưởng."],["我们叫他小王。","Wǒmen jiào tā xiǎo wáng.","Chúng tôi gọi anh ấy là Tiểu Vương."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-062","hsk30_level":"4","official":["o-4-062"],"title":"兼语句：表致使","py":"Jiān yǔ jù: biǎo zhìshǐ","func":"句子的类型 › 句类","struct":"主语 + 使/让 + 人 + 动词短语","vi":"Câu kiêm ngữ nghĩa khiến ai làm hoặc trở nên.","use":"使 thường dùng trong văn viết.","ex":[["这件事让我很感动。","Zhè jiàn shì ràng wǒ hěn gǎndòng.","Chuyện này khiến tôi rất cảm động."],["老师让我们回家。","Lǎoshī ràng wǒmen huíjiā.","Thầy bảo chúng tôi về nhà."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-064","hsk30_level":"4","official":["o-4-064"],"title":"比较句：跟……相比","py":"Bǐjiào jù: gēn……xiāngbǐ","func":"句子的类型","struct":"跟 + B + 相比，A + ……","vi":"So với B thì A...","use":"Đi đầu câu để so sánh tổng thể.","ex":[["跟去年相比，今年更热。","Gēn qùnián xiāngbǐ, jīnnián gēng rè.","So với năm ngoái năm nay nóng hơn."],["跟哥哥相比，他很矮。","Gēn gēge xiāngbǐ, tā hěn ǎi.","So với anh trai cậu ấy thấp."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-065","hsk30_level":"4","official":["o-4-065"],"title":"双重否定表示强调","py":"Shuāngchóng fǒudìng biǎoshì qiángdiào","func":"句子的类型","struct":"不 + 不/没 + 动词；非 + 不可","vi":"Dùng hai lần phủ định để khẳng định mạnh.","use":"Ví dụ 不得不, 没有不, 非……不可.","ex":[["我不得不去。","Wǒ bùdébù qù.","Tôi buộc phải đi."],["没有人不喜欢他。","Méiyǒu rén bù xǐhuan tā.","Không ai là không thích anh ấy."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-066","hsk30_level":"4","official":["o-4-066"],"title":"不是……，而是……","py":"Bù shì……, érshì……","func":"句子的类型 › 复句","struct":"不是 + A，而是 + B","vi":"Không phải A mà là B.","use":"Bác bỏ A, khẳng định B.","ex":[["他不是不想去，而是没时间。","Tā bù shì bù xiǎng qù, érshì méi shíjiān.","Anh ấy không phải không muốn đi mà là không có thời gian."],["这不是问题，而是机会。","Zhè bù shì wèntí, érshì jīhuì.","Đây không phải vấn đề mà là cơ hội."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-068","hsk30_level":"4","official":["o-4-068"],"title":"一方面……，另一方面……","py":"Yīfāngmiàn……, lìngyīfāngmiàn……","func":"句子的类型 › 复句","struct":"一方面 + A，另一方面 + B","vi":"Một mặt... mặt khác...","use":"Liệt kê hai phương diện.","ex":[["一方面要努力，另一方面要休息。","Yīfāngmiàn yào nǔlì, lìngyīfāngmiàn yào xiūxi.","Một mặt phải cố gắng, mặt khác phải nghỉ ngơi."],["一方面他很忙，另一方面他身体不好。","Yīfāngmiàn tā hěn máng, lìngyīfāngmiàn tā shēntǐ bù hǎo.","Một mặt anh ấy bận, mặt khác sức khỏe không tốt."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-072","hsk30_level":"4","official":["o-4-072"],"title":"……，甚至……","py":"……, Shènzhì……","func":"句子的类型 › 复句","struct":"A，甚至 + B","vi":"Thậm chí: nêu mức cao hơn, bất ngờ.","use":"Dùng cho mức độ tăng dần.","ex":[["他很忙，甚至没时间吃饭。","Tā hěn máng, shènzhì méi shíjiān chīfàn.","Anh ấy bận đến mức không có thời gian ăn cơm."],["她喜欢旅行，甚至去过南极。","Tā xǐhuan lǚxíng, shènzhì qù guò nánjí.","Cô ấy thích du lịch, thậm chí từng đến Nam Cực."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-073","hsk30_level":"4","official":["o-4-073"],"title":"不仅/不光……，还/而且……","py":"Bùjǐn/bùguāng……, hái/érqiě……","func":"句子的类型 › 复句","struct":"不仅/不光 + A，还/而且 + B","vi":"Không chỉ A mà còn B.","use":"Giống 不但, khẩu ngữ hơn với 不光.","ex":[["他不仅会唱歌，还会跳舞。","Tā bùjǐn huì chànggē, hái huì tiàowǔ.","Anh ấy không chỉ biết hát mà còn biết nhảy."],["这不光是你的错，而且是我的错。","Zhè bùguāng shì nǐ de cuò, érqiě shì wǒ de cuò.","Đây không chỉ là lỗi của bạn mà cũng là lỗi của tôi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-074","hsk30_level":"4","official":["o-4-074"],"title":"……，并且……","py":"……, Bìngqiě……","func":"句子的类型 › 复句","struct":"A，并且 + B","vi":"Và còn, đồng thời: nối hai việc cùng tồn tại hoặc nối tiếp.","use":"Dùng cho động từ, tính từ.","ex":[["他同意了，并且很高兴。","Tā tóngyì le, bìngqiě hěn gāoxìng.","Anh ấy đồng ý, và còn rất vui."],["我们要学习，并且要实践。","Wǒmen yào xuéxí, bìngqiě yào shíjiàn.","Chúng ta phải học và cũng phải thực hành."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-076","hsk30_level":"4","official":["o-4-076"],"title":"不是……，就是……","py":"Bù shì……, jiùshì……","func":"句子的类型 › 复句","struct":"不是 + A，就是 + B","vi":"Nếu không phải A thì là B: chỉ có hai khả năng.","use":"Cũng chỉ việc lặp lại liên tục.","ex":[["他不是在看书，就是在睡觉。","Tā bù shì zài kàn shū, jiùshì zài shuìjiào.","Anh ấy không đọc sách thì là ngủ."],["周末不是下雨，就是刮风。","Zhōumò bù shì xiàyǔ, jiùshì guāfēng.","Cuối tuần không mưa thì gió."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-077","hsk30_level":"4","official":["o-4-077"],"title":"尽管……，但是/可是……","py":"Jǐnguǎn……, dànshì/kěshì……","func":"句子的类型 › 复句","struct":"尽管 + A，但是/可是 + B","vi":"Mặc dù A nhưng B.","use":"Mạnh hơn 虽然, thừa nhận sự thật.","ex":[["尽管很累，但是他没放弃。","Jǐnguǎn hěn lěi, dànshì tā méi fàngqì.","Mặc dù rất mệt nhưng anh ấy không bỏ cuộc."],["尽管下雨，可是我们照常出发。","Jǐnguǎn xiàyǔ, kěshì wǒmen zhàocháng chūfā.","Dù mưa chúng tôi vẫn lên đường."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-079","hsk30_level":"4","official":["o-4-079"],"title":"……，不过……","py":"……, Bùguò……","func":"句子的类型 › 复句","struct":"A，不过 + B","vi":"Có điều, có điều là: chuyển ý nhẹ.","use":"Vế sau bổ sung lưu ý.","ex":[["这件衣服很好，不过有点儿贵。","Zhè jiàn yīfu hěn hǎo, bùguò yǒudiǎnr guì.","Cái áo này tốt, có điều hơi đắt."],["他很聪明，不过不太努力。","Tā hěn cōngming, bùguò bùtài nǔlì.","Cậu ấy thông minh nhưng không chăm lắm."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-080","hsk30_level":"4","official":["o-4-080"],"title":"……X是X，就是/不过……","py":"……XshìX, jiùshì/bùguò……","func":"句子的类型 › 复句","struct":"X + 是 + X，就是/不过 + ……","vi":"Thừa nhận X nhưng nêu nhược điểm.","use":"Xem thêm o-4-050.","ex":[["这个房子大是大，就是太旧。","Zhè ge fángzi dà shì dà, jiùshì tài jiù.","Căn nhà này to thì to, chỉ là cũ quá."],["好吃是好吃，不过有点儿辣。","Hǎochī shì hǎochī, bùguò yǒudiǎnr là.","Ngon thì ngon, có điều hơi cay."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-082","hsk30_level":"4","official":["o-4-082"],"title":"要是……，就……","py":"Yàoshi……, jiù……","func":"句子的类型 › 复句","struct":"要是 + 条件，就 + 结果","vi":"Nếu như: khẩu ngữ, giống 如果.","use":"Khẩu ngữ hơn 如果.","ex":[["要是你有空，就来玩吧。","Yàoshi nǐ yǒu kōng, jiù lái wán ba.","Nếu bạn rảnh thì đến chơi."],["要是明天下雨，我就不去了。","Yàoshi míngtiān xiàyǔ, wǒ jiù bù qù le.","Nếu mai mưa thì tôi không đi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-083","hsk30_level":"4","official":["o-4-083"],"title":"要是……，（就）……，否则……","py":"Yàoshi……, （jiù）……, fǒuzé……","func":"句子的类型 › 复句","struct":"要是 + A，(就) + B，否则 + C","vi":"Nếu A thì B, nếu không thì C.","use":"否则 nêu hậu quả trái lại.","ex":[["要是你早点儿来，就能赶上，否则会迟到。","Yàoshi nǐ zǎo diǎn r lái, jiù néng gǎnshàng, fǒuzé huì chídào.","Nếu bạn đến sớm sẽ kịp, nếu không sẽ muộn."],["要是认真学，就会进步，否则不行。","Yàoshi rènzhēn xué, jiù huì jìnbù, fǒuzé bùxíng.","Nếu học nghiêm túc sẽ tiến bộ, nếu không thì không."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-086","hsk30_level":"4","official":["o-4-086"],"title":"既然……，就……","py":"Jìrán……, jiù……","func":"句子的类型 › 复句","struct":"既然 + 事实，就 + 结论","vi":"Đã... thì...: dựa trên sự thật đã biết.","use":"Khác 如果 vì sự việc đã xảy ra.","ex":[["既然你来了，就多坐一会儿。","Jìrán nǐ lái le, jiù duō zuò yīhuìr.","Đã đến rồi thì ngồi thêm chút."],["既然大家都同意，就这么办吧。","Jìrán dàjiā dōu tóngyì, jiù zhème bàn ba.","Mọi người đã đồng ý thì cứ vậy."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-087","hsk30_level":"4","official":["o-4-087"],"title":"（由于）……，因此……","py":"（Yóuyú）……, yīncǐ……","func":"句子的类型 › 复句","struct":"(由于) + 原因，因此 + 结果","vi":"Do... nên...: dùng trong văn viết.","use":"因此 đứng đầu vế sau.","ex":[["由于下雨，因此比赛推迟了。","Yóuyú xiàyǔ, yīncǐ bǐsài tuīchí le.","Do mưa nên trận đấu bị hoãn."],["他很努力，因此成绩很好。","Tā hěn nǔlì, yīncǐ chéngjì hěn hǎo.","Anh ấy chăm chỉ nên kết quả tốt."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-088","hsk30_level":"4","official":["o-4-088"],"title":"……，好……","py":"……, Hǎo……","func":"句子的类型 › 复句","struct":"A，好 + B","vi":"Để có thể, cho tiện: vế sau là mục đích.","use":"好 đứng đầu vế mục đích.","ex":[["请留个电话，好联系你。","Qǐng liú ge diànhuà, hǎo liánxì nǐ.","Xin để lại số điện thoại để tiện liên lạc."],["早点儿睡，好明天早起。","Zǎo diǎn r shuì, hǎo míngtiān zǎo qǐ.","Ngủ sớm để mai dậy sớm."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-091","hsk30_level":"4","official":["o-4-091"],"title":"紧缩复句：无标记","py":"Jǐnsuō fù jù: wú biāojì","func":"句子的类型 › 复句","struct":"动词短语1 + 动词短语2 (không có từ nối)","vi":"Câu rút gọn không có từ nối: hai vế đi liền, có quan hệ ngầm.","use":"Hay là 说走就走, 越多越好.","ex":[["你说怎么办就怎么办。","Nǐ shuō zěnmebàn jiù zěnmebàn.","Bạn bảo làm thế nào thì làm thế ấy."],["有钱就买。","Yǒu qián jiù mǎi.","Có tiền thì mua."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-4-092","hsk30_level":"4","official":["o-4-092"],"title":"不……也……","py":"Bù……yě……","func":"句子的类型 › 复句","struct":"不 + A + 也 + B","vi":"Không... cũng...: nhượng bộ.","use":"Nhấn kết quả không đổi.","ex":[["你不说我也知道。","Nǐ bù shuō wǒ yě zhīdào.","Bạn không nói tôi cũng biết."],["不下雨也要带伞。","Bù xiàyǔ yě yào dài sǎn.","Không mưa cũng phải mang ô."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-001","hsk30_level":"5","official":["o-5-001"],"title":"后缀 —头","py":"Hòu zhuì —tóu","func":"语素 › 后缀","struct":"名词/动词/形容词 + 头","vi":"Hậu tố 头 tạo danh từ, đọc nhẹ.","use":"Ví dụ 石头, 木头, 想头, 甜头, 苦头.","ex":[["这块石头很重。","Zhè kuài shítou hěn zhòng.","Hòn đá này rất nặng."],["吃点苦头才能进步。","Chī diǎn kǔ tóu cáinéng jìnbù.","Phải nếm chút khổ mới tiến bộ."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-021","hsk30_level":"5","official":["o-5-021"],"title":"A来A去","py":"AláiAqù","func":"短语 › 固定短语","struct":"A + 来 + A + 去","vi":"Làm đi làm lại một động tác, kéo dài.","use":"A là động từ: 想来想去, 走来走去.","ex":[["我想来想去，还是决定去。","Wǒ xiǎng lái xiǎng qù, háishi juédìng qù.","Tôi nghĩ đi nghĩ lại, vẫn quyết định đi."],["他在房间里走来走去。","Tā zài fángjiān lǐ zǒu lái zǒu qù.","Anh ấy đi đi lại lại trong phòng."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-022","hsk30_level":"5","official":["o-5-022"],"title":"A着A着","py":"AzheAzhe","func":"短语 › 固定短语","struct":"A + 着 + A + 着，句子","vi":"Đang làm A thì bỗng xảy ra việc khác.","use":"Việc sau thường bất ngờ.","ex":[["他说着说着就哭了。","Tā shuō zhe shuō zhe jiù kū le.","Anh ấy nói mãi rồi bật khóc."],["走着走着，天黑了。","Zǒu zhe zǒu zhe, tiān hēi le.","Đi mãi đi mãi thì trời tối."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-023","hsk30_level":"5","official":["o-5-023"],"title":"没A没B","py":"MéiAméiB","func":"短语 › 固定短语","struct":"没 + A + 没 + B","vi":"Không có A không có B: thiếu phép tắc.","use":"Ví dụ 没大没小, 没完没了, 没日没夜.","ex":[["孩子没大没小的。","Háizi méi dà méi xiǎo de.","Đứa trẻ không biết lớn nhỏ."],["他没日没夜地工作。","Tā méi rì méi yè de gōngzuò.","Anh ấy làm việc không phân ngày đêm."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-024","hsk30_level":"5","official":["o-5-024"],"title":"说A就A","py":"ShuōAjiùA","func":"短语 › 固定短语","struct":"说 + A + 就 + A","vi":"Nói làm là làm, hành động ngay.","use":"Ví dụ 说走就走, 说干就干.","ex":[["我们说走就走吧！","Wǒmen shuō zǒu jiù zǒu ba!","Chúng ta nói đi là đi!"],["他说干就干。","Tā shuōgànjiùgàn.","Anh ấy nói làm là làm ngay."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-025","hsk30_level":"5","official":["o-5-025"],"title":"不得了","py":"Bùdéliǎo","func":"短语 › 固定短语","struct":"形容词/动词 + 得 + 不得了；不得了了","vi":"Rất lắm, không xong rồi.","use":"Có thể làm bổ ngữ mức độ hay vị ngữ độc lập.","ex":[["今天热得不得了。","Jīntiān rè de bùdéliǎo.","Hôm nay nóng kinh khủng."],["不得了了，着火了！","Bùdéliǎo le, zháohuǒ le!","Không xong rồi, cháy rồi!"]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-026","hsk30_level":"5","official":["o-5-026"],"title":"用不着","py":"Yòngbuzháo","func":"短语 › 固定短语","struct":"用不着 + 动词","vi":"Không cần, không đáng.","use":"Khẩu ngữ.","ex":[["这点儿小事用不着你帮忙。","Zhè diǎn r xiǎo shì yòngbuzháo nǐ bāngmáng.","Việc nhỏ này không cần bạn giúp."],["你用不着担心。","Nǐ yòngbuzháo dānxīn.","Bạn không cần lo."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-027","hsk30_level":"5","official":["o-5-027"],"title":"从……来看","py":"Cóng……lái kàn","func":"短语 › 固定短语","struct":"从 + 角度 + 来看，句子","vi":"Nhìn từ góc độ, xét theo.","use":"Nêu căn cứ đánh giá.","ex":[["从这点来看，他是对的。","Cóng zhè diǎn lái kàn, tā shì duì de.","Nhìn từ điểm này, anh ấy đúng."],["从结果来看，计划很成功。","Cóng jiēguǒ lái kàn, jìhuà hěn Chénggōng.","Xét kết quả thì kế hoạch rất thành công."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-028","hsk30_level":"5","official":["o-5-028"],"title":"A的A，B的B","py":"AdeA, BdeB","func":"短语 › 固定短语","struct":"A + 的 + A，B + 的 + B","vi":"Ai làm việc người nấy, mỗi bên một việc.","use":"Ví dụ 干活的干活，休息的休息.","ex":[["大家各忙各的：干活的干活，学习的学习。","Dàjiā gè máng gè de: gàn huó de gàn huó, xuéxí de xuéxí.","Ai nấy bận việc mình: người làm việc, người học."],["吃的吃，喝的喝。","Chī de chī, hē de hē.","Người ăn, người uống."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-029","hsk30_level":"5","official":["o-5-029"],"title":"（自）……以来","py":"（Zì）……yǐlái","func":"短语 › 固定短语","struct":"(自) + 时间 + 以来","vi":"Kể từ... đến nay.","use":"Dùng thời điểm hoặc thời gian.","ex":[["自去年以来，他一直在北京。","Zì qùnián yǐlái, tā yīzhí zài Běijīng.","Từ năm ngoái đến nay anh ấy ở Bắc Kinh."],["改革开放以来，变化很大。","Gǎigékāifàng yǐlái, biànhuà hěn dà.","Từ khi cải cách mở cửa, thay đổi rất lớn."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-030","hsk30_level":"5","official":["o-5-030"],"title":"由……组成","py":"Yóu……zǔchéng","func":"短语 › 固定短语","struct":"A + 由 + B + 组成","vi":"Gồm có, được tạo thành từ.","use":"Bị động nhẹ.","ex":[["这个队由十个人组成。","Zhè ge duì yóu shí gèrén zǔchéng.","Đội này gồm mười người."],["水由氢和氧组成。","Shuǐ yóu qīng hé yǎng zǔchéng.","Nước gồm hydro và oxy."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-031","hsk30_level":"5","official":["o-5-031"],"title":"X也不是，Y也不是","py":"Xyě bù shì, Yyě bù shì","func":"短语 › 固定短语","struct":"X + 也不是，Y + 也不是","vi":"Cái này không phải cái kia cũng không phải: tiến thoái lưỡng nan.","use":"Khẩu ngữ.","ex":[["去也不是，不去也不是。","Qù yě bù shì, bù qù yě bù shì.","Đi cũng không phải, không đi cũng không phải."],["说也不是，不说也不是。","Shuō yě bù shì, bù shuō yě bù shì.","Nói cũng không được, không nói cũng không xong."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-032","hsk30_level":"5","official":["o-5-032"],"title":"X也X不得，Y也Y不得","py":"XyěXbù de, YyěYbù de","func":"短语 › 固定短语","struct":"X + 也 + X + 不得，Y + 也 + Y + 不得","vi":"Làm cái này không được, làm cái kia không được.","use":"Cùng ý với o-5-031.","ex":[["进也进不得，退也退不得。","Jìn yě jìn bù de, tuì yě tuì bù de.","Tiến không được, lui cũng không được."],["哭也哭不得，笑也笑不得。","Kū yě kū bù de, xiào yě xiào bù de.","Khóc không được, cười cũng không xong."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-033","hsk30_level":"5","official":["o-5-033"],"title":"X是它，Y也是它","py":"Xshì tā, Yyě shì tā","func":"固定格式","struct":"X + 是 + 它，Y + 也是 + 它","vi":"Cái này là nó, cái kia cũng là nó: nhấn một nhân tố quyết định.","use":"Dạng nhấn mạnh.","ex":[["成也是它，败也是它。","Chéng yě shì tā, bài yě shì tā.","Thành cũng là nó, bại cũng là nó."],["好也是它，坏也是它。","Hǎo yě shì tā, huài yě shì tā.","Tốt cũng là nó, xấu cũng là nó."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-034","hsk30_level":"5","official":["o-5-034"],"title":"X着也是X着","py":"Xzhe yě shìXzhe","func":"固定格式","struct":"动词 + 着 + 也是 + 动词 + 着","vi":"Dù sao cũng đang như vậy, thì tranh thủ làm việc khác.","use":"Giọng thoải mái.","ex":[["闲着也是闲着，我们去逛街吧。","Xián zhe yě shì xián zhe, wǒmen qù guàng jiē ba.","Rảnh cũng là rảnh, ta đi dạo phố đi."],["坐着也是坐着，帮我拿一下。","Zuò zhe yě shì zuò zhe, bāng wǒ ná yī xià.","Ngồi không cũng là ngồi, giúp tôi cầm cái."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-035","hsk30_level":"5","official":["o-5-035"],"title":"不管怎样说","py":"Bùguǎn zěnyàng shuō","func":"固定格式","struct":"不管怎样说，句子","vi":"Dù nói thế nào đi nữa.","use":"Mở đầu câu kết luận.","ex":[["不管怎样说，他还是对的。","Bùguǎn zěnyàng shuō, tā háishi duì de.","Dù nói thế nào anh ấy vẫn đúng."],["不管怎样说，我们得试试。","Bùguǎn zěnyàng shuō, wǒmen de shì shì.","Dù sao ta cũng phải thử."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-036","hsk30_level":"5","official":["o-5-036"],"title":"真有你/他/她的","py":"Zhēn yǒu nǐ/tā/tā de","func":"固定格式","struct":"真有 + 你/他/她 + 的","vi":"Cậu giỏi thật đấy (khen, cảm thán).","use":"Khẩu ngữ, cũng có thể mỉa.","ex":[["真有你的，这么快就做好了！","Zhēn yǒu nǐ de, zhème kuài jiù zuò hǎo le!","Giỏi thật, làm xong nhanh vậy!"],["真有他的！","Zhēn yǒu tā de!","Anh ấy giỏi thật!"]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-037","hsk30_level":"5","official":["o-5-037"],"title":"X什么X","py":"XshénmeX","func":"固定格式","struct":"动词 + 什么 + 动词","vi":"Đừng, ngăn cản: làm gì mà lại...","use":"Ví dụ 吵什么吵.","ex":[["吵什么吵，安静点儿！","Chǎo shénme chǎo, ānjìng diǎn r!","Cãi gì mà cãi, yên lặng đi!"],["急什么急，慢慢来。","Jí shénme jí, mànmànlái.","Vội gì mà vội, từ từ."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-038","hsk30_level":"5","official":["o-5-038"],"title":"什么X不X（的）","py":"ShénmeXbùX（de）","func":"固定格式","struct":"什么 + 动词 + 不 + 动词 + (的)","vi":"Việc gì mà... không (không quan trọng).","use":"Giọng không bận tâm.","ex":[["什么累不累的，我愿意。","Shénme lěi bù lěi de, wǒ yuànyì.","Mệt hay không gì, tôi sẵn lòng."],["什么贵不贵的，喜欢就买。","Shénme guì bù guì de, xǐhuan jiù mǎi.","Đắt hay không gì, thích thì mua."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-039","hsk30_level":"5","official":["o-5-039"],"title":"不X白不X","py":"BùXbái bùX","func":"固定格式","struct":"不 + 动词 + 白 + 不 + 动词","vi":"Không làm thì uổng: nên tận dụng.","use":"Khẩu ngữ.","ex":[["不吃白不吃。","Bù chī bái bù chī.","Không ăn thì phí."],["不拿白不拿。","Bù ná bái bù ná.","Không lấy thì uổng."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-040","hsk30_level":"5","official":["o-5-040"],"title":"X来X去，都是/就是……","py":"XláiXqù, dōu shì/jiùshì……","func":"固定格式","struct":"动词 + 来 + 动词 + 去，都是/就是……","vi":"Nói đi nói lại, rốt cuộc vẫn là...","use":"Kết luận sau khi cân nhắc.","ex":[["想来想去，就是你对。","Xiǎng lái xiǎng qù, jiùshì nǐ duì.","Nghĩ đi nghĩ lại, vẫn là bạn đúng."],["说来说去，都是钱的问题。","Shuō lái shuō qù, dōu shì qián de wèntí.","Nói đi nói lại đều là chuyện tiền."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-041","hsk30_level":"5","official":["o-5-041"],"title":"动词+什么（就）是什么","py":"Dòng cí+shénme（jiù）shì shénme","func":"固定格式","struct":"动词 + 什么 + (就) + 是 + 什么","vi":"Có gì dùng nấy, không kén chọn.","use":"Ví dụ 给什么吃什么.","ex":[["有什么吃什么。","Yǒu shénme chī shénme.","Có gì ăn nấy."],["给什么就是什么。","Gěi shénme jiùshì shénme.","Cho gì nhận nấy."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-042","hsk30_level":"5","official":["o-5-042"],"title":"多项状语","py":"Duō xiàng zhuàng yǔ","func":"句子成分 › 状语","struct":"时间 + 地点/范围 + 描写 + 动词","vi":"Nhiều trạng ngữ trước động từ theo thứ tự.","use":"Thứ tự thông thường: thời gian, phó từ, giới từ, mô tả.","ex":[["他昨天在家高兴地唱歌。","Tā zuótiān zàijiā gāoxìng de chànggē.","Hôm qua anh ấy vui vẻ hát ở nhà."],["我们明天一起去公园。","Wǒmen míngtiān yīqǐ qù gōngyuán.","Mai chúng ta cùng đi công viên."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-043","hsk30_level":"5","official":["o-5-043"],"title":"可能补语：动词+得/不得","py":"Kěnéng bǔ yǔ: dòng cí+de/bù de","func":"句子成分 › 补语","struct":"动词 + 得/不得","vi":"得/不得 sau động từ nói được phép hay không (làm).","use":"Ví dụ 吃不得, 去不得.","ex":[["这种药吃不得。","Zhè zhǒng yào chī bù de.","Loại thuốc này không được uống."],["这话可说不得。","Zhè huà kě shuō bù de.","Lời này không nói được."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-044","hsk30_level":"5","official":["o-5-044"],"title":"程度补语：得+不得了","py":"Chéngdù bǔ yǔ: de+bùdéliǎo","func":"句子成分 › 补语","struct":"形容词/心理动词 + 得 + 不得了","vi":"Mức độ cực cao.","use":"Ví dụ 高兴得不得了.","ex":[["孩子高兴得不得了。","Háizi gāoxìng de bùdéliǎo.","Đứa trẻ vui không tả nổi."],["我累得不得了。","Wǒ lěi de bùdéliǎo.","Tôi mệt rã rời."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-045","hsk30_level":"5","official":["o-5-045"],"title":"趋向补语的引申：状态意义","py":"Qū xiàng bǔ yǔ de yǐn shēn: zhuàngtài yìyì","func":"句子成分 › 补语","struct":"动词/形容词 + 下来/下去/起来/过来/过去","vi":"Nghĩa mở rộng của bổ ngữ xu hướng chỉ trạng thái bắt đầu, tiếp diễn, dừng.","use":"起来 bắt đầu, 下去 tiếp tục, 下来 ổn định.","ex":[["天慢慢暗下来了。","Tiān mànmàn àn xiàlai le.","Trời dần tối lại."],["你说下去吧。","Nǐ shuō xiàqù ba.","Bạn cứ nói tiếp đi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-046","hsk30_level":"5","official":["o-5-046"],"title":"状态补语：得+动词短语","py":"Zhuàngtài bǔ yǔ: de+dòng cí duǎn yǔ","func":"句子成分 › 补语","struct":"动词/形容词 + 得 + 动词短语","vi":"Bổ ngữ trạng thái là cụm động từ mô tả hậu quả.","use":"Ví dụ 累得走不动.","ex":[["他累得走不动了。","Tā lěi de zǒu bù dòng le.","Anh ấy mệt đến không đi nổi."],["她高兴得跳了起来。","Tā gāoxìng de tiào le qǐlai.","Cô ấy vui đến nhảy cẫng lên."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-047","hsk30_level":"5","official":["o-5-047"],"title":"状态补语：得+主谓短语","py":"Zhuàngtài bǔ yǔ: de+zhǔ wèi duǎn yǔ","func":"句子成分 › 补语","struct":"动词/形容词 + 得 + 主谓短语","vi":"Bổ ngữ trạng thái là cụm chủ vị.","use":"Có chủ ngữ riêng.","ex":[["他急得满头大汗。","Tā jí de mǎn tóu dà hàn.","Anh ấy lo đến toát mồ hôi đầm đìa."],["天冷得手都冻了。","Tiān lěng déshǒu dōu dòng le.","Trời lạnh đến tay cũng cóng."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-048","hsk30_level":"5","official":["o-5-048"],"title":"状态补语：得+固定短语","py":"Zhuàngtài bǔ yǔ: de+gùdìng duǎn yǔ","func":"句子成分 › 补语","struct":"动词/形容词 + 得 + 成语/固定短语","vi":"Bổ ngữ trạng thái là thành ngữ.","use":"Tăng sắc thái hình tượng.","ex":[["他高兴得手舞足蹈。","Tā gāoxìng déshǒu wǔ zú dǎo.","Anh ấy vui đến múa tay múa chân."],["她吓得目瞪口呆。","Tā xià de mùdèngkǒudāi.","Cô ấy sợ đến sững sờ."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-049","hsk30_level":"5","official":["o-5-049"],"title":"“有”字句：有+着+宾语","py":"“Yǒu”zì jù: yǒu+zhe+bīn yǔ","func":"句子的类型 › 特殊句型","struct":"主语 + 有 + 着 + 宾语","vi":"Có (văn viết), nhấn tồn tại hay sở hữu.","use":"着 làm câu trang trọng hơn.","ex":[["他有着丰富的经验。","Tā yǒuzhe fēngfù de jīngyàn.","Anh ấy có kinh nghiệm phong phú."],["这个城市有着悠久的历史。","Zhè ge chéngshì yǒuzhe yōujiǔ de lìshǐ.","Thành phố này có lịch sử lâu đời."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-050","hsk30_level":"5","official":["o-5-050"],"title":"“有”字句：动词+有+宾语","py":"“Yǒu”zì jù: dòng cí+yǒu+bīn yǔ","func":"句子的类型 › 特殊句型","struct":"主语 + 动词 + 有 + 宾语","vi":"Động từ + 有 chỉ sự gắn vào, mang theo.","use":"Ví dụ 写有, 刻有, 带有.","ex":[["墙上写有他的名字。","Qiáng shàng xiě yǒu tā de míngzi.","Trên tường viết tên anh ấy."],["这本书附有图片。","Zhè běn shū fù yǒu túpiàn.","Quyển sách này kèm tranh ảnh."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-051","hsk30_level":"5","official":["o-5-051"],"title":"“把”字句：把+宾语+一+动词","py":"“Bǎ”zì jù: bǎ+bīn yǔ+yī+dòng cí","func":"句子的类型 › 特殊句型","struct":"主语 + 把 + 宾语 + 一 + 动词","vi":"Làm một lần, làm đột ngột.","use":"一 gắn động từ đơn.","ex":[["他把门一关，走了。","Tā bǎ mén yī guān, zǒu le.","Anh ấy sập cửa một cái rồi đi."],["她把头一扭，不理我。","Tā bǎ tóu yī niǔ, bùlǐ wǒ.","Cô ấy quay phắt đầu, không để ý tôi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-052","hsk30_level":"5","official":["o-5-052"],"title":"“把”字句：把+宾语1+动词+宾语2","py":"“Bǎ”zì jù: bǎ+bīn yǔ1+dòng cí+bīn yǔ2","func":"句子的类型 › 特殊句型","struct":"主语 + 把 + 宾语1 + 动词 + 宾语2","vi":"Câu 把 có hai tân ngữ.","use":"Ví dụ 把书送他.","ex":[["请把这本书给我。","Qǐng bǎ zhè běn shū gěi wǒ.","Xin đưa quyển sách này cho tôi."],["他把钱借了朋友一千块。","Tā bǎ qián jiè le péngyou yī qiān kuài.","Anh ấy cho bạn mượn một nghìn đồng."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-053","hsk30_level":"5","official":["o-5-053"],"title":"连动句：因果、转折、条件","py":"Lián dòng jù: yīn guǒ, zhuǎnzhé, tiáojiàn","func":"句子的类型 › 特殊句型","struct":"动词短语1 + 动词短语2","vi":"Câu liên động mà hai vế có quan hệ nhân quả, trái ngược hay điều kiện.","use":"Không có từ nối nhưng hiểu được.","ex":[["他生病请了假。","Tā shēngbìng qǐng le jiǎ.","Anh ấy ốm xin nghỉ."],["你有机会不去，真可惜。","Nǐ yǒujī huì bù qù, zhēn kěxī.","Có cơ hội mà bạn không đi, tiếc thật."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-054","hsk30_level":"5","official":["o-5-054"],"title":"比较句：A+形容词+B+数量补语","py":"Bǐjiào jù: A+xíngróng cí+B+shùliàng bǔ yǔ","func":"句子的类型 › 特殊句型","struct":"A + 形容词 + B + 数量补语","vi":"Ít gặp, văn viết/cổ: A hơn B bao nhiêu.","use":"Ví dụ 长我三岁.","ex":[["他大我三岁。","Tā dà wǒ sān suì.","Anh ấy hơn tôi ba tuổi."],["哥哥高我一头。","Gēge gāo wǒ yītóu.","Anh trai cao hơn tôi một cái đầu."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-055","hsk30_level":"5","official":["o-5-055"],"title":"被动句：被/叫/让+宾语+给+动词","py":"Bèidòng jù: bèi/jiào/ràng+bīn yǔ+gěi+dòng cí","func":"句子的类型 › 特殊句型","struct":"主语 + 被/叫/让 + 施事 + 给 + 动词 + 其他成分","vi":"Câu bị động có 给 nhấn mạnh việc xảy ra không mong muốn.","use":"给 nằm trước động từ, khẩu ngữ.","ex":[["杯子被他给打碎了。","Bēizi bèi tā gěi dǎ suì le.","Cái cốc bị anh ấy làm vỡ mất."],["钱让小偷给偷走了。","Qián ràng xiǎotōu gěi tōu zǒu le.","Tiền bị trộm lấy mất."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-056","hsk30_level":"5","official":["o-5-056"],"title":"……，便……","py":"……, Biàn……","func":"句子的类型 › 特殊句型","struct":"A，便 + B","vi":"便 gần như 就, văn viết: thì liền.","use":"Quan hệ nối tiếp.","ex":[["他一进门，便大声说话。","Tā yī jìn mén, biàn dàshēng shuōhuà.","Anh ấy vừa vào cửa liền nói lớn."],["听了这话，他便笑了。","Tīng le zhè huà, tā biàn xiào le.","Nghe lời này anh ấy liền cười."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-057","hsk30_level":"5","official":["o-5-057"],"title":"或是……，或是……","py":"Huòshì……, huòshì……","func":"句子的类型 › 特殊句型","struct":"或是 + A，或是 + B","vi":"Hoặc A hoặc B, giống 或者.","use":"Văn viết hơn.","ex":[["周末或是看书，或是运动。","Zhōumò huòshì kàn shū, huòshì yùndòng.","Cuối tuần hoặc đọc sách hoặc vận động."],["你或是电话，或是邮件联系。","Nǐ huòshì diànhuà, huòshì yóujiàn liánxì.","Bạn liên hệ qua điện thoại hay thư đều được."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-058","hsk30_level":"5","official":["o-5-058"],"title":"一旦……，就……","py":"Yīdàn……, jiù……","func":"句子的类型 › 特殊句型","struct":"一旦 + 条件，就 + 结果","vi":"Một khi... thì...","use":"Nhấn hậu quả.","ex":[["一旦开始，就别停。","Yīdàn kāishǐ, jiù bié tíng.","Một khi đã bắt đầu thì đừng dừng."],["一旦出问题，就麻烦了。","Yīdàn chū wèntí, jiù máfan le.","Một khi có vấn đề thì rắc rối."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-059","hsk30_level":"5","official":["o-5-059"],"title":"假如……，（就）……","py":"Jiǎrú……, （jiù）……","func":"句子的类型 › 特殊句型","struct":"假如 + 条件，(就) + 结果","vi":"Giả như: văn viết hơn 如果.","use":"Thường giả thiết không có thật.","ex":[["假如我是你，我就去。","Jiǎrú wǒ shì nǐ, wǒ jiù qù.","Giả như tôi là bạn thì tôi sẽ đi."],["假如明天下雨，比赛就取消。","Jiǎrú míngtiān xiàyǔ, bǐsài jiù qǔxiāo.","Giả như mai mưa thì trận đấu hủy."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-062","hsk30_level":"5","official":["o-5-062"],"title":"……，因而……","py":"……, Yīnér……","func":"句子的类型 › 特殊句型","struct":"A，因而 + B","vi":"Do vậy nên, vì thế mà: văn viết.","use":"Đứng đầu vế sau.","ex":[["他很努力，因而成绩提高了。","Tā hěn nǔlì, yīnér chéngjì tígāo le.","Anh ấy chăm chỉ nên điểm số tăng."],["天气变冷，因而人们穿厚了。","Tiānqì biàn lěng, yīnér rénmen chuān hòu le.","Trời lạnh nên người ta mặc dày."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-063","hsk30_level":"5","official":["o-5-063"],"title":"……，可见……","py":"……, Kějiàn……","func":"句子的类型 › 特殊句型","struct":"A，可见 + B","vi":"Có thể thấy, như vậy đủ thấy.","use":"Vế sau là kết luận.","ex":[["他天天练习，可见很努力。","Tā tiān tiān liànxí, kějiàn hěn nǔlì.","Anh ấy ngày nào cũng luyện tập, đủ thấy chăm chỉ."],["连小孩都懂，可见这很容易。","Lián xiǎo hái dōu dǒng, kějiàn zhè hěn róngyì.","Đến trẻ con cũng hiểu, đủ thấy dễ."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-065","hsk30_level":"5","official":["o-5-065"],"title":"不但不/不但没有……，反而……","py":"Bùdàn bù/bùdàn méiyǒu……, fǎnér……","func":"句子的类型 › 特殊句型","struct":"不但不/没 + A，反而 + B","vi":"Không những không... mà ngược lại.","use":"Hai vế trái với dự đoán.","ex":[["他不但不生气，反而笑了。","Tā bùdàn bù shēngqì, fǎnér xiào le.","Anh ấy không những không giận mà còn cười."],["雨不但没停，反而更大了。","Yǔ bùdàn méi tíng, fǎnér gēng dà le.","Mưa không những không tạnh mà còn to hơn."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-066","hsk30_level":"5","official":["o-5-066"],"title":"不是……，还/还是……","py":"Bù shì……, hái/háishi……","func":"句子的类型 › 特殊句型","struct":"不是 + A，还是 + B","vi":"Không phải A mà vẫn là B.","use":"Ít gặp, trong khẩu ngữ.","ex":[["不是他来，还是你来？","Bù shì tā lái, háishi nǐ lái?","Không phải anh ấy thì bạn đến?"],["不是红的，还是黑的。","Bù shì hóng de, háishi hēi de.","Không phải đỏ thì vẫn là đen."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-067","hsk30_level":"5","official":["o-5-067"],"title":"……，为的是……","py":"……, Wèi de shì……","func":"句子的类型 › 特殊句型","struct":"A，为的是 + B","vi":"Là để, mục đích của việc trước là...","use":"Giải thích mục đích sau hành động.","ex":[["他努力工作，为的是让家人过好日子。","Tā nǔlì gōngzuò, wèi de shì ràng jiārén guò hǎo rìzi.","Anh ấy làm việc chăm để gia đình sống tốt."],["我早起，为的是锻炼身体。","Wǒ zǎo qǐ, wèi de shì duànliàn shēntǐ.","Tôi dậy sớm để tập thể dục."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-068","hsk30_level":"5","official":["o-5-068"],"title":"没有……就没有……","py":"Méiyǒu……jiù méiyǒu……","func":"句子的类型 › 特殊句型","struct":"没有 + A + 就没有 + B","vi":"Không có A thì không có B.","use":"Nhấn quan hệ điều kiện cần.","ex":[["没有努力就没有成功。","Méiyǒu nǔlì jiù méiyǒu Chénggōng.","Không cố gắng thì không có thành công."],["没有你就没有今天。","Méiyǒu nǐ jiù méiyǒu jīntiān.","Không có bạn thì không có hôm nay."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-5-069","hsk30_level":"5","official":["o-5-069"],"title":"不……不……","py":"Bù……bù……","func":"句子的类型 › 特殊句型","struct":"不 + A + 不 + B","vi":"Không A không B: A là điều kiện của B.","use":"Ví dụ 不见不散, 不说不知道.","ex":[["不见不散。","Bùjiàn bù sàn.","Không gặp không về."],["不学不会。","Bù xué bù huì.","Không học thì không biết."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-001","hsk30_level":"6","official":["o-6-001"],"title":"类前缀 超—、多—、反—、无—、亚—、准—","py":"Lèi qián zhuì chāo—, duō—, fǎn—, wú—, yà—, zhǔn—","func":"语素 › 类前缀","struct":"前缀 + 名词/形容词/动词","vi":"Tiền tố loại: 超 siêu, 多 đa, 反 phản, 无 vô, 亚 á, 准 chuẩn.","use":"Ví dụ 超市, 多功能, 反作用, 无关, 亚洲, 准时.","ex":[["我们去超市买东西。","Wǒmen qù chāoshì mǎi dōngxī.","Chúng ta đi siêu thị mua đồ."],["这跟我无关。","Zhè gēn wǒ wúguān.","Việc này không liên quan đến tôi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-021","hsk30_level":"6","official":["o-6-021"],"title":"A这A那","py":"AzhèAnà","func":"短语 › 固定短语","struct":"A + 这 + A + 那","vi":"Nói này nói nọ, liệt kê dài dòng.","use":"Ví dụ 说这说那, 买这买那.","ex":[["他整天说这说那。","Tā zhěngtiān shuō zhè shuō nà.","Anh ấy cả ngày nói này nói nọ."],["她买这买那，花了很多钱。","Tā mǎi zhè mǎi nà, huā le hěn duō qián.","Cô ấy mua cái này cái nọ, tiêu nhiều tiền."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-022","hsk30_level":"6","official":["o-6-022"],"title":"左A右B","py":"ZuǒAyòuB","func":"短语 › 固定短语","struct":"左 + A + 右 + B","vi":"Làm đi làm lại, hết cái này đến cái khác.","use":"Ví dụ 左思右想, 左看右看.","ex":[["我左思右想，还是不放心。","Wǒ zuǒ sī yòu xiǎng, háishi bù fàngxīn.","Tôi nghĩ tới nghĩ lui vẫn không yên tâm."],["他左看右看，没找到。","Tā zuǒ kàn yòu kàn, méi zhǎodào.","Anh ấy nhìn trái nhìn phải mà không thấy."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-023","hsk30_level":"6","official":["o-6-023"],"title":"好（不）容易","py":"Hǎo（bù）róngyì","func":"短语 › 固定短语","struct":"好(不)容易 + 动词","vi":"Rất khó khăn mới; 好容易 và 好不容易 cùng nghĩa.","use":"Nhấn việc khó mới xong.","ex":[["我好不容易才买到票。","Wǒ hǎobùróngyì cái mǎi dào piào.","Tôi khó khăn lắm mới mua được vé."],["他好容易找到了工作。","Tā hǎoróngyì zhǎodào le gōngzuò.","Anh ấy vất vả mới tìm được việc."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-024","hsk30_level":"6","official":["o-6-024"],"title":"那倒（也）是","py":"Nà dào（yě）shì","func":"短语 › 固定短语","struct":"那倒(也)是","vi":"Cái đó cũng đúng, đồng ý một phần.","use":"Dùng đáp lại.","ex":[["——这家店贵。——那倒也是。","——Zhè jiā diàn guì. ——nà dào yě shì.","— Quán này đắt. — Cũng phải."],["那倒是，我没想到。","Nà dàoshi, wǒ méixiǎngdào.","Cũng đúng, tôi không nghĩ tới."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-025","hsk30_level":"6","official":["o-6-025"],"title":"算了","py":"Suànle","func":"短语 › 固定短语","struct":"算了 (+ 吧)","vi":"Thôi, bỏ đi: dừng hay không tính toán.","use":"Khẩu ngữ.","ex":[["算了，别说了。","Suànle, biéshuō le.","Thôi, đừng nói nữa."],["太贵了，算了吧。","Tài guì le, suànle ba.","Đắt quá, thôi bỏ đi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-026","hsk30_level":"6","official":["o-6-026"],"title":"得了","py":"Déle","func":"短语 › 固定短语","struct":"得了 (+ 吧)","vi":"Thôi đi, đủ rồi (ngăn lại hoặc không tin).","use":"Khẩu ngữ.","ex":[["得了，别吹牛了。","Déle, bié chuīniú le.","Thôi đi, đừng khoác lác."],["得了，我自己来。","Déle, wǒ zìjǐ lái.","Thôi, để tôi tự làm."]],"note":"Khác 得了 (liǎo) = có thể.","origin":"hanziai-authored"},{"id":"a-o-6-027","hsk30_level":"6","official":["o-6-027"],"title":"A一+量词，B一+量词","py":"Ayī+liàng cí, Byī+liàng cí","func":"短语 › 固定短语","struct":"A + 一 + 量词，B + 一 + 量词","vi":"Nối tiếp từng cái một.","use":"Ví dụ 吃一口，喝一口.","ex":[["他吃一口，说一句。","Tā chī yī kǒu, shuō yī jù.","Anh ấy ăn một miếng, nói một câu."],["他看一页，写一页。","Tā kàn yī yè, xiě yī yè.","Anh ấy xem một trang, viết một trang."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-028","hsk30_level":"6","official":["o-6-028"],"title":"东一A，西一A","py":"Dōng yīA, xī yīA","func":"短语 › 固定短语","struct":"东 + 一 + 量词/名词，西 + 一 + 量词/名词","vi":"Chỗ này một chỗ kia một, rải rác lộn xộn.","use":"Ví dụ 东一本，西一本.","ex":[["书东一本西一本。","Shū dōng yī běn xī yī běn.","Sách chỗ này một quyển chỗ kia một quyển."],["他东一句西一句地说着。","Tā dōng yī jù xī yī jù de shuō zhe.","Anh ấy nói câu được câu chăng."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-029","hsk30_level":"6","official":["o-6-029"],"title":"到……为止","py":"Dào……wéizhǐ","func":"短语 › 固定短语","struct":"到 + 时间/地点 + 为止","vi":"Cho đến, tính đến.","use":"Chỉ giới hạn cuối.","ex":[["到现在为止，我们已经学了五课。","Dào xiànzài wéizhǐ, wǒmen yǐjīng xué le wǔ kè.","Cho đến nay chúng tôi đã học năm bài."],["今天的课到这儿为止。","Jīntiān de kè dào zhèr wéizhǐ.","Buổi học hôm nay đến đây là hết."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-030","hsk30_level":"6","official":["o-6-030"],"title":"X到Y头上来了","py":"XdàoYtóu shànglái le","func":"短语 › 固定短语","struct":"X + 到 + Y + 头上来了","vi":"Việc đã đến lượt người nào, nhất là việc không hay.","use":"Khẩu ngữ.","ex":[["这种事怎么到我头上来了？","Zhè zhǒng shì zěnme dào wǒ tóu shànglái le?","Sao chuyện này lại tới lượt tôi?"],["好事轮不到我头上来。","Hǎoshì lún bù dào wǒ tóu shànglái.","Việc tốt không tới lượt tôi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-031","hsk30_level":"6","official":["o-6-031"],"title":"不X不……，一X……","py":"BùXbù……, yīX……","func":"短语 › 固定短语","struct":"不 + 动词 + 不…，一 + 动词 + …","vi":"Nếu không thì thôi, đã làm là...","use":"Vế đầu bối cảnh, vế sau kết quả.","ex":[["不看不知道，一看吓一跳。","Bù kàn bùzhī dào, yī kàn xià yī tiào.","Không xem thì không biết, vừa xem là giật mình."],["不说不知道，一说就明白。","Bù shuō bùzhī dào, yī shuō jiù míngbai.","Không nói thì không hiểu, nói ra là rõ."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-032","hsk30_level":"6","official":["o-6-032"],"title":"好你个X","py":"Hǎo nǐ geX","func":"短语 › 固定短语","struct":"好你个 + 名词","vi":"Được lắm cái đồ, mắng yêu hoặc giận.","use":"Khẩu ngữ.","ex":[["好你个小李，原来是你！","Hǎo nǐ ge xiǎo li, yuánlái shì nǐ!","Được lắm Tiểu Lý, hóa ra là cậu!"],["好你个懒鬼！","Hǎo nǐ ge lǎn guǐ!","Đúng là đồ lười!"]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-033","hsk30_level":"6","official":["o-6-033"],"title":"早（也）不X，晚（也）不X","py":"Zǎo（yě）bùX, wǎn（yě）bùX","func":"短语 › 固定短语","struct":"早 (也) 不 + 动词，晚 (也) 不 + 动词，偏偏……","vi":"Sớm không... muộn không... lại đúng lúc này (trách).","use":"Thường kèm 偏偏.","ex":[["早不来晚不来，偏偏这时候来。","Zǎo bù lái wǎn bù lái, piānpiān zhèshíhòu lái.","Sớm không đến muộn không đến, lại đúng lúc này đến."],["早不坏晚不坏，偏偏现在坏了。","Zǎo bù huài wǎn bù huài, piānpiān xiànzài huài le.","Sớm không hỏng muộn không hỏng, lại hỏng ngay bây giờ."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-034","hsk30_level":"6","official":["o-6-034"],"title":"看/瞧+把+宾语（施事）+X得","py":"Kàn/qiáo+bǎ+bīn yǔ（shī shì）+Xde","func":"短语 › 固定短语","struct":"看/瞧 + 把 + 人 + 动词/形容词 + 得……","vi":"Nhìn xem, câu cảm thán với 把 chỉ mức độ.","use":"Khẩu ngữ.","ex":[["看把你急得！","Kàn bǎ nǐ jí de!","Xem bạn gấp chưa kìa!"],["瞧把他高兴的！","Qiáo bǎ tā gāoxìng de!","Nhìn anh ấy vui chưa!"]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-035","hsk30_level":"6","official":["o-6-035"],"title":"放着X不Y","py":"Fàng zheXbùY","func":"短语 › 固定短语","struct":"放着 + A + 不 + 动词","vi":"Có sẵn mà không dùng, phê bình.","use":"Khẩu ngữ.","ex":[["放着好日子不过。","Fàng zhe hǎo rìzi bùguò.","Có cuộc sống tốt không sống."],["放着现成的不用。","Fàng zhe xiànchéng de bùyòng.","Có sẵn mà không dùng."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-036","hsk30_level":"6","official":["o-6-036"],"title":"X了就X了，（没）有……","py":"Xle jiùXle, （méi）yǒu……","func":"短语 › 固定短语","struct":"动词 + 了 + 就 + 动词 + 了，(没) 有……","vi":"Đã làm rồi thì thôi, có gì đâu (không sao).","use":"Giọng thoải mái.","ex":[["错了就错了，有什么关系？","Cuò le jiù cuò le, yǒu shénme guānxi?","Sai thì sai, có sao đâu?"],["去了就去了，没什么。","Qù le jiù qù le, méishénme.","Đi thì đi rồi, không sao."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-037","hsk30_level":"6","official":["o-6-037"],"title":"这/那也不X，那/这也不Y","py":"Zhè/nà yě bùX, nà/zhè yě bùY","func":"短语 › 固定短语","struct":"这 + 也不 + A，那 + 也不 + B","vi":"Cái này không cái kia cũng không (kén chọn).","use":"Chê hết.","ex":[["这也不吃，那也不吃。","Zhè yě bù chī, nà yě bù chī.","Cái này không ăn, cái kia cũng không."],["这也不行，那也不行。","Zhè yě bùxíng, nà yě bùxíng.","Cái này không được, cái kia cũng không."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-038","hsk30_level":"6","official":["o-6-038"],"title":"X归X，Y归Y","py":"XguīX, YguīY","func":"短语 › 固定短语","struct":"X + 归 + X，Y + 归 + Y","vi":"Việc nào ra việc nấy, tách bạch.","use":"Dùng phân biệt.","ex":[["公事归公事，私事归私事。","Gōngshì guī gōngshì, sīshì guī sīshì.","Việc công ra việc công, việc tư ra việc tư."],["钱归钱，感情归感情。","Qián guī qián, gǎnqíng guī gǎnqíng.","Tiền ra tiền, tình ra tình."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-039","hsk30_level":"6","official":["o-6-039"],"title":"看你X的/瞧他X的","py":"Kàn nǐXde/qiáo tāXde","func":"短语 › 固定短语","struct":"看/瞧 + 人 + 动词/形容词 + 的","vi":"Nhìn xem ai làm gì thế này (cảm thán).","use":"Có thể trách hoặc khen.","ex":[["看你说的！","Kàn nǐ shuō de!","Nhìn bạn nói kìa!"],["瞧他高兴的！","Qiáo tā gāoxìng de!","Nhìn anh ấy vui chưa!"]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-040","hsk30_level":"6","official":["o-6-040"],"title":"程度补语：动词/形容词+透+了","py":"Chéngdù bǔ yǔ: dòng cí/xíngróng cí+tòu+le","func":"句子成分 › 补语","struct":"动词/形容词 + 透 + 了","vi":"Rất, hết sức, đến tận cùng.","use":"Hay dùng với 恨, 累, 湿, 看.","ex":[["衣服湿透了。","Yīfu shī tòu le.","Áo ướt sũng."],["我累透了。","Wǒ lěi tòu le.","Tôi mệt rã rời."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-041","hsk30_level":"6","official":["o-6-041"],"title":"“把”字句：非生物体主语","py":"“Bǎ”zì jù: fēi shēngwù tǐ zhǔ yǔ","func":"句子的类型 › 特殊句型","struct":"非生物 + 把 + 宾语 + 动词 + 其他成分","vi":"Câu 把 mà chủ ngữ không phải người, như sự việc hay hiện tượng.","use":"Hay dùng trong văn miêu tả.","ex":[["大风把树吹倒了。","Dà fēng bǎ shù chuī dào le.","Gió lớn thổi đổ cây."],["这场雨把衣服淋湿了。","Zhè chǎng yǔ bǎ yīfu lín shī le.","Cơn mưa làm áo ướt."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-042","hsk30_level":"6","official":["o-6-042"],"title":"“把”字句：宾语为施事","py":"“Bǎ”zì jù: bīn yǔ wèi shī shì","func":"句子的类型 › 特殊句型","struct":"主语 + 把 + 施事 + 动词 + 其他成分","vi":"Tân ngữ của 把 chính là người gây ra hành động, thường chỉ kết quả không mong muốn.","use":"Ví dụ 把客人走了.","ex":[["他把客人给走了。","Tā bǎ kèrén gěi zǒu le.","Anh ấy để khách đi mất."],["你把我急死了。","Nǐ bǎ wǒ jí sǐ le.","Bạn làm tôi sốt ruột chết."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-043","hsk30_level":"6","official":["o-6-043"],"title":"一时……一时……","py":"Yīshí……yīshí……","func":"句子的类型 › 复句","struct":"一时 + A，一时 + B","vi":"Lúc thì A lúc thì B, tạm thời.","use":"Giống 一会儿……一会儿.","ex":[["他心情一时好，一时坏。","Tā xīnqíng yīshí hǎo, yīshí huài.","Tâm trạng anh ấy lúc tốt lúc xấu."],["天气一时晴，一时雨。","Tiānqì yīshí qíng, yīshí yǔ.","Trời lúc nắng lúc mưa."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-044","hsk30_level":"6","official":["o-6-044"],"title":"要么……，要么……","py":"Yàome……, yàome……","func":"句子的类型 › 复句","struct":"要么 + A，要么 + B","vi":"Hoặc là A hoặc là B, buộc chọn.","use":"Có sắc thái quyết định.","ex":[["要么你去，要么我去。","Yàome nǐ qù, yàome wǒ qù.","Hoặc bạn đi hoặc tôi đi."],["要么现在走，要么别走了。","Yàome xiànzài zǒu, yàome bié zǒu le.","Hoặc đi bây giờ hoặc đừng đi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-045","hsk30_level":"6","official":["o-6-045"],"title":"虽……，但/可/却/也……","py":"Suī……, dàn/kě/què/yě……","func":"句子的类型 › 复句","struct":"虽 + A，但/可/却/也 + B","vi":"Tuy A nhưng B (văn viết).","use":"虽 là dạng rút gọn của 虽然.","ex":[["虽小，却很舒服。","Suī xiǎo, què hěn shūfu.","Tuy nhỏ nhưng rất thoải mái."],["虽贵，也值得买。","Suī guì, yě zhíde mǎi.","Tuy đắt cũng đáng mua."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-047","hsk30_level":"6","official":["o-6-047"],"title":"除非……，才……","py":"Chúfēi……, cái……","func":"句子的类型 › 复句","struct":"除非 + 条件，才 + 结果","vi":"Trừ phi, chỉ khi... mới...","use":"Điều kiện duy nhất.","ex":[["除非你去，他才会来。","Chúfēi nǐ qù, tā cái huì lái.","Trừ khi bạn đi thì anh ấy mới đến."],["除非下雨，我们才不去。","Chúfēi xiàyǔ, wǒmen cái bù qù.","Trừ khi mưa chúng tôi mới không đi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-6-050","hsk30_level":"6","official":["o-6-050"],"title":"……，以便……","py":"……, Yǐbiàn……","func":"句子的类型 › 复句","struct":"A，以便 + B","vi":"Để tiện, nhằm: vế sau là mục đích.","use":"Văn viết.","ex":[["请留下电话，以便联系。","Qǐng liúxià diànhuà, yǐbiàn liánxì.","Xin để lại điện thoại để tiện liên lạc."],["提前准备，以便顺利完成。","Tíqián zhǔnbèi, yǐbiàn shùnlì wánchéng.","Chuẩn bị trước để hoàn thành suôn sẻ."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-001","hsk30_level":"7-9","official":["o-7-9-001"],"title":"类前缀 后—、亲—","py":"Lèi qián zhuì hòu—, qīn—","func":"语素 › 类前缀","struct":"后 / 亲 + 名词","vi":"Tiền tố loại 后 (sau) và 亲 (thân, ruột thịt).","use":"Ví dụ 后半夜, 后现代, 亲妈, 亲兄弟.","ex":[["他睡到后半夜才醒。","Tā shuì dào hòu bànyè cái xǐng.","Anh ấy ngủ đến quá nửa đêm mới tỉnh."],["她是我的亲姐姐。","Tā shì wǒ de qīn jiějie.","Cô ấy là chị ruột của tôi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-002","hsk30_level":"7-9","official":["o-7-9-002"],"title":"类后缀 —观、—鬼、—界、—然、—坛、—为、—制","py":"Lèi hòu zhuì —guān, —guǐ, —jiè, —rán, —tán, —wèi, —zhì","func":"语素 › 类后缀","struct":"名词/形容词 + 观/鬼/界/然/坛/为/制","vi":"Hậu tố loại: 观 quan niệm, 鬼 kẻ nghiện, 界 giới, 然 vẻ, 坛 diễn đàn, 为 hành vi, 制 chế độ.","use":"Ví dụ 价值观, 酒鬼, 教育界, 突然, 体坛, 行为, 学分制.","ex":[["他的价值观很正。","Tā de jiàzhíguān hěn zhèng.","Quan niệm giá trị của anh ấy rất đúng đắn."],["教育界很关注这个问题。","Jiàoyù jiè hěn guānzhù zhè ge wèntí.","Giới giáo dục rất quan tâm vấn đề này."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-020","hsk30_level":"7-9","official":["o-7-9-020"],"title":"介词：当着、就","py":"Jiè cí: dāngzhe, jiù","func":"词类 › 介词","struct":"当着 + 人 + (的面) + 动词；就 + 对象 + 动词","vi":"Giới từ dẫn đối tượng: 当着 trước mặt ai, 就 đối với, về.","use":"就 dùng văn viết: 就这个问题讨论.","ex":[["他当着大家的面道歉了。","Tā dāngzhe dàjiā de miàn dàoqiàn le.","Anh ấy xin lỗi trước mặt mọi người."],["我们就这个问题进行了讨论。","Wǒmen jiù zhè ge wèntí jìnxíng le tǎolùn.","Chúng tôi đã thảo luận về vấn đề này."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-025","hsk30_level":"7-9","official":["o-7-9-025"],"title":"爱A不A","py":"ÀiAbùA","func":"短语 › 固定短语","struct":"爱 + A + 不 + A","vi":"Thích thì làm không thì thôi, thái độ thờ ơ.","use":"Ví dụ 爱信不信, 爱去不去.","ex":[["爱信不信，反正我说了。","Ài xìn bù xìn, fǎnzhèng wǒ shuō le.","Tin hay không tùy bạn, tôi nói rồi."],["爱吃不吃。","Ài chī bù chī.","Ăn hay không tùy."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-026","hsk30_level":"7-9","official":["o-7-9-026"],"title":"半A半B","py":"BànAbànB","func":"短语 › 固定短语","struct":"半 + A + 半 + B","vi":"Nửa này nửa kia: nửa... nửa...","use":"Ví dụ 半信半疑, 半睡半醒.","ex":[["他半信半疑地看着我。","Tā bànxìnbànyí de kàn zhe wǒ.","Anh ấy nửa tin nửa ngờ nhìn tôi."],["孩子半睡半醒地坐着。","Háizi bàn shuì bàn xǐng de zuò zhe.","Đứa trẻ ngồi nửa tỉnh nửa mơ."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-027","hsk30_level":"7-9","official":["o-7-9-027"],"title":"不A不B","py":"BùAbùB","func":"短语 › 固定短语","struct":"不 + A + 不 + B","vi":"Không... không...: nghĩa vừa phải hoặc không ra gì.","use":"Ví dụ 不上不下, 不三不四.","ex":[["这样不上不下的，真难受。","Zhèyàng bù shàng bù xià de, zhēn nánshòu.","Cứ lơ lửng thế này khó chịu thật."],["别和那些不三不四的人来往。","Bié hé nàxiē bù sān bù sì de rén láiwǎng.","Đừng qua lại với người không ra gì."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-028","hsk30_level":"7-9","official":["o-7-9-028"],"title":"不A而B","py":"BùAérB","func":"短语 › 固定短语","struct":"不 + A + 而 + B","vi":"Không A mà B: kết quả đạt được mà không cần A.","use":"Ví dụ 不谋而合, 不欢而散.","ex":[["我们的想法不谋而合。","Wǒmen de xiǎngfǎ bù móu ér hé.","Ý nghĩ của chúng tôi trùng nhau."],["会议不欢而散。","Huìyì bù huān ér sàn.","Cuộc họp tan trong không khí không vui."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-029","hsk30_level":"7-9","official":["o-7-9-029"],"title":"东A西B","py":"DōngAxīB","func":"短语 › 固定短语","struct":"东 + A + 西 + B","vi":"Khắp nơi, lung tung.","use":"Ví dụ 东张西望, 东奔西走.","ex":[["他东张西望地找人。","Tā dōngzhāngxīwàng de zhǎo rén.","Anh ấy nhìn ngó khắp nơi tìm người."],["他东奔西走，忙了一整天。","Tā dōngbēnxīzǒu, máng le yī zhěngtiān.","Anh ấy chạy ngược chạy xuôi cả ngày."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-030","hsk30_level":"7-9","official":["o-7-9-030"],"title":"非A非B","py":"FēiAfēiB","func":"短语 › 固定短语","struct":"非 + A + 非 + B","vi":"Không phải A cũng không phải B, nằm giữa.","use":"Ví dụ 非驴非马, 非亲非故.","ex":[["这个东西非驴非马的。","Zhè ge dōngxī fēi 驴 fēi mǎ de.","Thứ này chẳng ra cái gì."],["他和我非亲非故。","Tā hé wǒ fēi qīn fēi gù.","Anh ấy với tôi không thân không thích."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-031","hsk30_level":"7-9","official":["o-7-9-031"],"title":"忽A忽B","py":"HūAhūB","func":"短语 › 固定短语","struct":"忽 + A + 忽 + B","vi":"Lúc A lúc B, thay đổi đột ngột.","use":"Ví dụ 忽冷忽热, 忽高忽低.","ex":[["天气忽冷忽热。","Tiānqì hū lěng hū rè.","Thời tiết lúc nóng lúc lạnh."],["他的声音忽高忽低。","Tā de shēngyīn hūgāohūdī.","Giọng anh ấy lúc cao lúc thấp."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-032","hsk30_level":"7-9","official":["o-7-9-032"],"title":"或A或B","py":"HuòAhuòB","func":"短语 › 固定短语","struct":"或 + A + 或 + B","vi":"Hoặc A hoặc B, văn viết.","use":"Ví dụ 或多或少.","ex":[["这件事或多或少会有影响。","Zhè jiàn shì huòduōhuòshǎo huì yǒu yǐngxiǎng.","Việc này ít nhiều có ảnh hưởng."],["大家或站或坐。","Dàjiā huò zhàn huò zuò.","Mọi người người đứng người ngồi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-033","hsk30_level":"7-9","official":["o-7-9-033"],"title":"可A可B","py":"KěAkěB","func":"短语 › 固定短语","struct":"可 + A + 可 + B","vi":"Có thể A mà cũng có thể B.","use":"Ví dụ 可大可小, 可有可无.","ex":[["这个问题可大可小。","Zhè ge wèntí kě dà kě xiǎo.","Vấn đề này có thể lớn có thể nhỏ."],["他对此可有可无。","Tā duì cǐ kě yǒu kě wú.","Với anh ấy có hay không cũng được."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-034","hsk30_level":"7-9","official":["o-7-9-034"],"title":"连A带B","py":"LiánAdàiB","func":"短语 › 固定短语","struct":"连 + A + 带 + B","vi":"Cả A lẫn B, kể cả.","use":"Ví dụ 连说带笑, 连滚带爬.","ex":[["他连说带笑地走了进来。","Tā lián shuō dài xiào de zǒu le jìnlái.","Anh ấy vừa nói vừa cười bước vào."],["孩子连滚带爬地跑开了。","Háizi liángǔndàipá de pǎo kāi le.","Đứa trẻ lăn lê bò toài chạy đi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-035","hsk30_level":"7-9","official":["o-7-9-035"],"title":"七A八B","py":"QīAbāB","func":"短语 › 固定短语","struct":"七 + A + 八 + B","vi":"Lộn xộn, nhiều, lung tung.","use":"Ví dụ 七嘴八舌, 七上八下.","ex":[["大家七嘴八舌地讨论着。","Dàjiā qīzuǐbāshé de tǎolùn zhe.","Mọi người nhao nhao bàn luận."],["我心里七上八下的。","Wǒ xīnli qī shàng bā xià de.","Lòng tôi thấp thỏm không yên."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-036","hsk30_level":"7-9","official":["o-7-9-036"],"title":"时A时B","py":"ShíAshíB","func":"短语 › 固定短语","struct":"时 + A + 时 + B","vi":"Lúc A lúc B, văn viết.","use":"Ví dụ 时好时坏, 时隐时现.","ex":[["他的病时好时坏。","Tā de bìng shíhǎoshíhuài.","Bệnh của anh ấy lúc tốt lúc xấu."],["月亮时隐时现。","Yuèliang shí yǐn shí xiàn.","Mặt trăng lúc ẩn lúc hiện."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-037","hsk30_level":"7-9","official":["o-7-9-037"],"title":"无A不B","py":"WúAbùB","func":"短语 › 固定短语","struct":"无 + A + 不 + B","vi":"Không... mà không...: nhấn tuyệt đối.","use":"Ví dụ 无所不包, 无微不至.","ex":[["她无微不至地照顾孩子。","Tā wúwēibùzhì de zhàogu háizi.","Cô ấy chăm sóc con chu đáo từng li."],["这本书无所不包。","Zhè běn shū wú suǒ bù bāo.","Quyển sách này không thiếu thứ gì."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-038","hsk30_level":"7-9","official":["o-7-9-038"],"title":"无A可B","py":"WúAkěB","func":"短语 › 固定短语","struct":"无 + A + 可 + B","vi":"Không có gì để làm: không... để...","use":"Ví dụ 无话可说, 无计可施, 无路可走.","ex":[["我对他无话可说。","Wǒ duì tā wúhuàkěshuō.","Tôi không còn gì để nói với anh ấy."],["他已经无计可施了。","Tā yǐjīng wú jì kě shī le.","Anh ấy đã hết cách."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-039","hsk30_level":"7-9","official":["o-7-9-039"],"title":"自A自B","py":"ZìAzìB","func":"短语 › 固定短语","struct":"自 + A + 自 + B","vi":"Tự mình A tự mình B, tự làm tự chịu.","use":"Ví dụ 自给自足, 自说自话.","ex":[["他们自给自足，不求别人。","Tāmen zì gěi zì zú, bù qiú biéren.","Họ tự cung tự cấp, không nhờ ai."],["他总是自说自话。","Tā zǒngshì zì shuō zì huà.","Anh ấy lúc nào cũng tự nói tự làm."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-041","hsk30_level":"7-9","official":["o-7-9-041"],"title":"不是","py":"Bù shì","func":"短语 › 固定短语","struct":"不是，句子 / 不是 + 名词","vi":"Dùng để ngắt lời, đính chính hoặc hỏi lại.","use":"Khẩu ngữ, đứng đầu câu.","ex":[["不是，你说的是哪个？","Bù shì, nǐ shuō de shì nǎ ge?","Khoan đã, bạn nói cái nào?"],["不是，我不是这个意思。","Bù shì, wǒ bù shì zhè ge yìsi.","Không phải, tôi không có ý này."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-042","hsk30_level":"7-9","official":["o-7-9-042"],"title":"不是我说你","py":"Bù shì wǒ shuō nǐ","func":"短语 › 固定短语","struct":"不是我说你，句子","vi":"Không phải tôi nói bạn nhưng..., trách nhẹ.","use":"Khẩu ngữ.","ex":[["不是我说你，你也太马虎了。","Bù shì wǒ shuō nǐ, nǐ yě tài mǎhu le.","Không phải tôi nói bạn nhưng bạn cẩu thả quá."],["不是我说你，你该早点休息。","Bù shì wǒ shuō nǐ, nǐ gāi zǎo diǎn xiūxi.","Không phải tôi nói chứ bạn nên nghỉ sớm."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-043","hsk30_level":"7-9","official":["o-7-9-043"],"title":"反过来（说）","py":"Fǎnguolái（shuō）","func":"短语 › 固定短语","struct":"反过来 (说)，句子","vi":"Nói ngược lại, đổi chiều.","use":"Chuyển hướng lập luận.","ex":[["反过来说，你也有责任。","Fǎnguolái shuō, nǐ yě yǒu zérèn.","Nói ngược lại, bạn cũng có trách nhiệm."],["反过来想，这也是个机会。","Fǎnguolái xiǎng, zhè yě shì ge jīhuì.","Nghĩ ngược lại đây cũng là cơ hội."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-044","hsk30_level":"7-9","official":["o-7-9-044"],"title":"概括来说","py":"Gàikuò lái shuō","func":"短语 › 固定短语","struct":"概括来说，句子","vi":"Nói tóm lại, tóm tắt.","use":"Mở đầu phần kết.","ex":[["概括来说，这次活动很成功。","Gàikuò lái shuō, zhè cì huódòng hěn Chénggōng.","Tóm lại, hoạt động lần này rất thành công."],["概括来说，有三个原因。","Gàikuò lái shuō, yǒu sān ge yuányīn.","Tóm lại có ba nguyên nhân."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-046","hsk30_level":"7-9","official":["o-7-9-046"],"title":"话是这么说","py":"Huà shì zhème shuō","func":"短语 › 固定短语","struct":"话是这么说，可是/但是……","vi":"Nói thì nói vậy, nhưng...","use":"Nhượng bộ rồi chuyển ý.","ex":[["话是这么说，可做起来不容易。","Huà shì zhème shuō, kě zuò qǐlai bùróng yì.","Nói thế thì nói thế, làm không dễ."],["话是这么说，但我还是担心。","Huà shì zhème shuō, dàn wǒ háishi dānxīn.","Nói vậy nhưng tôi vẫn lo."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-047","hsk30_level":"7-9","official":["o-7-9-047"],"title":"话（又）说回来","py":"Huà（yòu）shuō huílai","func":"短语 › 固定短语","struct":"话(又)说回来，句子","vi":"Nói đi cũng phải nói lại, quay về chủ đề.","use":"Chuyển ý.","ex":[["话又说回来，他也不容易。","Huà yòu shuō huílai, tā yě bùróng yì.","Nói đi cũng phải nói lại, anh ấy cũng không dễ."],["话说回来，你打算怎么办？","Huà shuō huílai, nǐ dǎsuàn zěnmebàn?","Nói lại thì bạn tính sao?"]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-048","hsk30_level":"7-9","official":["o-7-9-048"],"title":"换句话说","py":"Huàn jù huà shuō","func":"短语 › 固定短语","struct":"换句话说，句子","vi":"Nói cách khác, diễn đạt lại.","use":"Giải thích ý trước.","ex":[["换句话说，你不同意。","Huàn jù huà shuō, nǐ bùtóng yì.","Nói cách khác, bạn không đồng ý."],["换句话说，这是不可能的。","Huàn jù huà shuō, zhè shì bù kěnéng de.","Nói cách khác, điều này là không thể."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-049","hsk30_level":"7-9","official":["o-7-9-049"],"title":"简（而）言之","py":"Jiǎn（ér）yán zhī","func":"短语 › 固定短语","struct":"简(而)言之，句子","vi":"Nói gọn lại, tóm lại, văn viết.","use":"Dùng kết luận.","ex":[["简言之，我们需要更多时间。","Jiǎn yán zhī, wǒmen xūyào gēng duō shíjiān.","Nói gọn lại, chúng ta cần thêm thời gian."],["简而言之，计划失败了。","Jiǎn ér yán zhī, jìhuà shībài le.","Tóm lại kế hoạch thất bại."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-050","hsk30_level":"7-9","official":["o-7-9-050"],"title":"可不（是嘛）","py":"Kě bù（shì má）","func":"短语 › 固定短语","struct":"可不(是嘛)","vi":"Đúng thế, chứ còn gì: đồng tình mạnh.","use":"Khẩu ngữ, dùng đáp lại.","ex":[["——今天真冷。——可不是嘛！","——Jīntiān zhēn lěng. ——kěbushì má!","— Hôm nay lạnh thật. — Chứ còn gì!"],["可不，他就是这样的人。","Kě bù, tā jiùshì zhèyàng de rén.","Đúng thế, anh ấy là người như vậy."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-051","hsk30_level":"7-9","official":["o-7-9-051"],"title":"老实说","py":"Lǎoshíshuō","func":"短语 › 固定短语","struct":"老实说，句子","vi":"Nói thật lòng.","use":"Mở đầu lời thành thật.","ex":[["老实说，我不太喜欢这个。","Lǎoshíshuō, wǒ bùtài xǐhuan zhè ge.","Nói thật, tôi không thích lắm cái này."],["老实说，我有点儿害怕。","Lǎoshíshuō, wǒ yǒudiǎnr hàipà.","Nói thật, tôi hơi sợ."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-052","hsk30_level":"7-9","official":["o-7-9-052"],"title":"（你）还别说","py":"（Nǐ）hái biéshuō","func":"短语 › 固定短语","struct":"(你)还别说，句子","vi":"Nói thật, đừng nói thế mà đúng: xác nhận điều bất ngờ.","use":"Khẩu ngữ.","ex":[["你还别说，他做得真不错。","Nǐ hái biéshuō, tā zuò de zhēn bùcuò.","Nói thật, anh ấy làm khá tốt đấy."],["还别说，这办法挺有用。","Hái biéshuō, zhè bànfǎ tǐng yǒuyòng.","Đừng nói chứ, cách này khá hữu dụng."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-053","hsk30_level":"7-9","official":["o-7-9-053"],"title":"你看你","py":"Nǐ kàn nǐ","func":"短语 › 固定短语","struct":"你看你 (+ 动词/形容词)","vi":"Nhìn bạn kìa: trách nhẹ.","use":"Khẩu ngữ.","ex":[["你看你，又迟到了。","Nǐ kàn nǐ, yòu chídào le.","Nhìn bạn kìa, lại đến muộn rồi."],["你看你，脸都红了。","Nǐ kàn nǐ, liǎn dōu hóng le.","Nhìn bạn kìa, mặt đỏ cả lên."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-054","hsk30_level":"7-9","official":["o-7-9-054"],"title":"说到哪儿去了","py":"Shuō dào nǎr qù le","func":"短语 › 固定短语","struct":"说到哪儿去了！","vi":"Nói đi đâu vậy, đáp lại khi người kia nói quá lời hay hiểu lầm.","use":"Khẩu ngữ.","ex":[["你说到哪儿去了，我们是朋友嘛。","Nǐ shuō dào nǎr qù le, wǒmen shì péngyou má.","Nói gì vậy, chúng ta là bạn mà."],["说到哪儿去了，我没生气。","Shuō dào nǎr qù le, wǒ méi shēngqì.","Nói đi đâu vậy, tôi không giận."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-055","hsk30_level":"7-9","official":["o-7-9-055"],"title":"说真的","py":"Shuōzhēnde","func":"短语 › 固定短语","struct":"说真的，句子","vi":"Nói thật đấy, nói nghiêm túc.","use":"Khẩu ngữ.","ex":[["说真的，我很想你。","Shuōzhēnde, wǒ hěn xiǎng nǐ.","Nói thật, tôi rất nhớ bạn."],["说真的，这件事不容易。","Shuōzhēnde, zhè jiàn shì bùróng yì.","Nói thật, việc này không dễ."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-056","hsk30_level":"7-9","official":["o-7-9-056"],"title":"退一步说","py":"Tuì yī bù shuō","func":"短语 › 固定短语","struct":"退一步说，句子","vi":"Lùi một bước mà nói, nhượng bộ.","use":"Dùng thương lượng.","ex":[["退一步说，就算他错了，也不用这样。","Tuì yī bù shuō, jiùsuàn tā cuò le, yě bùyòng zhèyàng.","Lùi một bước mà nói, kể cả anh ấy sai cũng không cần thế."],["退一步说，我们还有机会。","Tuì yī bù shuō, wǒmen háiyǒu jīhuì.","Lùi một bước, chúng ta vẫn còn cơ hội."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-057","hsk30_level":"7-9","official":["o-7-9-057"],"title":"无论如何","py":"Wúlùnrúhé","func":"短语 › 固定短语","struct":"无论如何，句子","vi":"Dù thế nào đi nữa.","use":"Nhấn quyết tâm.","ex":[["无论如何我都要去。","Wúlùnrúhé wǒ dōu yào qù.","Dù thế nào tôi cũng phải đi."],["无论如何，请你来一趟。","Wúlùnrúhé, qǐng nǐ lái yī tāng.","Dù sao xin bạn đến một chuyến."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-058","hsk30_level":"7-9","official":["o-7-9-058"],"title":"要（让）我说","py":"Yào（ràng）wǒ shuō","func":"短语 › 固定短语","struct":"要(让)我说，句子","vi":"Theo tôi nói thì: nêu ý kiến.","use":"Khẩu ngữ.","ex":[["要让我说，这办法不行。","Yào ràng wǒ shuō, zhè bànfǎ bùxíng.","Theo tôi thì cách này không ổn."],["要我说，我们早点儿走吧。","Yào wǒ shuō, wǒmen zǎo diǎn r zǒu ba.","Theo tôi, ta đi sớm đi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-059","hsk30_level":"7-9","official":["o-7-9-059"],"title":"这不","py":"Zhè bù","func":"短语 › 固定短语","struct":"这不 + 句子","vi":"Đấy, đây này: chỉ sự việc vừa xảy ra như đã nói.","use":"Khẩu ngữ.","ex":[["这不，说曹操曹操就到。","Zhè bù, shuō 曹 cāo 曹 cāo jiù dào.","Đấy, nhắc Tào Tháo Tào Tháo đến."],["这不，雨又下起来了。","Zhè bù, yǔ yòu xià qǐlai le.","Đấy, mưa lại đổ rồi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-060","hsk30_level":"7-9","official":["o-7-9-060"],"title":"这样一来","py":"Zhèyàngyīlái","func":"短语 › 固定短语","struct":"这样一来，句子","vi":"Như vậy thì, kết quả của điều đã nói.","use":"Nối câu.","ex":[["这样一来，问题就解决了。","Zhèyàngyīlái, wèntí jiù jiějué le.","Như vậy thì vấn đề được giải quyết."],["这样一来，大家都方便。","Zhèyàngyīlái, dàjiā dōu fāngbiàn.","Thế là ai cũng tiện."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-061","hsk30_level":"7-9","official":["o-7-9-061"],"title":"真是的","py":"Zhēnshide","func":"短语 › 固定短语","struct":"真是的！","vi":"Thật là, bực mình hay phàn nàn nhẹ.","use":"Khẩu ngữ.","ex":[["真是的，又忘带钥匙了。","Zhēnshide, yòu wàng dài yàoshi le.","Thật là, lại quên chìa khóa."],["真是的，怎么又下雨了。","Zhēnshide, zěnme yòu xiàyǔ le.","Thật là, sao lại mưa."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-062","hsk30_level":"7-9","official":["o-7-9-062"],"title":"综上所述","py":"Zōngshàngsuǒshù","func":"短语 › 固定短语","struct":"综上所述，句子","vi":"Tổng hợp những điều trên, tóm lại, văn viết.","use":"Kết luận của bài.","ex":[["综上所述，这个方案可行。","Zōngshàngsuǒshù, zhè ge fāngàn kěxíng.","Tổng hợp trên, phương án này khả thi."],["综上所述，我们应该改进。","Zōngshàngsuǒshù, wǒmen yīnggāi gǎijìn.","Tóm lại chúng ta nên cải thiện."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-064","hsk30_level":"7-9","official":["o-7-9-064"],"title":"总而言之","py":"Zǒngéryánzhī","func":"短语 › 固定短语","struct":"总而言之，句子","vi":"Tóm lại, nói chung.","use":"Kết luận.","ex":[["总而言之，大家都很满意。","Zǒngéryánzhī, dàjiā dōu hěn mǎnyì.","Tóm lại mọi người đều hài lòng."],["总而言之，别担心。","Zǒngéryánzhī, bié dānxīn.","Nói chung đừng lo."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-065","hsk30_level":"7-9","official":["o-7-9-065"],"title":"X到这个地步/份上","py":"Xdào zhè ge dìbù/fèn shàng","func":"短语 › 固定短语","struct":"动词/形容词 + 到 + 这个地步/份上","vi":"Đến mức này, đến nước này.","use":"Thường than phiền hoặc ngạc nhiên.","ex":[["事情发展到这个地步，谁也没想到。","Shìqing fāzhǎn dào zhè ge dìbù, shéi yě méixiǎngdào.","Sự việc đến nước này không ai ngờ."],["他穷到这个份上了。","Tā qióng dào zhè ge fèn shàng le.","Anh ấy nghèo đến mức này rồi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-066","hsk30_level":"7-9","official":["o-7-9-066"],"title":"X得要命/要死","py":"Xde yàomìng/yào sǐ","func":"短语 › 固定短语","struct":"形容词/动词 + 得 + 要命/要死","vi":"Cực kỳ, chết đi được (khẩu ngữ).","use":"Bổ ngữ mức độ.","ex":[["今天热得要命。","Jīntiān rè de yàomìng.","Hôm nay nóng chết đi được."],["我饿得要死。","Wǒ è de yào sǐ.","Tôi đói chết mất."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-067","hsk30_level":"7-9","official":["o-7-9-067"],"title":"X都不/没X","py":"Xdōu bù/méiX","func":"短语 › 固定短语","struct":"动词 + 都 + 不/没 + 动词","vi":"Ngay cả... cũng không: nhấn mạnh.","use":"Lặp lại động từ.","ex":[["他看都没看就走了。","Tā kàn dōu méi kàn jiù zǒu le.","Anh ấy nhìn cũng không nhìn đã đi."],["我想都不想就答应了。","Wǒ xiǎng dōu bù xiǎng jiù dāying le.","Tôi không nghĩ cũng đồng ý."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-068","hsk30_level":"7-9","official":["o-7-9-068"],"title":"X就X个Y","py":"XjiùXgeY","func":"短语 › 固定短语","struct":"动词 + 就 + 动词 + 个 + Y","vi":"Cứ làm cho đến nơi đến chốn, làm cho ra...","use":"Ví dụ 玩就玩个痛快.","ex":[["要玩就玩个痛快。","Yào wán jiù wán ge tòngkuài.","Đã chơi thì chơi cho thật đã."],["要说就说个明白。","Yào shuō jiù shuō ge míngbai.","Đã nói thì nói cho rõ."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-069","hsk30_level":"7-9","official":["o-7-9-069"],"title":"X了Y，Y了X","py":"XleY, YleX","func":"短语 › 固定短语","struct":"X + 了 + Y，Y + 了 + X","vi":"Làm đi làm lại X rồi Y, Y rồi X.","use":"Nhấn lặp lại.","ex":[["他写了改，改了写，终于完成了。","Tā xiě le gǎi, gǎi le xiě, zhōngyú wánchéng le.","Anh ấy viết rồi sửa, sửa rồi viết, rốt cuộc xong."],["吃了睡，睡了吃。","Chī le shuì, shuì le chī.","Ăn rồi ngủ, ngủ rồi ăn."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-070","hsk30_level":"7-9","official":["o-7-9-070"],"title":"X也好，Y也罢","py":"Xyěhǎo, Yyě bà","func":"短语 › 固定短语","struct":"X + 也好，Y + 也罢，都……","vi":"Dù X hay Y thì đều.","use":"Liệt kê hai khả năng.","ex":[["成功也好，失败也罢，都要试试。","Chénggōng yěhǎo, shībài yě bà, dōu yào shì shì.","Thành công hay thất bại cũng đều phải thử."],["你来也好，不来也罢，我都去。","Nǐ lái yěhǎo, bù lái yě bà, wǒ dōu qù.","Bạn đến hay không tôi cũng đi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-071","hsk30_level":"7-9","official":["o-7-9-071"],"title":"别提（有）多+形容词+了","py":"Bié tí（yǒu）duō+xíngróng cí+le","func":"短语 › 固定短语","struct":"别提(有)多 + 形容词 + 了","vi":"Khỏi nói là bao nhiêu, vô cùng.","use":"Khẩu ngữ.","ex":[["他别提有多高兴了。","Tā bié tí yǒu duō gāoxìng le.","Anh ấy khỏi nói là vui thế nào."],["这儿别提多热闹了。","Zhèr bié tí duō rènao le.","Chỗ này náo nhiệt vô cùng."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-072","hsk30_level":"7-9","official":["o-7-9-072"],"title":"不亚于……","py":"Bùyàyú……","func":"短语 › 固定短语","struct":"A + 不亚于 + B","vi":"Không kém gì, không thua.","use":"So sánh ngang.","ex":[["他的水平不亚于专业选手。","Tā de shuǐpíng bùyàyú zhuānyè xuǎnshǒu.","Trình độ anh ấy không kém gì tuyển thủ chuyên nghiệp."],["这里的风景不亚于国外。","Zhèlǐ de fēngjǐng bùyàyú guówài.","Phong cảnh ở đây không kém nước ngoài."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-073","hsk30_level":"7-9","official":["o-7-9-073"],"title":"不知X是/才好","py":"BùzhīXshì/cái hǎo","func":"短语 › 固定短语","struct":"不知 + 动词 + 才好","vi":"Không biết nên... mới phải.","use":"Diễn tả lúng túng.","ex":[["我不知怎么办才好。","Wǒ bùzhī zěnmebàn cái hǎo.","Tôi không biết làm thế nào mới được."],["他不知说什么才好。","Tā bùzhī shuō shénme cái hǎo.","Anh ấy không biết nói gì cho phải."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-075","hsk30_level":"7-9","official":["o-7-9-075"],"title":"动词+得个……","py":"Dòng cí+de ge……","func":"短语 › 固定短语","struct":"动词 + 得 + 个 + 形容词/动词","vi":"Làm đến mức, làm cho ra, đến mức độ.","use":"Khẩu ngữ.","ex":[["他们玩得个痛快。","Tāmen wán de ge tòngkuài.","Họ chơi thật đã."],["累得个半死。","Lěi de ge bàn sǐ.","Mệt gần chết."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-076","hsk30_level":"7-9","official":["o-7-9-076"],"title":"动词+个X","py":"Dòng cí+geX","func":"短语 › 固定短语","struct":"动词 + 个 + 形容词/动词","vi":"个 làm trợ từ kết cấu, biểu thị mức độ hoặc kết quả.","use":"Ví dụ 打个够, 说个清楚.","ex":[["我们说个清楚吧。","Wǒmen shuō ge qīngchu ba.","Chúng ta nói cho rõ ràng nhé."],["今天玩个痛快。","Jīntiān wán ge tòngkuài.","Hôm nay chơi cho thật đã."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-077","hsk30_level":"7-9","official":["o-7-9-077"],"title":"该X（就）X，该Y（就）Y","py":"GāiX（jiù）X, gāiY（jiù）Y","func":"短语 › 固定短语","struct":"该 + A + (就) + A，该 + B + (就) + B","vi":"Việc gì ra việc đó, đến lúc thì làm.","use":"Khẩu ngữ.","ex":[["该吃就吃，该睡就睡。","Gāi chī jiù chī, gāi shuì jiù shuì.","Đến lúc ăn thì ăn, đến lúc ngủ thì ngủ."],["该说就说，该做就做。","Gāi shuō jiù shuō, gāi zuò jiù zuò.","Cần nói thì nói, cần làm thì làm."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-078","hsk30_level":"7-9","official":["o-7-9-078"],"title":"何至于……","py":"Hé zhìyú……","func":"短语 › 固定短语","struct":"何至于 + 动词/形容词","vi":"Hà tất phải, cần gì đến mức.","use":"Phản vấn, văn viết.","ex":[["何至于为这点小事吵架？","Hé zhìyú wèi zhè diǎn xiǎo shì chǎojià?","Cần gì phải cãi nhau vì việc nhỏ này?"],["何至于这样？","Hé zhìyú zhèyàng?","Hà tất đến mức này?"]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-079","hsk30_level":"7-9","official":["o-7-9-079"],"title":"仅次于X","py":"JǐncìyúX","func":"短语 › 固定短语","struct":"A + 仅次于 + B","vi":"Chỉ đứng sau, đứng thứ hai.","use":"Dùng trong so sánh xếp hạng.","ex":[["他的成绩仅次于小王。","Tā de chéngjì jǐncìyú xiǎo wáng.","Điểm anh ấy chỉ sau Tiểu Vương."],["这座城市的人口仅次于北京。","Zhè zuò chéngshì de rénkǒu jǐncìyú Běijīng.","Dân số thành phố này chỉ sau Bắc Kinh."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-080","hsk30_level":"7-9","official":["o-7-9-080"],"title":"看在X的面子上","py":"Kàn zàiXde miànzi shàng","func":"短语 › 固定短语","struct":"看在 + 人 + 的面子上，句子","vi":"Nể mặt ai mà, vì thể diện.","use":"Dùng để xin hay tha thứ.","ex":[["看在你的面子上，我原谅他。","Kàn zài nǐ de miànzi shàng, wǒ yuánliàng tā.","Nể mặt bạn tôi tha cho anh ấy."],["看在朋友的面子上，帮他一次吧。","Kàn zài péngyou de miànzi shàng, bāng tā yī cì ba.","Nể mặt bạn bè, giúp anh ấy một lần."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-081","hsk30_level":"7-9","official":["o-7-9-081"],"title":"没什么+动词+头儿","py":"Méishénme+dòng cí+tóu r","func":"短语 › 固定短语","struct":"没什么 + 动词 + 头儿","vi":"Chẳng đáng để, chẳng có gì hay.","use":"头儿 làm hậu tố.","ex":[["这电影没什么看头儿。","Zhè diànyǐng méishénme kàn tóu r.","Phim này chẳng có gì đáng xem."],["这菜没什么吃头儿。","Zhè cài méishénme chī tóu r.","Món này chẳng có gì đáng ăn."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-082","hsk30_level":"7-9","official":["o-7-9-082"],"title":"没什么好+动词+的","py":"Méishénme hǎo+dòng cí+de","func":"短语 › 固定短语","struct":"没什么好 + 动词 + 的","vi":"Chẳng có gì đáng để...","use":"Giọng thờ ơ.","ex":[["这有什么好说的？","Zhè yǒu shénme hǎoshuō de?","Chuyện này có gì đáng nói?"],["没什么好担心的。","Méishénme hǎo dānxīn de.","Chẳng có gì phải lo."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-084","hsk30_level":"7-9","official":["o-7-9-084"],"title":"你说你一个X，……","py":"Nǐ shuō nǐ yī geX, ……","func":"短语 › 固定短语","struct":"你说你一个 + 名词，……","vi":"Bạn nói xem một người như bạn mà..., trách móc.","use":"Khẩu ngữ.","ex":[["你说你一个大男人，哭什么？","Nǐ shuō nǐ yī ge dà nánrén, kū shénme?","Bạn nói xem, đàn ông con trai khóc làm gì?"],["你说你一个老师，怎么这样？","Nǐ shuō nǐ yī ge lǎoshī, zěnme zhèyàng?","Bạn là giáo viên mà sao lại thế?"]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-085","hsk30_level":"7-9","official":["o-7-9-085"],"title":"什么A的B的","py":"ShénmeAdeBde","func":"短语 › 固定短语","struct":"什么 + A + 的 + B + 的","vi":"Cái gì A cái gì B, liệt kê tùy ý.","use":"Khẩu ngữ, giọng không để ý.","ex":[["什么钱不钱的，我们是朋友。","Shénme qián bù qián de, wǒmen shì péngyou.","Tiền bạc gì chứ, ta là bạn."],["什么对的错的，别想了。","Shénme duì de cuò de, bié xiǎng le.","Đúng sai gì, đừng nghĩ nữa."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-086","hsk30_level":"7-9","official":["o-7-9-086"],"title":"视……而定","py":"Shì……ér dìng","func":"短语 › 固定短语","struct":"视 + 名词 + 而定","vi":"Tùy theo, tùy vào.","use":"Văn viết.","ex":[["价格视质量而定。","Jiàgé shì zhìliàng ér dìng.","Giá tùy chất lượng."],["去不去视天气而定。","Qù bù qù shì tiānqì ér dìng.","Đi hay không tùy thời tiết."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-087","hsk30_level":"7-9","official":["o-7-9-087"],"title":"谈何……","py":"Tán hé……","func":"短语 › 固定短语","struct":"谈何 + 动词/形容词","vi":"Nói gì đến, nói sao nổi.","use":"Phản vấn, văn viết.","ex":[["这么忙，谈何休息？","Zhème máng, tán hé xiūxi?","Bận thế này, nói gì nghỉ ngơi?"],["没有钱，谈何容易？","Méiyǒu qián, tán hé róngyì?","Không có tiền nói gì dễ dàng?"]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-089","hsk30_level":"7-9","official":["o-7-9-089"],"title":"想X之所想，急X之所急","py":"XiǎngXzhī suǒ xiǎng, jíXzhī suǒ jí","func":"短语 › 固定短语","struct":"想 + 人 + 之所想，急 + 人 + 之所急","vi":"Nghĩ điều người ta nghĩ, lo điều người ta lo.","use":"Văn viết, lời quảng cáo hay khẩu hiệu.","ex":[["我们要想客户之所想，急客户之所急。","Wǒmen yào xiǎng kèhù zhī suǒ xiǎng, jí kèhù zhī suǒ jí.","Chúng tôi nghĩ điều khách nghĩ, lo điều khách lo."],["好老师想学生之所想。","Hǎo lǎoshī xiǎng xuésheng zhī suǒ xiǎng.","Thầy tốt nghĩ điều học trò nghĩ."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-090","hsk30_level":"7-9","official":["o-7-9-090"],"title":"向……致以……","py":"Xiàng……zhì yǐ……","func":"短语 › 固定短语","struct":"向 + 人 + 致以 + 名词","vi":"Gửi tới ai lời, trang trọng.","use":"Ví dụ 致以问候, 致以谢意.","ex":[["向大家致以诚挚的问候。","Xiàng dàjiā zhì yǐ chéngzhì de wènhòu.","Xin gửi lời chào chân thành tới mọi người."],["向您致以最高的敬意。","Xiàng nín zhì yǐ zuì gāo de jìngyì.","Xin gửi tới ngài lòng kính trọng cao nhất."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-091","hsk30_level":"7-9","official":["o-7-9-091"],"title":"要X有/没X，要Y有/没Y","py":"YàoXyǒu/méiX, yàoYyǒu/méiY","func":"短语 › 固定短语","struct":"要 + A + 有 + A，要 + B + 有 + B","vi":"Cần gì có nấy, hoặc cần gì cũng không có.","use":"Nói đầy đủ hay thiếu.","ex":[["要钱有钱，要人有人。","Yào qián yǒu qián, yào rén yǒurén.","Cần tiền có tiền, cần người có người."],["要书没书，要笔没笔。","Yào shū méi shū, yào bǐ méi bǐ.","Cần sách không có sách, cần bút không có bút."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-092","hsk30_level":"7-9","official":["o-7-9-092"],"title":"因……而……","py":"Yīn……ér……","func":"短语 › 固定短语","struct":"因 + 原因 + 而 + 结果","vi":"Vì... mà...: văn viết.","use":"而 nối nguyên nhân và kết quả.","ex":[["他因病而缺席。","Tā yīn bìng ér quēxí.","Anh ấy vì bệnh mà vắng mặt."],["大家因他的成功而高兴。","Dàjiā yīn tā de Chénggōng ér gāoxìng.","Mọi người vui vì thành công của anh ấy."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-093","hsk30_level":"7-9","official":["o-7-9-093"],"title":"有何X","py":"Yǒu héX","func":"短语 › 固定短语","struct":"有何 + 名词","vi":"Có gì (văn viết, hỏi tu từ).","use":"Ví dụ 有何不可.","ex":[["这有何不可？","Zhè yǒu hé bù kě?","Việc này có gì không được?"],["你有何打算？","Nǐ yǒu hé dǎsuàn?","Bạn có dự định gì?"]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-094","hsk30_level":"7-9","official":["o-7-9-094"],"title":"有什么+动词+头儿","py":"Yǒu shénme+dòng cí+tóu r","func":"短语 › 固定短语","struct":"有什么 + 动词 + 头儿","vi":"Có gì đáng... (phản vấn).","use":"Phiên bản khẳng định của o-7-9-081.","ex":[["这电影有什么看头儿？","Zhè diànyǐng yǒu shénme kàn tóu r?","Phim này có gì đáng xem?"],["这菜有什么吃头儿？","Zhè cài yǒu shénme chī tóu r?","Món này có gì mà ăn?"]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-095","hsk30_level":"7-9","official":["o-7-9-095"],"title":"（在）……之余","py":"（Zài）……zhī yú","func":"短语 › 固定短语","struct":"(在) + 动词/短语 + 之余，……","vi":"Ngoài việc, bên cạnh việc.","use":"Văn viết.","ex":[["工作之余，他爱读书。","Gōngzuò zhī yú, tā ài dúshū.","Ngoài công việc, anh ấy thích đọc sách."],["在学习之余，也要锻炼。","Zài xuéxí zhī yú, yě yào duànliàn.","Ngoài học tập cũng phải tập luyện."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-096","hsk30_level":"7-9","official":["o-7-9-096"],"title":"值此……之际，……","py":"Zhí cǐ……zhī jì, ……","func":"短语 › 固定短语","struct":"值此 + 时间/事件 + 之际，……","vi":"Nhân dịp, vào lúc, trang trọng.","use":"Dùng trong thư, phát biểu.","ex":[["值此新年之际，祝大家快乐。","Zhí cǐ xīnnián zhī jì, zhù dàjiā kuàilè.","Nhân dịp năm mới chúc mọi người vui vẻ."],["值此毕业之际，我谢谢老师。","Zhí cǐ bìyè zhī jì, wǒ xièxie lǎoshī.","Nhân dịp tốt nghiệp, tôi cảm ơn thầy cô."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-097","hsk30_level":"7-9","official":["o-7-9-097"],"title":"比较句：A+形容词+于/过+B","py":"Bǐjiào jù: A+xíngróng cí+yú/guò+B","func":"句子的类型 › 特殊句型","struct":"A + 形容词 + 于/过 + B","vi":"So sánh văn viết: 于 hoặc 过 sau tính từ.","use":"Ví dụ 大于, 高于, 胜过.","ex":[["他的成绩高于平均水平。","Tā de chéngjì gāoyú píngjūn shuǐpíng.","Điểm anh ấy cao hơn mức trung bình."],["事实胜过雄辩。","Shìshí shèng guò xióng biàn.","Sự thật hơn hùng biện."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-099","hsk30_level":"7-9","official":["o-7-9-099"],"title":"一则……，二则……，三则……","py":"Yī zé……, èr zé……, sān zé……","func":"句子的类型 › 简单复句","struct":"一则 + A，二则 + B，三则 + C","vi":"Một là... hai là... ba là..., liệt kê lý do.","use":"Văn viết.","ex":[["我不去，一则太远，二则没时间。","Wǒ bù qù, yī zé tài yuǎn, èr zé méi shíjiān.","Tôi không đi, một là xa, hai là không có thời gian."],["一则省钱，二则方便。","Yī zé shěngqián, èr zé fāngbiàn.","Một là tiết kiệm, hai là tiện."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-100","hsk30_level":"7-9","official":["o-7-9-100"],"title":"所谓……，就是……","py":"Suǒwèi……, jiùshì……","func":"句子的类型 › 简单复句","struct":"所谓 + 概念，就是 + 解释","vi":"Cái gọi là... chính là... : giải thích khái niệm.","use":"Câu giải thích.","ex":[["所谓成功，就是做自己喜欢的事。","Suǒwèi Chénggōng, jiùshì zuò zìjǐ xǐhuan de shì.","Cái gọi là thành công chính là làm điều mình thích."],["所谓朋友，就是互相帮助的人。","Suǒwèi péngyou, jiùshì hùxiāng bāngzhù de rén.","Bạn bè là người giúp đỡ nhau."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-101","hsk30_level":"7-9","official":["o-7-9-101"],"title":"或……，或……","py":"Huò……, huò……","func":"句子的类型 › 简单复句","struct":"或 + A，或 + B","vi":"Hoặc A hoặc B, văn viết.","use":"Giống 或者, trang trọng hơn.","ex":[["大家或唱歌，或跳舞。","Dàjiā huò chànggē, huò tiàowǔ.","Mọi người hoặc hát hoặc nhảy."],["你可或来，或不来。","Nǐ kě huò lái, huò bù lái.","Bạn có thể đến hoặc không."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-102","hsk30_level":"7-9","official":["o-7-9-102"],"title":"宁可/宁愿……，也不……","py":"Nìngkě/nìngyuàn……, yě bù……","func":"句子的类型 › 简单复句","struct":"宁可/宁愿 + A，也不 + B","vi":"Thà A còn hơn B.","use":"Chọn cái chấp nhận được hơn.","ex":[["我宁可走路，也不坐那辆车。","Wǒ nìngkě zǒulù, yě bù zuò nà liàng chē.","Tôi thà đi bộ còn hơn ngồi xe đó."],["他宁愿饿着，也不求人。","Tā nìngyuàn è zhe, yě bù qiú rén.","Anh ấy thà đói còn hơn cầu người."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-103","hsk30_level":"7-9","official":["o-7-9-103"],"title":"与其……，宁愿/宁可……","py":"Yǔqí……, nìngyuàn/nìngkě……","func":"句子的类型 › 简单复句","struct":"与其 + A，宁愿/宁可 + B","vi":"Thay vì A thà B.","use":"Phủ định A, chọn B.","ex":[["与其等他，不如自己去。","Yǔqí děng tā, bùrú zìjǐ qù.","Thay vì đợi anh ấy chi bằng tự đi."],["与其吵架，宁可沉默。","Yǔqí chǎojià, nìngkě chénmò.","Thay vì cãi nhau thà im lặng."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-104","hsk30_level":"7-9","official":["o-7-9-104"],"title":"X（倒）是X（了），……","py":"X（dào）shìX（le）, ……","func":"句子的类型 › 简单复句","struct":"动词/形容词 + (倒) + 是 + 动词/形容词 + (了)，但……","vi":"Thì cũng là X, nhưng...","use":"Thừa nhận rồi chuyển ý.","ex":[["去倒是去了，没见到人。","Qù dàoshi qù le, méi jiàndào rén.","Đi thì có đi nhưng không gặp ai."],["好是好，就是贵。","Hǎo shì hǎo, jiùshì guì.","Tốt thì tốt, chỉ là đắt."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-105","hsk30_level":"7-9","official":["o-7-9-105"],"title":"别看……，……","py":"Biékàn……, ……","func":"句子的类型 › 简单复句","struct":"别看 + A，(可是/却) + B","vi":"Đừng thấy A mà: nhưng thực ra B.","use":"Nhượng bộ rồi đối lập.","ex":[["别看他年纪小，懂得可多了。","Biékàn tā niánjì xiǎo, dǒngde kě duō le.","Đừng thấy cậu ấy nhỏ, hiểu nhiều lắm."],["别看这房子旧，住着很舒服。","Biékàn zhè fángzi jiù, zhù zhe hěn shūfu.","Đừng thấy nhà cũ, ở rất dễ chịu."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-106","hsk30_level":"7-9","official":["o-7-9-106"],"title":"虽说……，但/可……","py":"Suīshuō……, dàn/kě……","func":"句子的类型 › 简单复句","struct":"虽说 + A，但/可 + B","vi":"Tuy nói là A nhưng B, khẩu ngữ hơn 虽然.","use":"虽说 là nhượng bộ.","ex":[["虽说便宜，但质量不好。","Suīshuō biànyí, dàn zhìliàng bù hǎo.","Tuy rẻ nhưng chất lượng không tốt."],["虽说是春天，可还很冷。","Suīshuō shì chūntiān, kě hái hěn lěng.","Tuy là mùa xuân nhưng vẫn lạnh."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-107","hsk30_level":"7-9","official":["o-7-9-107"],"title":"无论……与否，都……","py":"Wúlùn……yǔfǒu, dōu……","func":"句子的类型 › 简单复句","struct":"无论 + A + 与否，都 + B","vi":"Bất kể có hay không, đều.","use":"与否 là có hay không.","ex":[["无论成功与否，都要努力。","Wúlùn Chénggōng yǔfǒu, dōu yào nǔlì.","Thành công hay không đều phải cố gắng."],["无论你同意与否，我都去。","Wúlùn nǐ tóngyì yǔfǒu, wǒ dōu qù.","Bất kể bạn đồng ý hay không tôi cũng đi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-108","hsk30_level":"7-9","official":["o-7-9-108"],"title":"凡……（者），均（可）……","py":"Fán……（zhě）, jūn（kě）……","func":"句子的类型 › 简单复句","struct":"凡 + 条件 + (者)，均 + (可) + 结果","vi":"Phàm là... thì đều..., văn viết.","use":"Thường trong quy định.","ex":[["凡年满十八岁者，均可报名。","Fán nián mǎn shí bā suì zhě, jūn kě bàomíng.","Phàm đủ mười tám tuổi đều có thể đăng ký."],["凡是学生，均可免费参观。","Fánshì xuésheng, jūn kě miǎnfèi cānguān.","Phàm là học sinh đều được xem miễn phí."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-109","hsk30_level":"7-9","official":["o-7-9-109"],"title":"假若/假使……，……","py":"Jiǎ ruò/jiǎshǐ……, ……","func":"句子的类型 › 简单复句","struct":"假若/假使 + 条件，(就) + 结果","vi":"Giả như, nếu như, văn viết.","use":"Giống 如果, trang trọng hơn.","ex":[["假若他来，我们就开会。","Jiǎ ruò tā lái, wǒmen jiù kāihuì.","Giả như anh ấy đến thì ta họp."],["假使我是你，就不去。","Jiǎshǐ wǒ shì nǐ, jiù bù qù.","Giả sử tôi là bạn thì sẽ không đi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-110","hsk30_level":"7-9","official":["o-7-9-110"],"title":"幸亏/幸好……，不然/否则……","py":"Xìngkuī/xìnghǎo……, bùrán/fǒuzé……","func":"句子的类型 › 简单复句","struct":"幸亏/幸好 + A，不然/否则 + B","vi":"May mà A, nếu không thì B.","use":"B là hậu quả không mong muốn.","ex":[["幸亏你来了，不然我就迟到了。","Xìngkuī nǐ lái le, bùrán wǒ jiù chídào le.","May mà bạn đến, nếu không tôi đã muộn."],["幸好带了伞，否则就湿透了。","Xìnghǎo dài le sǎn, fǒuzé jiù shī tòu le.","May mang ô, nếu không thì ướt hết."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-111","hsk30_level":"7-9","official":["o-7-9-111"],"title":"纵然/纵使……，也……","py":"Zòngrán/zòng shǐ……, yě……","func":"句子的类型 › 简单复句","struct":"纵然/纵使 + A，也 + B","vi":"Cho dù A cũng B: nhượng bộ giả định.","use":"Văn viết.","ex":[["纵然失败，也不后悔。","Zòngrán shībài, yě bù hòuhuǐ.","Cho dù thất bại cũng không hối hận."],["纵使困难再大，也要去。","Zòng shǐ kùnnan zài dà, yě yào qù.","Dù khó thế nào cũng phải đi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-112","hsk30_level":"7-9","official":["o-7-9-112"],"title":"（因）……，故……","py":"（Yīn）……, gù……","func":"句子的类型 › 简单复句","struct":"(因) + A，故 + B","vi":"Vì A nên B, văn viết (故 = vì thế).","use":"Dùng trong văn bản trang trọng.","ex":[["因天气不好，故航班取消。","Yīn tiānqì bù hǎo, gù hángbān qǔxiāo.","Vì thời tiết xấu nên chuyến bay hủy."],["他有事，故未出席。","Tā yǒushì, gù wèi chūxí.","Anh ấy có việc nên không dự."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-113","hsk30_level":"7-9","official":["o-7-9-113"],"title":"……，以至（于）……","py":"……, Yǐzhì（yú）……","func":"句子的类型 › 简单复句","struct":"A，以至(于) + B","vi":"Đến mức, dẫn đến.","use":"Hậu quả của A.","ex":[["他太累了，以至于睡着了。","Tā tài lěi le, yǐzhìyú shuìzháo le.","Anh ấy mệt quá đến nỗi ngủ thiếp."],["声音太小，以至听不清。","Shēngyīn tài xiǎo, yǐzhì tīng bù qīng.","Giọng quá nhỏ đến mức nghe không rõ."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-115","hsk30_level":"7-9","official":["o-7-9-115"],"title":"……不说，还……","py":"……Bù shuō, hái……","func":"句子的类型 › 简单复句","struct":"A + 不说，还 + B","vi":"A thì khỏi nói, còn B nữa.","use":"Nhấn B nặng hơn A.","ex":[["他迟到不说，还大声说话。","Tā chídào bù shuō, hái dàshēng shuōhuà.","Anh ấy đến muộn chưa nói, còn nói to nữa."],["他不帮忙不说，还添乱。","Tā bù bāngmáng bù shuō, hái tiān luàn.","Anh ấy không giúp đã đành, còn gây rối thêm."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-116","hsk30_level":"7-9","official":["o-7-9-116"],"title":"连……都……，更不用说……了","py":"Lián……dōu……, gēng bùyòngshuō……le","func":"句子的类型 › 简单复句","struct":"连 + A + 都 + 动词，更不用说 + B + 了","vi":"Ngay cả A cũng, huống chi B.","use":"Nhấn mạnh bằng ví dụ khó.","ex":[["连孩子都懂，更不用说大人了。","Lián háizi dōu dǒng, gēng bùyòngshuō dàren le.","Đến trẻ con còn hiểu huống chi người lớn."],["他连汉字都不会写，更不用说写文章了。","Tā lián hànzì dōu bù huì xiě, gēng bùyòngshuō xiě wénzhāng le.","Anh ấy ngay cả chữ cũng không viết được, nói gì viết bài."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-118","hsk30_level":"7-9","official":["o-7-9-118"],"title":"……，更不用说……了","py":"……, Gēng bùyòngshuō……le","func":"句子的类型 › 简单复句","struct":"A，更不用说 + B + 了","vi":"Huống chi, nói gì đến.","use":"Đứng cuối.","ex":[["我连走路都累，更不用说跑步了。","Wǒ lián zǒulù dōu lěi, gēng bùyòngshuō pǎobù le.","Đi bộ tôi còn mệt, nói gì chạy."],["他平时都不吃，更不用说今天了。","Tā píngshí dōu bù chī, gēng bùyòngshuō jīntiān le.","Ngày thường anh ấy còn không ăn, nói gì hôm nay."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-119","hsk30_level":"7-9","official":["o-7-9-119"],"title":"为（了）……起见，……","py":"Wèi（le）……qǐ jiàn, ……","func":"句子的类型 › 简单复句","struct":"为(了) + 目的 + 起见，……","vi":"Vì lẽ gì đó nên (nhằm mục đích).","use":"Trang trọng.","ex":[["为了安全起见，请系好安全带。","Wèile ānquán qǐ jiàn, qǐng xì hǎo ānquán dài.","Để an toàn xin thắt dây an toàn."],["为方便起见，请提前预约。","Wèi fāngbiàn qǐ jiàn, qǐng tíqián yùyuē.","Cho tiện, xin hẹn trước."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-120","hsk30_level":"7-9","official":["o-7-9-120"],"title":"……，以……","py":"……, Yǐ……","func":"句子的类型 › 简单复句","struct":"A，以 + 动词","vi":"Để, nhằm (mục đích), văn viết.","use":"以 đứng đầu vế mục đích.","ex":[["他努力学习，以取得好成绩。","Tā nǔlì xuéxí, yǐ qǔdé hǎo chéngjì.","Anh ấy học chăm để đạt thành tích tốt."],["我们提前出发，以免迟到。","Wǒmen tíqián chūfā, yǐmiǎn chídào.","Chúng tôi đi sớm để khỏi muộn."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-121","hsk30_level":"7-9","official":["o-7-9-121"],"title":"非得……才……","py":"Fēiděi……cái……","func":"句子的类型 › 简单复句","struct":"非得 + A + 才 + B","vi":"Nhất định phải... mới...","use":"Khẩu ngữ, nhấn bắt buộc.","ex":[["他非得亲自去才放心。","Tā fēiděi qīnzì qù cái fàngxīn.","Anh ấy nhất định phải tự đi mới yên tâm."],["非得努力才能成功。","Fēiděi nǔlì cáinéng Chénggōng.","Nhất định phải cố gắng mới thành công."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-122","hsk30_level":"7-9","official":["o-7-9-122"],"title":"任……也……","py":"Rèn……yě……","func":"句子的类型 › 简单复句","struct":"任 + A + 也 + B","vi":"Mặc cho A cũng B, bất kể.","use":"Văn viết, khẩu ngữ.","ex":[["任你怎么说，我也不去。","Rèn nǐ zěnme shuō, wǒ yě bù qù.","Mặc bạn nói thế nào tôi cũng không đi."],["任他怎么劝，她也不听。","Rèn tā zěnme quàn, tā yě bù tīng.","Mặc anh ấy khuyên thế nào cô ấy cũng không nghe."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-123","hsk30_level":"7-9","official":["o-7-9-123"],"title":"多重并列复句","py":"Duō zhòng bìngliè fù jù","func":"句子的类型 › 多重复句","struct":"分句1，分句2；分句3，分句4","vi":"Câu ghép nhiều tầng có quan hệ song song ở nhiều tầng.","use":"Mỗi tầng có thể có từ nối riêng.","ex":[["他既会唱歌，又会跳舞；她既爱读书，又爱运动。","Tā jì huì chànggē, yòu huì tiàowǔ; tā jì ài dúshū, yòu ài yùndòng.","Anh ấy vừa biết hát vừa biết nhảy; cô ấy vừa thích đọc vừa thích thể thao."],["一方面要学习，一方面要工作，另一方面还要休息。","Yīfāngmiàn yào xuéxí, yīfāngmiàn yào gōngzuò, lìngyīfāngmiàn hái yào xiūxi.","Một mặt phải học, một mặt phải làm, mặt khác còn phải nghỉ."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-124","hsk30_level":"7-9","official":["o-7-9-124"],"title":"多重转折复句","py":"Duō zhòng zhuǎnzhé fù jù","func":"句子的类型 › 多重复句","struct":"分句1，但是 分句2，不过 分句3","vi":"Câu ghép nhiều tầng chuyển ý.","use":"Có hai lần chuyển hướng.","ex":[["他很聪明，但是不努力，所以成绩一般。","Tā hěn cōngming, dànshì bù nǔlì, suǒyǐ chéngjì yībān.","Anh ấy thông minh nhưng không chăm nên điểm thường."],["虽然很累，但我很快乐，不过也想休息。","Suīrán hěn lěi, dàn wǒ hěn kuàilè, bùguò yě xiǎng xiūxi.","Tuy mệt nhưng tôi vui, có điều cũng muốn nghỉ."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-125","hsk30_level":"7-9","official":["o-7-9-125"],"title":"多重假设复句","py":"Duō zhòng jiǎshè fù jù","func":"句子的类型 › 多重复句","struct":"如果 A，那么 B；要是 C，就 D","vi":"Câu ghép nhiều tầng giả thiết.","use":"Giả thiết lồng giả thiết.","ex":[["如果明天下雨，我们就不去；要是不下，就早点儿出发。","Rúguǒ míngtiān xiàyǔ, wǒmen jiù bù qù; yàoshi bù xià, jiù zǎo diǎn r chūfā.","Nếu mai mưa thì ta không đi; nếu không mưa thì xuất phát sớm."],["假如他同意，我就去，不然就算了。","Jiǎrú tā tóngyì, wǒ jiù qù, bùrán jiùsuàn le.","Nếu anh ấy đồng ý tôi đi, nếu không thì thôi."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-126","hsk30_level":"7-9","official":["o-7-9-126"],"title":"多重因果复句","py":"Duō zhòng yīn guǒ fù jù","func":"句子的类型 › 多重复句","struct":"因为 A，所以 B，因此 C","vi":"Câu ghép nhiều tầng nhân quả.","use":"Quan hệ nhân quả nối tiếp.","ex":[["因为下雨，所以路滑，因此出了事故。","Yīnwèi xiàyǔ, suǒyǐ lù huá, yīncǐ chū le shìgù.","Vì mưa nên đường trơn, do đó xảy ra tai nạn."],["因为他努力，所以成功了，因此大家都很高兴。","Yīnwèi tā nǔlì, suǒyǐ Chénggōng le, yīncǐ dàjiā dōu hěn gāoxìng.","Vì anh ấy cố gắng nên thành công, do đó mọi người đều vui."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-127","hsk30_level":"7-9","official":["o-7-9-127"],"title":"多重递进复句","py":"Duō zhòng dì jìn fù jù","func":"句子的类型 › 多重复句","struct":"不但 A，而且 B，甚至 C","vi":"Câu ghép nhiều tầng tăng tiến.","use":"Mức độ tăng dần.","ex":[["他不但会说，而且会写，甚至会翻译。","Tā bùdàn huì shuō, érqiě huì xiě, shènzhì huì fānyì.","Anh ấy không những nói được mà còn viết được, thậm chí biết dịch."],["这里不但漂亮，而且便宜，甚至免费。","Zhèlǐ bùdàn piàoliang, érqiě biànyí, shènzhì miǎnfèi.","Chỗ này không những đẹp mà còn rẻ, thậm chí miễn phí."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-128","hsk30_level":"7-9","official":["o-7-9-128"],"title":"语段：时间顺序","py":"Yǔ duàn: shíjiān shùnxù","func":"语段（句群）","struct":"按先后时间排列句子","vi":"Đoạn văn sắp xếp theo thứ tự thời gian.","use":"Dùng 先, 然后, 接着, 最后.","ex":[["早上我先洗脸，然后吃早饭，接着去上班，最后晚上回家。","Zǎoshang wǒ xiān xǐ liǎn, ránhòu chī zǎofàn, jiēzhe qù shàngbān, zuìhòu wǎnshang huíjiā.","Sáng tôi rửa mặt, rồi ăn sáng, sau đó đi làm, tối về nhà."],["昨天他先看书，后来看电影。","Zuótiān tā xiān kàn shū, hòulái kàn diànyǐng.","Hôm qua anh ấy đọc sách trước, sau đó xem phim."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-129","hsk30_level":"7-9","official":["o-7-9-129"],"title":"语段：空间顺序","py":"Yǔ duàn: kōngjiān shùnxù","func":"语段（句群）","struct":"按空间位置排列句子","vi":"Đoạn văn sắp xếp theo vị trí không gian.","use":"Dùng 左边, 右边, 前面, 后面.","ex":[["教室前面是黑板，左边是窗户，右边是门。","Jiàoshì qiánmiàn shì hēibǎn, zuǒbian shì chuānghu, yòubian shì mén.","Phía trước lớp là bảng, bên trái là cửa sổ, bên phải là cửa ra vào."],["楼下有商店，楼上是办公室。","Lóuxià yǒu shāngdiàn, lóushàng shì bàngōngshì.","Dưới lầu là cửa hàng, trên lầu là văn phòng."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-130","hsk30_level":"7-9","official":["o-7-9-130"],"title":"语段：逻辑顺序","py":"Yǔ duàn: luóji shùnxù","func":"语段（句群）","struct":"按因果、总分等逻辑排列句子","vi":"Đoạn văn sắp xếp theo mạch lý luận: nguyên nhân kết quả, tổng phân.","use":"Dùng 首先, 其次, 因此, 总之.","ex":[["首先要学好汉字，其次要多说，因此要多练习。","Shǒuxiān yào xué hǎo hànzì, qícì yào duō shuō, yīncǐ yào duō liànxí.","Trước tiên phải học tốt chữ Hán, tiếp theo phải nói nhiều, vì vậy cần luyện tập nhiều."],["总之，学习要坚持。","Zǒngzhī, xuéxí yào jiānchí.","Tóm lại học tập phải kiên trì."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-131","hsk30_level":"7-9","official":["o-7-9-131"],"title":"语段：话题延伸","py":"Yǔ duàn: huàtí yánshēn","func":"语段（句群）","struct":"话题 → 相关细节","vi":"Mở rộng chủ đề: từ chủ đề chung đi vào chi tiết liên quan.","use":"Câu sau triển khai câu trước.","ex":[["我喜欢旅行。去年我去了云南，那里的风景特别美。","Wǒ xǐhuan lǚxíng. qùnián wǒ qù le yún nán, nàli de fēngjǐng tèbié měi.","Tôi thích du lịch. Năm ngoái tôi đi Vân Nam, phong cảnh ở đó rất đẹp."],["他爱音乐，尤其爱古典音乐。","Tā ài yīnyuè, yóuqí ài gǔdiǎn yīnyuè.","Anh ấy yêu âm nhạc, nhất là nhạc cổ điển."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-132","hsk30_level":"7-9","official":["o-7-9-132"],"title":"语段：话题转换","py":"Yǔ duàn: huàtí zhuǎnhuàn","func":"语段（句群）","struct":"原话题 + 转折词 + 新话题","vi":"Chuyển chủ đề sang chủ đề mới.","use":"Dùng 对了, 说起…, 另外, 至于.","ex":[["对了，明天你有时间吗？","Duì le, míngtiān nǐ yǒushí jiān ma?","À này, mai bạn có rảnh không?"],["说到学习，我想起一件事。","Shuō dào xuéxí, wǒ xiǎngqǐ yī jiàn shì.","Nói đến học tập, tôi nhớ ra một chuyện."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-133","hsk30_level":"7-9","official":["o-7-9-133"],"title":"语段：承前省略","py":"Yǔ duàn: chéng qián shěnglu:è","func":"语段（句群）","struct":"前句已有成分，后句省略","vi":"Lược thành phần đã xuất hiện ở câu trước.","use":"Thường lược chủ ngữ.","ex":[["小王今天来了，(他)带了很多水果。","Xiǎo wáng jīntiān lái le, (tā)dài le hěn duō shuǐguǒ.","Tiểu Vương hôm nay đến, mang theo nhiều hoa quả."],["我买了书，(我)也买了笔。","Wǒ mǎi le shū, (wǒ)yě mǎi le bǐ.","Tôi mua sách, cũng mua bút."]],"note":"","origin":"hanziai-authored"},{"id":"a-o-7-9-134","hsk30_level":"7-9","official":["o-7-9-134"],"title":"语段：蒙后省略","py":"Yǔ duàn: méng hòu shěnglu:è","func":"语段（句群）","struct":"先省略，后句出现","vi":"Lược ở câu trước, thành phần xuất hiện ở câu sau.","use":"Ít gặp hơn 承前省略.","ex":[["(他)一进门，小李就笑了。","(Tā)yī jìn mén, xiǎo li jiù xiào le.","(Anh ấy) vừa vào cửa Tiểu Lý đã cười."],["(他们)刚到，老师就来了。","(Tāmen)gāng dào, lǎoshī jiù lái le.","(Họ) vừa đến thì thầy đã tới."]],"note":"","origin":"hanziai-authored"}];
